def is_human_readable_text(s: str) -> bool:
    """Checks if the string is clean human-readable text and not a protobuf/hash/hex dump or raw number."""
    if not s or not isinstance(s, str):
        return False
    s_clean = s.strip()
    if not s_clean:
        return False
    # Reject pure numeric STBL / Object instance hashes (e.g. "827498137", "0x123")
    if s_clean.isdigit():
        return False
    if any(bad in s_clean.lower() for bad in ["hash:", "tokens", "text_string", "{", "}", "0x", "<", "0b", "key:"]):
        return False
    return True


