def _detect_alien_disguise(sim_info) -> bool:
    """Returns True if Alien is in human disguise, False if in true alien form."""
    try:
        ot = getattr(sim_info, "occult_tracker", None)
        if ot is not None:
            try:
                from sims.occult.occult_enums import OccultType
                if hasattr(OccultType, "ALIEN") and hasattr(ot, "in_occult_form"):
                    return not bool(ot.in_occult_form(OccultType.ALIEN))
            except Exception:
                pass

        cot = getattr(sim_info, "current_occult_types", None)
        if cot is not None:
            try:
                from sims.occult.occult_enums import OccultType
                if hasattr(OccultType, "ALIEN") and hasattr(OccultType, "HUMAN"):
                    cot_int = int(cot)
                    if cot_int == int(OccultType.HUMAN):
                        return True
                    if cot_int & int(OccultType.ALIEN):
                        return False
            except Exception:
                pass

        if hasattr(sim_info, "get_buffs"):
            try:
                for b in sim_info.get_buffs():
                    b_name = getattr(getattr(b, "buff_type", b), "__name__", str(b)).lower()
                    if "disguis" in b_name:
                        return True
            except Exception:
                pass
    except Exception:
        pass
    return False


def _detect_werewolf_form(sim_info) -> bool:
    """Returns True if Werewolf is in beast/wolf form, False if in human form."""
    try:
        ot = getattr(sim_info, "occult_tracker", None)
        if ot is not None:
            try:
                from sims.occult.occult_enums import OccultType
                if hasattr(OccultType, "WEREWOLF") and hasattr(ot, "in_occult_form"):
                    return bool(ot.in_occult_form(OccultType.WEREWOLF))
            except Exception:
                pass

        if hasattr(sim_info, "get_traits"):
            try:
                for t in sim_info.get_traits():
                    t_name = getattr(t, "__name__", str(t)).lower()
                    if "wereform" in t_name or "werewolf_form" in t_name or "beastform" in t_name:
                        return True
            except Exception:
                pass

        if hasattr(sim_info, "get_buffs"):
            try:
                for b in sim_info.get_buffs():
                    b_name = getattr(getattr(b, "buff_type", b), "__name__", str(b)).lower()
                    if "werewolf_rampage" in b_name or "werewolf_wereform" in b_name:
                        return True
            except Exception:
                pass
    except Exception:
        pass
    return False


def is_werewolf_enraged(sim_info) -> bool:
    """
    Checks if a werewolf Sim is currently enraged / in rampage.
    If fury is 0-99, or if Sim is in human form, returns False.
    Only returns True if the werewolf is transformed into beast/wolf form AND actively rampaging or at 100% fury.
    """
    if sim_info is None:
        return False
    try:
        # 1. Check if the Sim is actually an occult werewolf
        is_werewolf = getattr(sim_info, "is_werewolf", False)
        if not is_werewolf:
            if hasattr(sim_info, "occult_tracker") and sim_info.occult_tracker is not None:
                try:
                    from sims.occult.occult_enums import OccultType
                    if hasattr(OccultType, "WEREWOLF") and hasattr(sim_info.occult_tracker, "has_occult_type"):
                        if sim_info.occult_tracker.has_occult_type(OccultType.WEREWOLF):
                            is_werewolf = True
                except Exception:
                    pass
            if not is_werewolf and hasattr(sim_info, "get_traits"):
                try:
                    for t in sim_info.get_traits():
                        t_name = getattr(t, "__name__", str(t)).lower()
                        if "trait_occultwerewolf" in t_name or "werewolf" in t_name:
                            is_werewolf = True
                            break
                except Exception:
                    pass

        if not is_werewolf:
            return False

        # 2. PREREQUISITE: A werewolf in rage/rampage is ALWAYS in beast/wolf form!
        # If the Sim is currently in human form, they are NEVER rampaging / in rage.
        in_wolf_form = _detect_werewolf_form(sim_info)
        if not in_wolf_form:
            return False

        # 3. In beast form, verify if they are truly in uncontrollable rage/rampage:
        # A. Check active Rampaging/Enraged emotion
        if hasattr(sim_info, "get_mood"):
            try:
                m = sim_info.get_mood()
                m_name = getattr(m, "__name__", str(m)).lower()
                if any(rk in m_name for rk in ["rampag", "enraged"]):
                    return True
            except Exception:
                pass

        # B. Check active Rampage buff (exclude tracker, controller, perk, immunity, temperament buffs)
        if hasattr(sim_info, "get_buffs"):
            try:
                for b in sim_info.get_buffs():
                    b_name = getattr(getattr(b, "buff_type", b), "__name__", str(b)).lower()
                    if any(ign in b_name for ign in ["tracker", "controller", "anti", "prevent", "immunity", "resistance", "perk", "cooldown", "temperament"]):
                        continue
                    if "werewolf_rampage" in b_name or b_name in ("buff_werewolf_rampage", "buff_werewolf_rampage_transformation"):
                        return True
            except Exception:
                pass

        # C. Check specifically commodity_Motive_Werewolf_Fury (must be at maximum 99.5 - 100)
        if hasattr(sim_info, "commodity_tracker") and sim_info.commodity_tracker is not None:
            try:
                for stat in list(sim_info.commodity_tracker):
                    s_type = getattr(stat, "stat_type", None) or type(stat)
                    type_name = getattr(s_type, "__name__", "").lower()
                    if type_name in ("commodity_motive_werewolf_fury", "motive_werewolf_fury") or ("werewolf_fury" in type_name and not any(ign in type_name for ign in ["max", "threshold", "glow", "active", "decay"])):
                        val = getattr(stat, "get_value", lambda: 0)()
                        if val >= 99.5:
                            return True
            except Exception:
                pass

    except Exception as e:
        log_exception("Error checking if werewolf is enraged", e)

    return False


def _detect_vampire_dark_form(sim_info) -> bool:
    """Returns True if Vampire is in Dark Form, False if in normal human appearance."""
    try:
        ot = getattr(sim_info, "occult_tracker", None)
        if ot is not None:
            try:
                from sims.occult.occult_enums import OccultType
                if hasattr(OccultType, "VAMPIRE") and hasattr(ot, "in_occult_form"):
                    return bool(ot.in_occult_form(OccultType.VAMPIRE))
            except Exception:
                pass

        if hasattr(sim_info, "get_traits"):
            try:
                for t in sim_info.get_traits():
                    t_name = getattr(t, "__name__", str(t)).lower()
                    if "darkform" in t_name or "dark_form" in t_name:
                        return True
            except Exception:
                pass
    except Exception:
        pass
    return False


def _detect_ghost_death_cause(sim_info, is_en: bool = False) -> str:
    """Determines the cause of death for a Ghost Sim in Russian or English."""
    death_key = ""
    try:
        dt = getattr(sim_info, "death_tracker", None)
        if dt is not None:
            raw_dtype = getattr(dt, "death_type", None) or getattr(dt, "_death_type", None)
            if raw_dtype is not None:
                death_key = getattr(raw_dtype, "name", str(raw_dtype)).lower()
    except Exception:
        pass

    ghost_trait_obj = None
    ghost_trait_name = ""
    try:
        if hasattr(sim_info, "get_traits"):
            for t in sim_info.get_traits():
                t_name = getattr(t, "__name__", str(t)).lower()
                is_g = getattr(t, "is_ghost_trait", False)
                try:
                    from traits.trait_enums import TraitType
                    if getattr(t, "trait_type", None) == TraitType.GHOST:
                        is_g = True
                except Exception:
                    pass
                if is_g or ("ghost" in t_name and ("death" in t_name or t_name.startswith("trait_ghost"))):
                    ghost_trait_obj = t
                    ghost_trait_name = t_name
                    break
    except Exception:
        pass

    # Check GHOST_DEATH_TRANSLATIONS dictionary for matching keywords
    search_keys = [death_key, ghost_trait_name]
    for key_candidate in search_keys:
        if not key_candidate:
            continue
        c_low = key_candidate.lower()
        for pat in sorted(GHOST_DEATH_TRANSLATIONS.keys(), key=len, reverse=True):
            if pat in c_low:
                ru_val, en_val = GHOST_DEATH_TRANSLATIONS[pat]
                return en_val if is_en else ru_val

    # Fallback: try reading localized trait display_name from game engine
    if ghost_trait_obj is not None:
        try:
            dn = getattr(ghost_trait_obj, "display_name", None)
            if dn is not None:
                if callable(dn):
                    dn = dn(sim_info)
                if LocalizationHelperTuning is not None:
                    raw_dn = LocalizationHelperTuning.get_raw_text(dn)
                    if raw_dn and is_human_readable_text(str(raw_dn)):
                        raw_s = str(raw_dn).strip()
                        cleaned = re.sub(r'^(?:смерть\s+от|погиб\s+от|death\s+by|died\s+of)\s+', '', raw_s, flags=re.IGNORECASE).strip()
                        if cleaned:
                            return cleaned.capitalize()
                        return raw_s
        except Exception:
            pass

    return "Unknown" if is_en else "Неизвестно"


def get_sim_occult_info(sim_info, is_en: bool = False) -> str:
    """Accurately identifies the Sim's species / occult race with live form and death details."""
    base_race = "Человек"
    try:
        # 1. Check Ghost first
        if getattr(sim_info, "is_ghost", False):
            base_race = "Призрак"
        elif getattr(sim_info, "is_robot", False) or getattr(sim_info, "is_humanoid_robot", False):
            base_race = "Робот (Серво)"
        elif getattr(sim_info, "is_vampire", False):
            base_race = "Вампир"
        elif getattr(sim_info, "is_werewolf", False):
            base_race = "Оборотень"
        elif getattr(sim_info, "is_mermaid", False):
            base_race = "Русалка"
        elif getattr(sim_info, "is_witch", False) or getattr(sim_info, "is_spellcaster", False):
            base_race = "Чародей / Маг"
        elif getattr(sim_info, "is_alien", False):
            base_race = "Инопланетянин (Пришелец)"
        else:
            # 2. Check Occult Tracker
            if hasattr(sim_info, "occult_tracker") and sim_info.occult_tracker is not None:
                try:
                    from sims.occult.occult_enums import OccultType
                    ot = sim_info.occult_tracker
                    if hasattr(OccultType, "ROBOT") and hasattr(ot, "has_occult_type") and ot.has_occult_type(OccultType.ROBOT):
                        base_race = "Робот (Серво)"
                    elif hasattr(OccultType, "VAMPIRE") and hasattr(ot, "has_occult_type") and ot.has_occult_type(OccultType.VAMPIRE):
                        base_race = "Вампир"
                    elif hasattr(OccultType, "WEREWOLF") and hasattr(ot, "has_occult_type") and ot.has_occult_type(OccultType.WEREWOLF):
                        base_race = "Оборотень"
                    elif hasattr(OccultType, "MERMAID") and hasattr(ot, "has_occult_type") and ot.has_occult_type(OccultType.MERMAID):
                        base_race = "Русалка"
                    elif hasattr(OccultType, "WITCH") and hasattr(ot, "has_occult_type") and ot.has_occult_type(OccultType.WITCH):
                        base_race = "Чародей / Маг"
                    elif hasattr(OccultType, "ALIEN") and hasattr(ot, "has_occult_type") and ot.has_occult_type(OccultType.ALIEN):
                        base_race = "Инопланетянин (Пришелец)"
                except Exception:
                    pass

            if base_race == "Человек":
                # 3. Check traits for occults
                traits = []
                if hasattr(sim_info, "get_traits"):
                    try:
                        traits = [getattr(t, "__name__", str(t)).lower() for t in sim_info.get_traits()]
                    except Exception:
                        pass
                for t_name in traits:
                    if any(ign in t_name for ign in ["preference", "likes", "dislikes", "fear", "skill", "buff", "flavor", "lore"]):
                        continue
                    if t_name in ("trait_humanoid_robot_main", "trait_humanoid_robot", "trait_humanoidrobot") or t_name.startswith("trait_humanoid_robot"):
                        base_race = "Робот (Серво)"
                        break
                    if t_name in ("trait_occultvampire", "trait_occult_vampire") or t_name.startswith("trait_occult_vampire"):
                        base_race = "Вампир"
                        break
                    if t_name in ("trait_occultwerewolf", "trait_occult_werewolf") or t_name.startswith("trait_occult_werewolf"):
                        base_race = "Оборотень"
                        break
                    if t_name in ("trait_occultmermaid", "trait_occult_mermaid") or t_name.startswith("trait_occult_mermaid"):
                        base_race = "Русалка"
                        break
                    if t_name in ("trait_occult_witch", "trait_occultwitch", "trait_occult_spellcaster") or t_name.startswith("trait_occult_witch"):
                        base_race = "Чародей / Маг"
                        break
                    if t_name in ("trait_occultalien", "trait_occult_alien") or t_name.startswith("trait_occult_alien"):
                        base_race = "Инопланетянин (Пришелец)"
                        break
                    if t_name in ("trait_planthood", "trait_plantsim", "trait_plantsim_challenge") or "plantsim" in t_name or "planthood" in t_name:
                        base_race = "Ростоман"
                        break
                    if t_name in ("trait_hidden_skeleton", "trait_skeleton"):
                        base_race = "Скелет"
                        break
                    if t_name.startswith("trait_ghost"):
                        base_race = "Призрак"
                        break

            # 4. Fallback check for temporary occult buffs (e.g. PlantSim buff)
            if base_race == "Человек":
                try:
                    active_buffs = get_all_sim_buffs(sim_info)
                    for b in active_buffs:
                        b_type = getattr(b, "buff_type", None) or type(b)
                        b_name = getattr(b_type, "__name__", str(b)).lower()
                        if "plantsim" in b_name or "planthood" in b_name:
                            base_race = "Ростоман"
                            break
                except Exception:
                    pass
    except Exception as e:
        log_exception("Error getting sim occult info", e)

    # 4. Enhance with live form / death details
    if base_race == "Инопланетянин (Пришелец)":
        is_disguised = _detect_alien_disguise(sim_info)
        if is_en:
            return "Alien [In Human Disguise]" if is_disguised else "Alien [True Alien Form (Undisguised)]"
        else:
            return "Инопланетянин (Пришелец) [В маскировке под человека]" if is_disguised else "Инопланетянин (Пришелец) [Истинный облик (без маскировки)]"

    elif base_race == "Оборотень":
        in_wolf_form = _detect_werewolf_form(sim_info)
        if is_en:
            return "Werewolf [In Beast / Wolf Form]" if in_wolf_form else "Werewolf [In Human Form]"
        else:
            return "Оборотень [В форме волка (звериный облик)]" if in_wolf_form else "Оборотень [В человеческом облике]"

    elif base_race == "Вампир":
        in_dark_form = _detect_vampire_dark_form(sim_info)
        if is_en:
            return "Vampire [In Dark Form]" if in_dark_form else "Vampire [In Normal Form]"
        else:
            return "Вампир [В тёмной форме]" if in_dark_form else "Вампир [В обычном облике]"

    elif base_race == "Призрак":
        death_cause = _detect_ghost_death_cause(sim_info, is_en=is_en)
        if death_cause:
            return f"Ghost [Cause of death: {death_cause}]" if is_en else f"Призрак [Причина смерти: {death_cause}]"
        return "Ghost" if is_en else "Призрак"

    elif base_race == "Ростоман":
        if is_en:
            return "PlantSim (human-plant hybrid: photosynthesizes in sunlight, absorbs water instead of regular food, loves nature, wilts without moisture)"
        else:
            return "Ростоман (человек-растение: фотосинтезирует на солнце, вместо обычной еды поглощает солнечный свет и воду, любит природу, вянет без влаги)"

    if is_en:
        en_base_map = {
            "Человек": "Human",
            "Робот (Серво)": "Robot (Servo)",
            "Русалка": "Mermaid",
            "Чародей / Маг": "Spellcaster",
            "Ростоман": "PlantSim",
            "Скелет": "Skeleton",
        }
        return en_base_map.get(base_race, base_race)

    return base_race


