CAREER_LEVEL_TITLES["athletic"] = CAREER_LEVEL_TITLES["athlete"]


def get_career_level_title_and_desc(car_name: str, track_name: str, level_name: str, level: int):
    """Resolves specific job title and description for a career, branch and level."""
    try:
        car_key = (car_name or "").lower()
        track_key = (track_name or "").lower()
        lvl_key = (level_name or "").lower()
        
        for k, v in CAREER_LEVEL_TITLES.items():
            if k in car_key:
                # 1. Check branch if track or level tuning matches branch name
                for branch_key, branch_val in v.items():
                    if isinstance(branch_val, dict):
                        if branch_key in track_key or branch_key in lvl_key:
                            if level in branch_val:
                                return branch_val[level]
                # 2. Check direct level in career dict
                if level in v and isinstance(v[level], tuple):
                    return v[level]
                # 3. Fallback: check all branches if level matches
                for branch_key, branch_val in v.items():
                    if isinstance(branch_val, dict) and level in branch_val:
                        return branch_val[level]
    except Exception:
        pass
    return None


