def _extract_crafting_title(obj):
    if obj is None:
        return ""
    for attr in ["_custom_name", "custom_name", "title", "_title", "name", "_name"]:
        val = getattr(obj, attr, None)
        if isinstance(val, str) and val.strip() and not any(bad in val for bad in ["hash:", "tokens", "{", "}", "0x", "Object", "Interaction", "None"]):
            clean_val = val.strip()
            if len(clean_val) > 1 and not clean_val.startswith("computer_") and not clean_val.startswith("recipe_"):
                return clean_val
    for method_name in ["get_custom_name", "get_name", "custom_name"]:
        if hasattr(obj, method_name) and callable(getattr(obj, method_name)):
            try:
                res = getattr(obj, method_name)()
                if isinstance(res, str) and res.strip() and not any(bad in res for bad in ["hash:", "tokens", "{", "}", "0x", "Object", "Interaction", "None"]):
                    clean_res = res.strip()
                    if len(clean_res) > 1 and not clean_res.startswith("computer_") and not clean_res.startswith("recipe_"):
                        return clean_res
            except Exception:
                pass
    return ""


def extract_written_book_details(interactions_list, full_context_text: str) -> str:
    """Extracts exact genre and title for a book being written on a computer."""
    found_genre = ""
    found_title = ""
    candidate_tokens = []

    for inter in interactions_list:
        n = getattr(inter, "__name__", str(inter)).lower()
        candidate_tokens.append(n)

        tgt = getattr(inter, "target", None)
        if tgt is not None:
            candidate_tokens.append(getattr(tgt, "__name__", str(tgt)).lower())

        # Check crafting process on interaction or target
        proc = None
        for obj in [inter, tgt]:
            if obj is None:
                continue
            if hasattr(obj, "get_crafting_process") and callable(getattr(obj, "get_crafting_process")):
                try:
                    proc = obj.get_crafting_process()
                    if proc is not None:
                        break
                except Exception:
                    pass
            if hasattr(obj, "crafting_process") and getattr(obj, "crafting_process") is not None:
                proc = getattr(obj, "crafting_process")
                break

        if proc is not None:
            # Check recipe on crafting process
            if hasattr(proc, "recipe") and proc.recipe is not None:
                candidate_tokens.append(getattr(proc.recipe, "__name__", str(proc.recipe)).lower())
            # Check title on crafting process or crafted object
            if not found_title:
                found_title = _extract_crafting_title(proc)
            if not found_title and hasattr(proc, "crafted_value"):
                found_title = _extract_crafting_title(getattr(proc, "crafted_value"))

        # Check direct recipe on interaction
        if hasattr(inter, "recipe") and inter.recipe is not None:
            candidate_tokens.append(getattr(inter.recipe, "__name__", str(inter.recipe)).lower())

    joined_tokens = (" ".join(candidate_tokens) + " " + full_context_text).replace("_", "").lower()

    # Find matching genre
    for kw_list, g_desc in BOOK_WRITING_GENRES:
        for kw in kw_list:
            if kw.replace("_", "").lower() in joined_tokens:
                found_genre = g_desc
                break
        if found_genre:
            break

    if not found_genre:
        found_genre = "книгу / роман"

    if found_title:
        return f"Пишет {found_genre} под названием «{found_title}» на компьютере"
    return f"Пишет {found_genre} на компьютере"


def get_computer_action_details(interactions_list, full_context_text: str) -> str:
    """Analyzes all computer/laptop interactions and returns the specific activity."""
    # 1. Check if writing a book/text first
    for inter in interactions_list:
        n = getattr(inter, "__name__", str(inter)).lower()
        if "write" in n or "novel" in n or "book" in n or any(g in n for g in ["fantasy", "scifi", "mystery", "romance", "biography", "poetry", "screenplay", "children"]):
            if "writejoke" in n or "comedy" in n:
                return "Сочиняет шутки для стендапа на компьютере"
            if "writearticle" in n or "journalism" in n or "column" in n:
                return "Пишет журналистскую статью / расследование"
            if "writeexcuse" in n or "forgedexcuse" in n:
                return "Подделывает объяснительную записку на компьютере"
            if "writeloveletter" in n or "loveletter" in n:
                return "Пишет любовное письмо на компьютере"
            if "postblog" in n or "writeblog" in n or "blog" in n:
                return "Пишет заметку в свой личный блог"
            if "publishbook" in n or "submittopublisher" in n:
                return "Отправляет рукопись книги в издательство"
            return extract_written_book_details(interactions_list, full_context_text)

    # 2. Check all individual interactions in order of priority
    for inter in interactions_list:
        n = getattr(inter, "__name__", str(inter)).lower()
        tgt = getattr(inter, "target", None)
        t = getattr(tgt, "__name__", str(tgt)).lower() if tgt else ""
        combined = f"{n} {t}".replace("_", "").lower()

        # Check video games on PC first
        if "videogame" in n or "gaming" in n or "game" in n:
            for g_key, g_val in VIDEO_GAMES:
                if g_key.replace("_", "").lower() in combined:
                    return g_val
            if "tournament" in combined:
                return "Участвует в киберспортивном игровом турнире"
            if "livestream" in combined or "stream" in combined:
                return "Ведет стрим видеоигры для зрителей"
            if any(k in combined for k in ["playgame", "playvideogame", "gameplay"]):
                return "Играет в видеоигру на компьютере"

        # Check all specific computer actions
        for keywords, desc in COMPUTER_ACTIONS:
            for kw in keywords:
                clean_kw = kw.replace("_", "").lower()
                if clean_kw in combined:
                    return desc

    # 3. Check full context string across all interactions
    for keywords, desc in COMPUTER_ACTIONS:
        for kw in keywords:
            clean_kw = kw.replace("_", "").lower()
            if clean_kw in full_context_text:
                return desc

    return "Сидит за компьютером"


def _extract_music_genre(text: str) -> str:
    """Extracts Russian descriptive name for music station / genre."""
    t = text.lower().replace("_", "")
    if "alternative" in t:
        return "альтернативный рок / инди"
    if "metal" in t or "heavymetal" in t:
        return "хэви-метал / тяжёлый рок"
    if "rock" in t:
        return "рок-музыку"
    if "pop" in t and "spop" not in t and "tweenpop" not in t:
        return "поп-музыку"
    if "spop" in t or "jpop" in t:
        return "японский поп (S-Pop)"
    if "tweenpop" in t:
        return "молодёжный тин-поп"
    if "classical" in t or "classic" in t:
        return "классическую музыку"
    if "baroque" in t:
        return "музыку эпохи барокко"
    if "blues" in t:
        return "блюз"
    if "jazz" in t:
        return "джаз"
    if "electronica" in t or "electronic" in t or "edm" in t:
        return "электронную музыку (EDM)"
    if "hiphop" in t or "hip_hop" in t or "urban" in t:
        return "хип-хоп / рэп"
    if "spooky" in t:
        return "жуткую готическую музыку"
    if "latin" in t:
        return "латиноамериканскую музыку"
    if "reggae" in t or "island" in t:
        return "островные ритмы / регги"
    if "country" in t or "bluegrass" in t:
        return "кантри-музыку"
    if "carnival" in t:
        return "карнавальную музыку"
    if "focus" in t or "ambient" in t:
        return "музыку для концентрации"
    if "singersongwriter" in t or "acoustic" in t:
        return "акустические авторские песни"
    if "romance" in t or "romantic" in t:
        return "романтическую музыку"
    if "retro" in t:
        return "ретро-хиты"
    if "disco" in t or "nudisco" in t:
        return "диско-музыку"
    if "kids" in t:
        return "детские песенки"
    if "lullaby" in t or "lullabies" in t:
        return "колыбельную музыку"
    if "holiday" in t or "winter" in t:
        return "новогоднюю праздничную музыку"
    if "summer" in t or "backyard" in t:
        return "летние дачные мотивы"
    if "world" in t:
        return "этническую музыку мира"
    if "cottage" in t or "folklore" in t:
        return "деревенские народные мотивы"
    return "музыку"


def get_microphone_action_details(interactions_list, full_context_text: str) -> str:
    """Analyzes all microphone / karaoke / singing interactions across all running affordances."""
    all_tokens = []
    for inter in interactions_list:
        n = getattr(inter, "__name__", str(inter)).lower()
        all_tokens.append(n)
        tgt = getattr(inter, "target", None)
        if tgt is not None:
            all_tokens.append(getattr(tgt, "__name__", str(tgt)).lower())

    joined = (" ".join(all_tokens) + " " + full_context_text).replace("_", "").lower()

    # Guard: If any musical instrument is involved, it should never be diagnosed as microphone/singing!
    if any(inst in joined for inst in ["pipeorgan", "organ", "piano", "keyboard", "guitar", "violin"]):
        if "pipeorgan" in joined or "organ" in joined:
            return "Играет на органе"
        if "piano" in joined or "keyboard" in joined:
            return "Играет на пианино"
        if "guitar" in joined:
            return "Играет на гитаре"
        if "violin" in joined:
            return "Играет на скрипке"

    # 1. Рассказывание анекдотов, стендап, комедия (Telling Jokes / Stand-Up Comedy)
    if any(k in joined for k in ["telljoke", "telljokes", "joke", "jokes", "comedy", "standup", "routine", "funny", "humor", "anecdote", "standupcomedy"]):
        if any(p in joined for p in ["perform", "performroutine", "show", "stage", "crowd"]):
            return "Выступает со стендап-комедией у микрофона (рассказывает шутки публике)"
        return "Рассказывает анекдоты и шутки в микрофон (стендап)"

    # 2. Пение, вокал, караоке (Singing & Vocals)
    # Use strict patterns to prevent false positives from words like 'rehearsing', 'browsing', 'cleansing'
    has_singing = any(k in joined for k in ["singing", "vocal", "vocalize", "ballad", "karaoke", "practicesing"]) or any(re.search(r'\bsing\b', tok) for tok in all_tokens)
    if has_singing:
        if any(p in joined for p in ["practice", "practicing", "exercises", "train"]):
            return "Упражняется в пении / тренирует вокал у микрофона"
        if "karaoke" in joined:
            return "Поет песню в караоке"
        return "Поет песню в микрофон"

    # 3. Речь, дебаты, ораторское искусство (Speech & Debate)
    if any(k in joined for k in ["speech", "debate", "oration", "story", "toast", "preach"]):
        if any(p in joined for p in ["practice", "practicing"]):
            return "Тренирует ораторское искусство и речь у микрофона"
        return "Произносит торжественную речь / тост у микрофона"

    # 4. Общее выступление перед публикой
    if any(k in joined for k in ["perform", "show", "entertain"]):
        return "Выступает перед публикой у микрофона"

    return "Выступает / упражняется у микрофона"


