def _match_world_name_ru(text: str) -> str:
    """Helper to match a raw string (region name, neighborhood name, tuning name) to WORLD_NAMES_RU."""
    if not text:
        return ""
    clean = str(text).lower().replace("_", "").replace(" ", "").replace("-", "")
    for w_key, w_val in sorted(WORLD_NAMES_RU.items(), key=lambda x: len(x[0]), reverse=True):
        clean_key = w_key.replace("_", "").replace(" ", "").replace("-", "")
        if clean_key in clean:
            return w_val
    return ""


def get_current_world_name() -> str:
    """Extracts current World / City name (e.g. 'Виллоу Крик', 'Сан Мишуно', 'Сулани')."""
    try:
        if services is not None:
            # 1. Primary & fastest: services.current_region()
            try:
                current_reg = services.current_region()
                if current_reg is not None:
                    reg_name = getattr(current_reg, "__name__", "") or str(current_reg)
                    match = _match_world_name_ru(reg_name)
                    if match:
                        return match

                    match_type = _match_world_name_ru(type(current_reg).__name__)
                    if match_type:
                        return match_type

                    loc_name = getattr(current_reg, "region_name", None) or getattr(current_reg, "display_name", None)
                    if loc_name:
                        from sims4.localization import LocalizationHelperTuning
                        if LocalizationHelperTuning is not None:
                            raw_t = LocalizationHelperTuning.get_raw_text(loc_name)
                            if raw_t:
                                return str(raw_t)
            except Exception:
                pass

            current_zone = services.current_zone()
            if current_zone is not None:
                persistence = services.get_persistence_service()
                if persistence is not None:
                    # 2. Try Neighborhood proto buff
                    n_id = getattr(current_zone, "neighborhood_id", 0)
                    if n_id:
                        get_n_pb = getattr(persistence, "get_neighborhood_proto_buff", None) or getattr(persistence, "get_neighborhood_proto_by_id", None)
                        if get_n_pb is not None:
                            n_proto = get_n_pb(n_id)
                            if n_proto is not None:
                                n_name = getattr(n_proto, "name", "")
                                match = _match_world_name_ru(n_name)
                                if match:
                                    return match
                                reg_id = getattr(n_proto, "region_id", 0)
                                if reg_id:
                                    import sims4.resources
                                    mgr = services.get_instance_manager(sims4.resources.Types.REGION)
                                    if mgr is not None:
                                        reg_tuning = mgr.get(reg_id)
                                        if reg_tuning is not None:
                                            match = _match_world_name_ru(getattr(reg_tuning, "__name__", ""))
                                            if match:
                                                return match

                    # 3. Try World proto buff
                    w_id = getattr(current_zone, "world_id", 0)
                    if w_id:
                        get_w_pb = getattr(persistence, "get_world_proto_buff", None) or getattr(persistence, "get_world_proto_by_id", None)
                        if get_w_pb is not None:
                            w_proto = get_w_pb(w_id)
                            if w_proto is not None:
                                w_name = getattr(w_proto, "name", "")
                                match = _match_world_name_ru(w_name)
                                if match:
                                    return match

                    # 4. Try Zone proto buff
                    get_z_pb = getattr(persistence, "get_zone_proto_buff", None)
                    if get_z_pb:
                        zone_proto = get_z_pb(current_zone.id)
                        if zone_proto is not None:
                            match = _match_world_name_ru(getattr(zone_proto, "name", ""))
                            if match:
                                return match

                # 5. Try world_description tuning
                try:
                    import sims4.resources
                    w_desc_id = getattr(current_zone, "world_description_id", 0)
                    if w_desc_id:
                        mgr = services.get_instance_manager(sims4.resources.Types.WORLD_DESCRIPTION)
                        if mgr is not None:
                            w_tuning = mgr.get(w_desc_id)
                            if w_tuning is not None:
                                match = _match_world_name_ru(getattr(w_tuning, "__name__", ""))
                                if match:
                                    return match
                                loc_name = getattr(w_tuning, "world_name", None) or getattr(w_tuning, "display_name", None)
                                if loc_name:
                                    from sims4.localization import LocalizationHelperTuning
                                    if LocalizationHelperTuning is not None:
                                        raw_t = LocalizationHelperTuning.get_raw_text(loc_name)
                                        if raw_t:
                                            return str(raw_t)
                except Exception:
                    pass

            # 6. Venue type fallback for uniquely located venues
            try:
                venue_service = services.venue_service()
                active_venue = venue_service.active_venue if venue_service else None
                v_name = getattr(active_venue, "__name__", str(active_venue)).lower() if active_venue else ""
                if "beach" in v_name:
                    return "Сулани"
                if "onsen" in v_name:
                    return "Гора Комореби"
                if "vampire" in v_name:
                    return "Форготн Холлоу"
            except Exception:
                pass
    except Exception as e:
        log_exception("Error getting current world name", e)

    return ""


def get_sim_home_world_name(sim_info) -> str:
    """Extracts the home World / City name for a Sim if known."""
    try:
        if services is not None and sim_info is not None:
            household = getattr(sim_info, "household", None)
            if household is None and hasattr(sim_info, "household_id"):
                hh_mgr = services.household_manager()
                if hh_mgr is not None:
                    try:
                        household = hh_mgr.get(sim_info.household_id)
                    except Exception:
                        household = None
            home_zone_id = getattr(household, "home_zone_id", 0) if household else 0
            if home_zone_id:
                persistence = services.get_persistence_service()
                if persistence is not None:
                    get_zone_pb = getattr(persistence, "get_zone_proto_buff", None) or getattr(persistence, "get_zone_proto_by_id", None)
                    zone_proto = get_zone_pb(home_zone_id) if get_zone_pb is not None else None
                    if zone_proto is not None:
                        n_id = getattr(zone_proto, "neighborhood_id", 0)
                        if n_id:
                            get_n_pb = getattr(persistence, "get_neighborhood_proto_buff", None) or getattr(persistence, "get_neighborhood_proto_by_id", None)
                            if get_n_pb is not None:
                                n_proto = get_n_pb(n_id)
                                if n_proto is not None:
                                    match = _match_world_name_ru(getattr(n_proto, "name", ""))
                                    if match:
                                        return match
                                    reg_id = getattr(n_proto, "region_id", 0)
                                    if reg_id:
                                        import sims4.resources
                                        mgr = services.get_instance_manager(sims4.resources.Types.REGION)
                                        if mgr is not None:
                                            reg_tuning = mgr.get(reg_id)
                                            if reg_tuning is not None:
                                                match = _match_world_name_ru(getattr(reg_tuning, "__name__", ""))
                                                if match:
                                                    return match
                        w_id = getattr(zone_proto, "world_id", 0)
                        if w_id:
                            get_w_pb = getattr(persistence, "get_world_proto_buff", None) or getattr(persistence, "get_world_proto_by_id", None)
                            if get_w_pb is not None:
                                w_proto = get_w_pb(w_id)
                                if w_proto is not None:
                                    match = _match_world_name_ru(getattr(w_proto, "name", ""))
                                    if match:
                                        return match
    except Exception as e:
        log_exception("Error getting sim home world name", e)
    return ""


