def is_sim_physically_outside(sim_info) -> bool:
    """Checks if the Sim is currently outdoors in open air or inside enclosed walls."""
    try:
        sim_instance = sim_info.get_sim_instance() if hasattr(sim_info, "get_sim_instance") else None
        if sim_instance is not None:
            # 1. Room ID property (0 = outdoors / no room, >0 = indoors in a room)
            room_id = getattr(sim_instance, "room_id", None)
            if room_id is not None:
                return room_id == 0

            # 2. Direct property/method on GameObject / Sim
            if hasattr(sim_instance, "is_outside"):
                val = sim_instance.is_outside
                if callable(val):
                    return bool(val())
                return bool(val)

            # 3. Location and build_buy room query
            if hasattr(sim_instance, "location") and services is not None:
                try:
                    pos = sim_instance.location.transform.translation
                    level = getattr(sim_instance.location, "level", 0)
                    zone_id = services.current_zone_id()
                    import build_buy
                    room_id = build_buy.get_room_id(zone_id, pos, level)
                    return room_id == 0
                except Exception:
                    pass
    except Exception as e:
        log_exception("Error checking if sim is outside", e)

    return False


def get_current_location(sim_info) -> str:
    """
    Accurately identifies the Sim's spatial location:
    - If off-lot (sim_instance is None): 'Находится на другом участке' (without inside/outside)
    - At home: 'У себя дома (в помещении)' vs 'Возле своего дома / во дворе'
    - At residential/neighbor: 'В гостях (внутри чужого дома)' vs 'На улице в жилом районе / гуляет возле дома'
    - At public venue: 'В спортзале (внутри здания)' vs 'На улице возле спортзала / в районе'
    - Open parks/beaches: 'В городском парке (на свежем воздухе)'
    """
    try:
        sim_instance = sim_info.get_sim_instance() if hasattr(sim_info, "get_sim_instance") else None
        if sim_instance is None:
            home_world = get_sim_home_world_name(sim_info)
            if home_world:
                from ai_thought_reader.config import get_experimental_flag
                if get_experimental_flag("enhanced_world_descriptions"):
                    desc = WORLD_DESCRIPTIONS_RU.get(home_world, "")
                    if desc:
                        return f"Находится на другом участке (г. {home_world} — {desc})"
                return f"Находится на другом участке (г. {home_world})"
            return "Находится на другом участке"

        loc_desc = "У себя дома"
        is_outside = is_sim_physically_outside(sim_info)

        if services is not None:
            current_zone = services.current_zone()
            if current_zone is not None:
                # 1. Determine household and ownership
                sim_hh_id = getattr(sim_info, "household_id", 0)
                household = getattr(sim_info, "household", None)
                if household is None and sim_hh_id:
                    hh_mgr = services.household_manager()
                    if hh_mgr is not None:
                        try:
                            household = hh_mgr.get(sim_hh_id)
                        except Exception:
                            household = None
                if not sim_hh_id and household:
                    sim_hh_id = getattr(household, "id", 0)

                lot = getattr(current_zone, "lot", None)
                lot_owner_hh_id = getattr(lot, "owner_household_id", 0) if lot else 0
                if not lot_owner_hh_id and lot and hasattr(lot, "get_household_owner_id"):
                    try:
                        lot_owner_hh_id = lot.get_household_owner_id()
                    except Exception:
                        lot_owner_hh_id = 0

                home_zone_id = getattr(household, "home_zone_id", 0) if household else 0
                current_zone_id = getattr(current_zone, "id", 0) or (services.current_zone_id() if hasattr(services, "current_zone_id") else 0)

                active_hh_id = services.active_household_id() if hasattr(services, "active_household_id") else 0
                is_owner_active = False
                if lot and hasattr(lot, "is_owner_household_active"):
                    try:
                        is_owner_active = lot.is_owner_household_active()
                    except Exception:
                        is_owner_active = False

                # Check is_home_lot
                is_home_lot = False
                if sim_hh_id and lot_owner_hh_id and sim_hh_id == lot_owner_hh_id:
                    is_home_lot = True
                elif home_zone_id and current_zone_id and home_zone_id == current_zone_id:
                    is_home_lot = True
                elif is_owner_active and sim_hh_id and active_hh_id and sim_hh_id == active_hh_id:
                    is_home_lot = True

                venue_service = services.venue_service()
                active_venue = venue_service.active_venue if venue_service else None
                v_name = getattr(active_venue, "__name__", str(active_venue)).lower() if active_venue else ""
                is_residential = ("residential" in v_name or "apartment" in v_name or "penthouse" in v_name or not v_name)

                # Check if instantiated sim is strictly within lot boundary
                is_on_lot = True
                if hasattr(sim_instance, "is_on_active_lot"):
                    try:
                        is_on_lot = sim_instance.is_on_active_lot()
                    except Exception:
                        is_on_lot = True

                # Room ID extra safeguard: if room_id > 0, unconditionally indoors
                room_id = getattr(sim_instance, "room_id", 0)
                if room_id > 0:
                    is_outside = False

                # 1. Sim is on their own home lot
                if is_home_lot:
                    if is_outside:
                        loc_desc = "Возле своего дома / во дворе"
                    else:
                        loc_desc = "У себя дома (в помещении)"

                # 2. Sim is on a residential lot (other Sim's house or neighborhood street)
                elif is_residential:
                    if not is_on_lot or is_outside:
                        loc_desc = "На улице в жилом районе / гуляет возле дома"
                    else:
                        loc_desc = "В гостях (внутри чужого дома)"

                # 3. Sim is at a public venue (Gym, Bar, Park, Cafe, etc.)
                else:
                    venue_base_name = None
                    v_key_matched = None
                    for v_key, v_val in VENUE_TRANSLATIONS.items():
                        if v_key in v_name:
                            venue_base_name = v_val
                            v_key_matched = v_key
                            break

                    if not venue_base_name:
                        venue_base_name = "В общественном месте"

                    # Naturally outdoor venue (parks, beaches)
                    if any(ov in v_name for ov in OUTDOOR_ONLY_VENUES):
                        loc_desc = f"{venue_base_name} (на свежем воздухе)"
                    else:
                        if is_outside:
                            gen_name = VENUE_GENITIVE.get(v_key_matched, "заведения")
                            loc_desc = f"На улице возле {gen_name} / в районе"
                        else:
                            loc_desc = f"{venue_base_name} (внутри здания)"

        city_name = get_current_world_name()
        if city_name:
            from ai_thought_reader.config import get_experimental_flag
            if get_experimental_flag("enhanced_world_descriptions"):
                desc = WORLD_DESCRIPTIONS_RU.get(city_name, "")
                if desc:
                    return f"{loc_desc} (г. {city_name} — {desc})"
            return f"{loc_desc} (г. {city_name})"
        return loc_desc
    except Exception as e:
        log_exception("Error getting current location", e)

    return "Находится на другом участке"


def get_sim_career_info(sim_info) -> str:
    """Extracts the Sim's career, exact job title and position description."""
    try:
        if hasattr(sim_info, "career_tracker") and sim_info.career_tracker is not None:
            careers = getattr(sim_info.career_tracker, "careers", {})
            if careers:
                career_entries = []
                for career in careers.values():
                    cls_obj = getattr(career, "__class__", None)
                    cls_name = getattr(cls_obj, "__name__", "") if cls_obj else ""
                    raw_name = getattr(career, "__name__", "") or cls_name or str(career)
                    if " on " in raw_name:
                        raw_name = raw_name.split(" on ")[0]
                    raw_name = raw_name.strip("<> ")
                    c_name = raw_name.lower()
                    c_level = getattr(career, "user_level", 1)

                    track_name = ""
                    if hasattr(career, "current_track_tuning") and career.current_track_tuning:
                        track_name = getattr(career.current_track_tuning, "__name__", "") or ""
                    level_name = ""
                    if hasattr(career, "current_level_tuning") and career.current_level_tuning:
                        level_name = getattr(career.current_level_tuning, "__name__", "") or ""

                    # Find broad career translation
                    career_title = None
                    for car_key, car_val in CAREER_TRANSLATIONS.items():
                        if car_key in c_name:
                            career_title = car_val
                            break
                    if not career_title:
                        clean_c = c_name.replace("career_", "").replace("adult_", "").replace("teen_", "").replace("child_", "").strip()
                        if clean_c.endswith(" on"):
                            clean_c = clean_c[:-3].strip()
                        career_title = clean_c.capitalize()

                    # Find specific job position title & description
                    job_info = get_career_level_title_and_desc(c_name, track_name, level_name, c_level)
                    if job_info:
                        job_title, job_desc = job_info
                        if job_desc:
                            career_entries.append(f"{career_title} — Должность: «{job_title}» (Уровень {c_level}: {job_desc})")
                        else:
                            career_entries.append(f"{career_title} — Должность: «{job_title}» (Уровень {c_level})")
                    else:
                        career_entries.append(f"{career_title} (Уровень {c_level})")

                if career_entries:
                    return "; ".join(career_entries)
    except Exception as e:
        log_exception("Error getting sim career", e)

    return "Безработный"



