def get_sim_aspiration_info(sim_info) -> str:
    """Extracts the Sim's active aspiration / primary life goal."""
    try:
        if hasattr(sim_info, "aspiration_tracker") and sim_info.aspiration_tracker is not None:
            asp_tracker = sim_info.aspiration_tracker
            active_asp = getattr(asp_tracker, "active_aspiration", None)
            if active_asp is None and hasattr(asp_tracker, "get_active_aspiration"):
                active_asp = asp_tracker.get_active_aspiration()

            active_track = getattr(asp_tracker, "active_track", None)

            # 1. Try localized string directly from game engine tuning (supports RU, EN, and all languages natively)
            if LocalizationHelperTuning is not None:
                for obj in [active_track, active_asp]:
                    if obj is not None:
                        display_n = getattr(obj, "display_name", None) or getattr(obj, "name", None)
                        if display_n is not None:
                            try:
                                raw_t = LocalizationHelperTuning.get_raw_text(display_n)
                                if raw_t and str(raw_t).strip():
                                    return str(raw_t).strip()
                            except Exception:
                                pass

            # 2. Match by internal name on track and aspiration (longer keys first for precision)
            sorted_asp_keys = sorted(ASPIRATION_TRANSLATIONS.keys(), key=len, reverse=True)
            for obj in [active_track, active_asp]:
                if obj is not None:
                    obj_name = getattr(obj, "__name__", str(obj)).lower()
                    for ak in sorted_asp_keys:
                        if ak in obj_name:
                            return ASPIRATION_TRANSLATIONS[ak]

            # 3. Try localized string if available as plain string
            for obj in [active_track, active_asp]:
                if obj is not None:
                    display_n = getattr(obj, "display_name", None) or getattr(obj, "name", None)
                    if display_n and isinstance(display_n, str) and not display_n.startswith("0x") and not display_n.startswith("<"):
                        return display_n

            # 4. Clean fallback
            for obj in [active_asp, active_track]:
                if obj is not None:
                    obj_name = getattr(obj, "__name__", str(obj)).lower()
                    clean = obj_name.replace("aspiration_", "").replace("track_", "").replace("_", " ").capitalize()
                    if clean and clean != "None":
                        return clean

        # Try primary aspiration on sim_info
        if hasattr(sim_info, "primary_aspiration"):
            prim = getattr(sim_info, "primary_aspiration", None)
            if prim:
                if LocalizationHelperTuning is not None:
                    display_n = getattr(prim, "display_name", None) or getattr(prim, "name", None)
                    if display_n is not None:
                        try:
                            raw_t = LocalizationHelperTuning.get_raw_text(display_n)
                            if raw_t and str(raw_t).strip():
                                return str(raw_t).strip()
                        except Exception:
                            pass
                p_name = getattr(prim, "__name__", str(prim)).lower()
                sorted_asp_keys = sorted(ASPIRATION_TRANSLATIONS.keys(), key=len, reverse=True)
                for ak in sorted_asp_keys:
                    if ak in p_name:
                        return ASPIRATION_TRANSLATIONS[ak]
    except Exception as e:
        log_exception("Error getting sim aspiration", e)

    return "Не выбрана"


def get_household_funds_info(sim_info) -> str:
    """Extracts the household funds / budget in Simoleons with financial status."""
    try:
        household = getattr(sim_info, "household", None)
        if household is not None and hasattr(household, "funds"):
            money = int(household.funds.money)
            formatted_money = f"{money:,}".replace(",", " ")

            if money < 1000:
                status = "Мало денег / Бедность"
            elif money < 15000:
                status = "Скромный достаток"
            elif money < 80000:
                status = "Хороший достаток"
            else:
                status = "Богатство"

            return f"{formatted_money} § ({status})"
    except Exception as e:
        log_exception("Error getting household funds", e)

    return "Неизвестно"


def get_sim_pregnancy_info(sim_info) -> str:
    """
    Extracts comprehensive pregnancy context:
    - If sim is pregnant: trimester, progress, symptoms, expected babies, and partner/other parent.
    - If sim's partner or family member is pregnant: pregnancy status of the partner/family.
    """
    try:
        is_pregnant = getattr(sim_info, "is_pregnant", False)

        gender_raw = getattr(getattr(sim_info, "gender", None), "name", "FEMALE")
        is_male = (gender_raw == "MALE")

        # Check buffs for exact trimester
        buff_trimester = None
        if hasattr(sim_info, "buffs"):
            for b in sim_info.buffs:
                b_name = getattr(getattr(b, "buff_type", b), "__name__", str(b)).lower()
                if "inlabor" in b_name or "in_labor" in b_name:
                    buff_trimester = "Схватки! Роды начались прямо сейчас! (Срочно нужно рожать в больнице или дома в люльке)"
                    break
                elif "trimester3" in b_name or "trimester_3" in b_name:
                    buff_trimester = "3-й триместр (скоро роды, большой тяжелый живот, сильная усталость, частые позывы в туалет, малыш активно пинается)"
                    break
                elif "trimester2" in b_name or "trimester_2" in b_name:
                    if is_male:
                        buff_trimester = "2-й триместр (заметный живот, первые шевеления ребенка, странные ощущения в теле)"
                    else:
                        buff_trimester = "2-й триместр (заметный живот, первые шевеления ребенка, приятное предвкушение материнства)"
                    break
                elif "trimester1" in b_name or "trimester_1" in b_name or "notshowing" in b_name:
                    buff_trimester = "1-й триместр (ранний срок, утренняя тошнота, странные пищевые капризы, перепады настроения)"
                    break

        if is_pregnant:
            p_trk = getattr(sim_info, "pregnancy_tracker", None)
            partner = p_trk.get_partner() if p_trk else None
            partner_name = ""
            if partner:
                p_first = getattr(partner, "first_name", "")
                p_last = getattr(partner, "last_name", "")
                partner_name = f"{p_first} {p_last}".strip()

            # Progress fallback if no buff found
            if not buff_trimester:
                prog = getattr(sim_info, "pregnancy_progress", 0.0)
                if prog >= 0.9:
                    buff_trimester = "Перед самыми родами (финал 3-го триместра)"
                elif prog >= 0.66:
                    buff_trimester = "3-й триместр (большой живот, подготовка к родам)"
                elif prog >= 0.33:
                    if is_male:
                        buff_trimester = "2-й триместр (округлившийся живот, толчки малыша)"
                    else:
                        buff_trimester = "2-й триместр (округлившийся живот, толчки малыша)"
                elif prog > 0:
                    buff_trimester = "1-й триместр (ранний срок, тошнота)"
                else:
                    buff_trimester = "Беременность (ранний этап)"

            offspring_count = getattr(p_trk, "offspring_count", 1) if p_trk else 1
            if offspring_count == 2:
                babies_str = "двойню"
            elif offspring_count >= 3:
                babies_str = "тройню"
            else:
                babies_str = "одного ребенка"

            is_alien_male = is_male and get_experimental_flag("alien_male_pregnancy")

            if is_alien_male:
                # User request:
                # "если мужчина беременный то автоматически считается что это беременность от инопланетян " определение мужской беременности от инопланетян". В разделе беремености типо после срока будет написано что он беременен инопланетяненом после похищения"
                prefix = "Беременен"
                term_desc = f"{buff_trimester}, беременен инопланетянином после похищения"
                details = [f"{prefix}: {term_desc}", f"Ожидает: {babies_str}"]
                if partner_name:
                    details.append(f"Второй родитель (опылитель): {partner_name}")
                else:
                    details.append("Опылитель: Инопланетная цивилизация")
            elif is_male:
                prefix = "Беременен"
                details = [f"{prefix}: {buff_trimester}", f"Ожидает: {babies_str}"]
                if partner_name:
                    details.append(f"Второй родитель: {partner_name}")
            else:
                prefix = "Беременна"
                details = [f"{prefix}: {buff_trimester}", f"Ожидает: {babies_str}"]
                if partner_name:
                    details.append(f"Второй родитель (отец/партнёр): {partner_name}")

            return "; ".join(details)

        # Sim themselves is not pregnant. Check if their partner or someone in the household is!
        if services is not None:
            sim_mgr = services.sim_info_manager()
            if sim_mgr is not None:
                # 1. First priority: Check if spouse/partner is pregnant with this sim's child
                for other_info in sim_mgr.values():
                    if other_info == sim_info:
                        continue
                    if getattr(other_info, "is_pregnant", False):
                        other_trk = getattr(other_info, "pregnancy_tracker", None)
                        if other_trk and other_trk.get_partner() == sim_info:
                            o_name = f"{getattr(other_info, 'first_name', '')} {getattr(other_info, 'last_name', '')}".strip()
                            o_offspring = getattr(other_trk, "offspring_count", 1)
                            o_babies = "двойню" if o_offspring == 2 else ("тройню" if o_offspring >= 3 else "ребенка")

                            o_trim = "беременна"
                            if hasattr(other_info, "buffs"):
                                for b in other_info.buffs:
                                    b_name = getattr(getattr(b, "buff_type", b), "__name__", str(b)).lower()
                                    if "inlabor" in b_name:
                                        o_trim = "рожает прямо сейчас (в схватках!)"
                                        break
                                    elif "trimester3" in b_name:
                                        o_trim = "на 3-м триместре (скоро роды)"
                                        break
                                    elif "trimester2" in b_name:
                                        o_trim = "на 2-м триместре (животик уже заметен)"
                                        break
                                    elif "trimester1" in b_name:
                                        o_trim = "на раннем сроке (1-й триместр)"
                                        break
                            not_preg_label = "Не беременен" if is_male else "Не беременна"
                            return f"{not_preg_label} (партнерша {o_name} беременна их общим ребенком: {o_trim}, ждет {o_babies}; сим готовится стать родителем)"

                # 2. Check if household member is pregnant
                household = getattr(sim_info, "household", None)
                if household is not None:
                    for h_sim in household.sim_info_gen():
                        if h_sim != sim_info and getattr(h_sim, "is_pregnant", False):
                            h_name = f"{getattr(h_sim, 'first_name', '')} {getattr(h_sim, 'last_name', '')}".strip()
                            not_preg_label = "Не беременен" if is_male else "Не беременна"
                            return f"{not_preg_label} (в семье скоро будет пополнение: {h_name} беременна)"

        return "Не беременна" if not is_male else "Не беременен"
    except Exception as e:
        log_exception("Error in get_sim_pregnancy_info", e)
        return "Не беременна"


def get_sim_fame_and_reputation_info(sim_info) -> str:
    """
    Extracts Fame level (Get Famous EP), celebrity quirks, and public reputation.
    """
    try:
        parts = []

        # 1. Fame (Уровень славы от 0 до 5 звезд)
        fame_stat = None
        if FameTunables is not None and getattr(FameTunables, "FAME_RANKED_STATISTIC", None) is not None:
            fame_stat_tuning = FameTunables.FAME_RANKED_STATISTIC
            if hasattr(sim_info, "get_statistic"):
                fame_stat = sim_info.get_statistic(fame_stat_tuning)
            if fame_stat is None:
                tracker = getattr(sim_info, "statistic_tracker", None) or getattr(sim_info, "commodity_tracker", None)
                if tracker is not None and hasattr(tracker, "get_statistic"):
                    fame_stat = tracker.get_statistic(fame_stat_tuning)

        # Fallback search if FameTunables not loaded directly
        if fame_stat is None:
            for trk_name in ["statistic_tracker", "commodity_tracker"]:
                tracker = getattr(sim_info, trk_name, None)
                if tracker is not None:
                    for stat in tracker:
                        s_name = getattr(stat, "__name__", str(type(stat).__name__)).lower()
                        if "rankedstatistic_fame" in s_name or (s_name.endswith("fame") and hasattr(stat, "rank_level")):
                            fame_stat = stat
                            break
                if fame_stat is not None:
                    break

        fame_rank = getattr(fame_stat, "rank_level", 0) if fame_stat is not None else 0

        # 2. Reputation (Общественная репутация: 7 фиксированных рангов, по умолчанию 4 — Нейтральная)
        # В The Sims 4 ранги репутации представлены строго 7 трейтами:
        # 1: Terrible (Ужасная)
        # 2: ReallyBad (Очень плохая)
        # 3: Bad (Плохая)
        # 4: Neutral (Нейтральная)
        # 5: Good (Хорошая)
        # 6: ReallyGood (Отличная)
        # 7: Pristine (Безупречная)
        rep_rank = 4  # По умолчанию: Нейтральная (4)

        all_sim_traits = []
        if hasattr(sim_info, "get_traits"):
            try:
                all_sim_traits.extend(sim_info.get_traits())
            except Exception:
                pass
        if hasattr(sim_info, "trait_tracker") and sim_info.trait_tracker is not None:
            try:
                equipped = getattr(sim_info.trait_tracker, "equipped_traits", None)
                if equipped:
                    all_sim_traits.extend(equipped)
            except Exception:
                pass

        for trait in all_sim_traits:
            t_name = getattr(trait, "__name__", str(trait)).lower()
            # Пропускаем исторические трейты "HasBeen_Rank_..."
            if "reputation_rank_" in t_name and "hasbeen" not in t_name and "has_been" not in t_name:
                if "rank_1" in t_name or "terrible" in t_name:
                    rep_rank = 1
                    break
                elif "rank_2" in t_name or "reallybad" in t_name or "really_bad" in t_name:
                    rep_rank = 2
                    break
                elif "rank_3" in t_name or "bad" in t_name:
                    rep_rank = 3
                    break
                elif "rank_4" in t_name or "neutral" in t_name:
                    rep_rank = 4
                    break
                elif "rank_5" in t_name or ("good" in t_name and "really" not in t_name):
                    rep_rank = 5
                    break
                elif "rank_6" in t_name or "reallygood" in t_name or "really_good" in t_name:
                    rep_rank = 6
                    break
                elif "rank_7" in t_name or "pristine" in t_name:
                    rep_rank = 7
                    break

        if hasattr(sim_info, "allow_reputation") and not sim_info.allow_reputation:
            rep_rank = 4

        FAME_LABELS = {
            0: "0 звёзд (Обычный житель / Не знаменит)",
            1: "⭐ 1 звезда — Заметный новичок (первое внимание публики)",
            2: "⭐⭐ 2 звезды — Восходящая звезда (вспышки камер, первые фанаты)",
            3: "⭐⭐⭐ 3 звезды — Настоящая знаменитость (толпы поклонников, известность)",
            4: "⭐⭐⭐⭐ 4 звезды — Звезда мирового масштаба (огромная слава, папарацци)",
            5: "⭐⭐⭐⭐⭐ 5 звёзд — Всемирная суперзвезда (культовая легенда, золотая аура славы)",
        }

        REP_LABELS = {
            1: "Ужасная (Отъявленный злодей, общественный враг)",
            2: "Очень плохая (Омерзительные слухи, всеобщее недоверие)",
            3: "Плохая (Дурная слава)",
            4: "Нейтральная (Обычная городская репутация)",
            5: "Хорошая (Вежливый и надежный горожанин)",
            6: "Отличная (Всеобщее уважение и симпатия)",
            7: "Безупречная (Святой образец для подражания, кумир общества)",
        }

        if fame_rank == 0 and rep_rank == 4:
            parts.append("Слава: 0 звёзд (Обычный житель / Не знаменит). Репутация: Нейтральная (обычная городская репутация)")
        else:
            parts.append(f"Слава: {FAME_LABELS.get(fame_rank, f'{fame_rank} звёзд')}")
            parts.append(f"Репутация: {REP_LABELS.get(rep_rank, f'Ранг {rep_rank}')}")

        if hasattr(sim_info, "allow_fame") and not sim_info.allow_fame:
            parts.append("(Отказ от славы: сим скрывается от публичности)")

        # 3. Celebrity Quirks (Особые звездные заскоки / причуды) - ONLY for actual celebrities (fame_rank > 0)
        quirks = []
        if fame_rank > 0 and hasattr(sim_info, "trait_tracker") and sim_info.trait_tracker is not None:
            CELEBRITY_QUIRK_NAMES = {
                "notouching": "Не прикасаться! (брезгует физическим контактом с обычными симами)",
                "refinedpalate": "Изысканный вкус (требует только великолепную ресторанную еду)",
                "publicnumber": "Общедоступный номер (телефон разрывается от звонков фанатов)",
                "paparazzidarling": "Любимец папарацци (обожает позировать перед камерами)",
                "stan": "Одержимый фанат (рядом постоянно бродит навязчивый сталкер)",
                "phonefanatic": "Телефонный фанатик (постоянно уткнут в соцсети)",
                "vainstreet": "Тщеславие (не может оторваться от зеркала)",
                "a-lister": "Общение со сливками общества (общается только со знаменитостями)",
                "juiceenthusiast": "Любитель сока (постоянная тяга к выпивке и бару)",
                "emotionbomb": "Эмоциональная бомба (склонен к драматическим срывам на публике)",
            }
            equipped_traits = getattr(sim_info.trait_tracker, "equipped_traits", ())
            for trait in equipped_traits:
                t_name = getattr(trait, "__name__", str(trait)).lower()
                # Strict filter: must be a fame quirk trait
                if "quirk" not in t_name:
                    continue
                for qk, qv in CELEBRITY_QUIRK_NAMES.items():
                    if qk in t_name and qv not in quirks:
                        quirks.append(qv)
                        break

        if quirks:
            parts.append(f"Причуды знаменитости: {'; '.join(quirks)}")

        return ". ".join(parts)
    except Exception as e:
        log_exception("Error in get_sim_fame_and_reputation_info", e)
        return "Слава: 0 звёзд (Обычный житель / Не знаменит). Репутация: Нейтральная (обычная городская репутация)"


def get_sim_traits_info(sim_info) -> list:
    """
    Extracts all human-readable character traits with 100% accuracy, including:
    - Core CAS Personality Traits (Романтик, Книжный червь, Эксцентричный, etc.)
    - WickedWhims Archetypes (Опекун, Мудрец, Шут, etc.) with psychological descriptions
    - Aspiration Bonus Traits (Способный ученик, Утонченный вкус, etc.)
    - Reward Store & Milestone Traits (Любитель целоваться, Многодетность, Сова, etc.)
    - WickedWhims Sexuality & Lifestyle Traits (Сексуальная привлекательность, etc.)
    - Child & Family Preference Traits (Нейтральное отношение к детям, etc.)
    Uses strict key & GUID resolution. Zero substring false-positives.
    """
    traits_list = []
    seen_names = set()

    try:
        # Categorized lists for logical prioritization
        core_traits = []
        ww_archetypes = []
        aspiration_traits = []
        reward_traits = []
        ww_traits = []
        other_traits = []

        def _clean_base_key(name: str) -> str:
            return name.split("(")[0].strip().lower()

        # 1. Collect all raw traits from the Sim (equipped traits take absolute priority)
        all_raw_traits = []
        if hasattr(sim_info, "get_traits"):
            all_raw_traits = list(sim_info.get_traits())
        elif hasattr(sim_info, "trait_tracker") and sim_info.trait_tracker is not None:
            if hasattr(sim_info.trait_tracker, "equipped_traits"):
                all_raw_traits = list(sim_info.trait_tracker.equipped_traits)
            else:
                all_raw_traits = list(sim_info.trait_tracker)

        for trait in all_raw_traits:
            if trait is None:
                continue

            t_name = getattr(trait, "__name__", str(trait))
            t_lower = t_name.lower()

            guid = getattr(trait, "guid64", None)
            if guid is None:
                guid = getattr(trait, "guid", None)

            # Check if this trait is a personality archetype or WickedWhims trait
            is_archetype_or_ww = (
                "archetype" in t_lower
                or (guid is not None and (guid in GUID_TRAIT_TRANSLATIONS or (guid & 0xFFFFFFFF) in GUID_TRAIT_TRANSLATIONS))
                or any(k in t_lower for k in ("wickedwhims", "ww_"))
            )

            # Check trait_type enum if available
            trait_type_val = getattr(trait, "trait_type", None)
            trait_type_name = str(getattr(trait_type_val, "name", trait_type_val)).upper()

            # Filter out non-personality engine types (archetypes & WW traits are preserved even if tuned as HIDDEN)
            if not is_archetype_or_ww:
                if trait_type_name in ("HIDDEN", "WALKSTYLE", "GENDER_OPTIONS", "SIM_PREFERENCE", "AGENT", "BATUU_ALIEN"):
                    continue

                # Skip common technical, situation or NPC markers
                if any(skip in t_lower for skip in [
                    "hidden", "walkstyle", "genderoptions", "ghost", "occult", "phone_",
                    "buff_", "is_master", "is_maid", "is_gardener", "is_repair",
                    "dislike", "favorite", "fear_", "graduation", "highschool", "batuu",
                    "scenario", "challenge", "situation", "service", "temperature",
                    "food_", "drink_", "music_", "decor_"
                ]):
                    continue

            resolved_name = None
            category = None
            extra_desc = None

            # --- A. Check 64-bit and 32-bit GUID ---
            if guid is not None:
                if guid in GUID_TRAIT_TRANSLATIONS:
                    g_info = GUID_TRAIT_TRANSLATIONS[guid]
                elif (guid & 0xFFFFFFFF) in GUID_TRAIT_TRANSLATIONS:
                    g_info = GUID_TRAIT_TRANSLATIONS[guid & 0xFFFFFFFF]
                else:
                    g_info = None
                if g_info:
                    resolved_name = g_info[0]
                    category = g_info[1]
                    extra_desc = g_info[2] if len(g_info) > 2 else None

            # --- B. Check WickedWhims Archetype trait name ---
            if not resolved_name and ("ww_personality_archetype_" in t_lower or "archetype_" in t_lower):
                clean_arch = t_lower
                for pfx in ("trait_", "ww_personality_archetype_", "archetype_"):
                    clean_arch = clean_arch.replace(pfx, "")
                for sfx in ("_major", "_minor"):
                    if clean_arch.endswith(sfx):
                        clean_arch = clean_arch[:-len(sfx)]
                clean_arch = clean_arch.strip()

                for enum_key, (arch_rus, arch_d) in WW_ARCHETYPE_ENUM_MAP.items():
                    if clean_arch == enum_key.lower():
                        resolved_name = arch_rus
                        category = "archetype"
                        extra_desc = arch_d
                        break

            # --- C. Check WickedWhims Sexuality / Personality trait ---
            clean_t = t_lower[6:] if t_lower.startswith("trait_") else t_lower
            if not resolved_name:
                if clean_t in WW_TRAIT_TRANSLATIONS:
                    resolved_name = WW_TRAIT_TRANSLATIONS[clean_t]
                    category = "ww"
                elif clean_t.replace("_", "") in WW_TRAIT_TRANSLATIONS:
                    resolved_name = WW_TRAIT_TRANSLATIONS[clean_t.replace("_", "")]
                    category = "ww"
                elif t_lower in WW_TRAIT_TRANSLATIONS:
                    resolved_name = WW_TRAIT_TRANSLATIONS[t_lower]
                    category = "ww"

            # --- D. Check Exact CAS / Aspiration / Reward trait dictionary ---
            if not resolved_name:
                if clean_t in TRAIT_TRANSLATIONS:
                    resolved_name = TRAIT_TRANSLATIONS[clean_t]
                elif clean_t.replace("_", "") in TRAIT_TRANSLATIONS:
                    resolved_name = TRAIT_TRANSLATIONS[clean_t.replace("_", "")]
                elif t_lower in TRAIT_TRANSLATIONS:
                    resolved_name = TRAIT_TRANSLATIONS[t_lower]

            # --- E. Special mod checks (RPO / WooHoo Wellness child preferences) ---
            if not resolved_name:
                if "child_pref_neutral" in t_lower or "child_pref_indifferent" in t_lower or "indifferent_to_children" in t_lower:
                    resolved_name = "Нейтральное отношение к детям"
                    category = "other"
                elif "child_pref_want" in t_lower or "wants_children" in t_lower:
                    resolved_name = "Хочет детей"
                    category = "other"
                elif "child_pref_no" in t_lower or "doesnt_want_children" in t_lower:
                    resolved_name = "Не хочет детей"
                    category = "other"

            # If still not resolved, ignore internal/unmapped engine trait
            if not resolved_name:
                continue

            base_key = _clean_base_key(resolved_name)
            if base_key in seen_names:
                continue
            seen_names.add(base_key)

            # Categorize and format
            disp_lower = resolved_name.lower()
            if category == "archetype" or any(base_key == a for a in [
                "мудрец", "герой", "шут", "опекун", "бунтарь", "любовник",
                "искатель", "творец", "правитель", "невинный", "славный малый", "маг"
            ]):
                if not extra_desc:
                    extra_desc = ARCHETYPE_DESCRIPTIONS.get(base_key, "")
                if extra_desc and "архетип" not in disp_lower:
                    formatted = f"{resolved_name} (Архетип личности: {extra_desc})"
                elif "архетип" not in disp_lower:
                    formatted = f"{resolved_name} (Архетип личности)"
                else:
                    formatted = resolved_name
                ww_archetypes.append(formatted)

            elif category == "ww":
                ww_traits.append(resolved_name)

            elif category == "other":
                other_traits.append(resolved_name)

            elif "бонус" in disp_lower or trait_type_name == "ASPIRATION":
                if "бонус" not in disp_lower:
                    formatted = f"{resolved_name} (Бонус жизненной цели)"
                else:
                    formatted = resolved_name
                aspiration_traits.append(formatted)

            elif "наград" in disp_lower:
                reward_traits.append(resolved_name)

            elif trait_type_name == "GAMEPLAY" and ("reward" in t_lower or "store" in t_lower):
                if "наград" not in disp_lower:
                    formatted = f"{resolved_name} (Награда)"
                else:
                    formatted = resolved_name
                reward_traits.append(formatted)

            elif trait_type_name == "PERSONALITY" or clean_t in TRAIT_TRANSLATIONS:
                core_traits.append(resolved_name)

            else:
                other_traits.append(resolved_name)

        # Fallback for WickedWhims Archetypes ONLY if no archetypes were found in equipped traits
        if not ww_archetypes:
            try:
                from turbolib2.wrappers.sim.sim import TurboSim
                from wickedwhims.relationships.features.impression.archetypes_operator import get_sim_personality_archetypes
                tsim = TurboSim(sim_info)
                arch_tuple = get_sim_personality_archetypes(tsim)
                if arch_tuple:
                    for arch in arch_tuple:
                        if not arch:
                            continue
                        a_name = getattr(arch, "name", str(arch)).upper()
                        # WickedWhims returns NONE when an archetype slot is empty
                        if a_name in ("NONE", "0"):
                            continue
                        if a_name in WW_ARCHETYPE_ENUM_MAP:
                            rus_name, rus_desc = WW_ARCHETYPE_ENUM_MAP[a_name]
                            b_key = rus_name.lower()
                            if b_key not in seen_names:
                                seen_names.add(b_key)
                                ww_archetypes.append(f"{rus_name} (Архетип личности: {rus_desc})")
            except Exception:
                pass

        # Assemble traits according to trait filter flags from settings
        from ai_thought_reader.config import get_trait_filter_flag

        if get_trait_filter_flag("core"):
            traits_list.extend(core_traits[:3])
        if get_trait_filter_flag("aspiration"):
            traits_list.extend(aspiration_traits)
        if get_trait_filter_flag("ww_archetypes"):
            traits_list.extend(ww_archetypes)
        if get_trait_filter_flag("rewards"):
            traits_list.extend(reward_traits)
        if get_trait_filter_flag("ww_traits"):
            traits_list.extend(ww_traits)
        if get_trait_filter_flag("custom_mods"):
            traits_list.extend(other_traits)

    except Exception as e:
        log_exception("Error getting sim traits", e)

    return traits_list[:20]


def get_sim_motives_summary(sim_info) -> list:
    """Accurately checks all core motives and needs across standard Sims and occults."""
    notable_needs = []
    seen_needs = set()

    def add_need(key, desc):
        if key not in seen_needs:
            seen_needs.add(key)
            notable_needs.append(desc)

    try:
        # Layer 1: Check Commodity Tracker
        if hasattr(sim_info, "commodity_tracker") and sim_info.commodity_tracker is not None:
            stats_list = list(sim_info.commodity_tracker)
            for stat in stats_list:
                s_type = getattr(stat, "stat_type", None) or type(stat)
                type_name = getattr(s_type, "__name__", "").lower()
                inst_str = str(stat).lower()
                combined_name = f"{type_name} {inst_str}"

                # Ignore sub-commodities (hands, teeth, sweat, cleanliness, autonomy, trait, static, etc.)
                if any(skip in type_name for skip in ["hands", "teeth", "sweat", "cleanliness", "autonomy", "trait", "static"]):
                    continue

                val = getattr(stat, "get_value", lambda: 0)()

                # 1. Естественная нужда (Bladder)
                if "motive_bladder" in type_name or ("bladder" in combined_name and "motive" in combined_name):
                    if val <= -75:
                        add_need("bladder", "Критически хочет в туалет (едва сдерживается, острая нужда)")
                    elif val <= -50:
                        add_need("bladder", "Хочет в туалет (нужно сходить в туалет)")

                # 2. Питание / Голод (Hunger)
                elif "motive_hunger" in type_name or ("hunger" in combined_name and "motive" in combined_name):
                    if val <= -75:
                        add_need("hunger", "Умирает от голода (критически пустой желудок, сильное истощение)")
                    elif val <= -50:
                        add_need("hunger", "Проголодался (хочет есть / перекусить)")

                # 3. Бодрость / Энергия (Energy)
                elif "motive_energy" in type_name or ("energy" in combined_name and "motive" in combined_name):
                    if val <= -75:
                        add_need("energy", "Валится с ног от усталости (критический недосып, засыпает на ходу)")
                    elif val <= -50:
                        add_need("energy", "Устал (хочет спать / прилечь отдохнуть)")

                # 4. Гигиена (Hygiene) - strictly main hygiene motive
                elif "motive_hygiene" in type_name or ("hygiene" in combined_name and "motive" in combined_name and not any(sub in combined_name for sub in ["hands", "teeth", "sweat", "foot", "cleanliness"])):
                    if val <= -75:
                        add_need("hygiene", "Ужасно грязен и плохо пахнет (критически необходим душ)")
                    elif val <= -50:
                        add_need("hygiene", "Не мешало бы помыться / принять душ")

                # 5. Досуг (Fun)
                elif "motive_fun" in type_name or ("fun" in combined_name and "motive" in combined_name):
                    if val <= -75:
                        add_need("fun", "Умирает от скуки и тоски (острая нехватка развлечений)")
                    elif val <= -50:
                        add_need("fun", "Скучно (хочется развлечься или поиграть)")

                # 6. Общение (Social)
                elif "motive_social" in type_name or ("social" in combined_name and "motive" in combined_name):
                    if val <= -75:
                        add_need("social", "Крайне одинок (глубокая социальная изоляция, острая нехватка общения)")
                    elif val <= -50:
                        add_need("social", "Хочется пообщаться / поболтать с кем-нибудь")

                # 7. Жажда вампира (Vampire Thirst)
                elif "vampire_thirst" in type_name or "motive_thirst" in type_name:
                    if val <= -75:
                        add_need("thirst", "Мучительная вампирская жажда (готов напасть ради свежей крови)")
                    elif val <= -50:
                        add_need("thirst", "Вампирская жажда (нужна свежая кровь или пакет с кровью)")

                # 8. Увлажнение русалки (Mermaid Hydration)
                elif "mermaid_hydration" in type_name or "motive_hydration" in type_name:
                    if val <= -75:
                        add_need("hydration", "Критическое обезвоживание (нужна вода / океан)")
                    elif val <= -50:
                        add_need("hydration", "Обезвоживание (нужно увлажнение / душ / плавание)")

                # 9. Вода ростомана (PlantSim Water)
                elif "plantsim_water" in type_name or ("plantsim" in combined_name and "water" in combined_name):
                    if val <= -75:
                        add_need("plantsim_water", "Критическая засуха и увядание (ростоман вянет без воды)")
                    elif val <= -50:
                        add_need("plantsim_water", "Обезвоживание ростомана (нужно поглотить воду или полить себя)")

                # 10. Солнечный свет ростомана (PlantSim Sunlight / Photosynthesis)
                elif "plantsim_hunger" in type_name or ("plantsim" in combined_name and ("hunger" in combined_name or "sunlight" in combined_name)):
                    if val <= -75:
                        add_need("plantsim_sunlight", "Истощение без солнца (ростоману критически необходим солнечный свет)")
                    elif val <= -50:
                        add_need("plantsim_sunlight", "Нехватка солнечного света (ростоману нужен свет для фотосинтеза)")

        # Layer 2: Verify only specific Motive Buffs (distress / urgent only, ignore neutral/satisfied)
        active_buffs = get_all_sim_buffs(sim_info)
        for b in active_buffs:
            b_type = getattr(b, "buff_type", None) or type(b)
            b_name = getattr(b_type, "__name__", str(b)).lower()

            # Ignore any satisfied, full, immune, or positive motive buffs
            if any(pos in b_name for pos in ["full", "satisfied", "happy", "fine", "normal", "immune", "cheat"]):
                continue

            if "buff_motive_bladder" in b_name or "buff_motives_bladder" in b_name:
                if any(k in b_name for k in ["desperate", "critical", "reallyurgent", "really_urgent", "fail"]):
                    add_need("bladder", "Критически хочет в туалет (едва сдерживается, острая нужда)")
                elif any(k in b_name for k in ["hastopee", "has_to_pee", "urgent", "distressed", "need"]):
                    add_need("bladder", "Хочет в туалет (нужно сходить в туалет)")

            elif "buff_motive_hunger" in b_name or "buff_motives_hunger" in b_name:
                if any(k in b_name for k in ["starv", "critical", "desperate"]):
                    add_need("hunger", "Умирает от голода (критически пустой желудок)")
                elif any(k in b_name for k in ["hungry", "famished", "peckish", "need"]):
                    add_need("hunger", "Проголодался (хочет есть)")

            elif "buff_motive_energy" in b_name or "buff_motives_energy" in b_name:
                if any(k in b_name for k in ["exhaust", "critical", "desperate", "passout", "pass_out"]):
                    add_need("energy", "Валится с ног от усталости (засыпает на ходу)")
                elif any(k in b_name for k in ["sleepy", "tired", "need"]):
                    add_need("energy", "Устал (хочет спать / отдохнуть)")

            elif "buff_motive_hygiene" in b_name or "buff_motives_hygiene" in b_name:
                if any(k in b_name for k in ["filthy", "critical", "desperate"]):
                    add_need("hygiene", "Ужасно грязен и плохо пахнет (срочно нужен душ)")
                elif any(k in b_name for k in ["grimy", "dirty", "smelly", "stinky", "need"]):
                    add_need("hygiene", "Не мешало бы принять душ / помыться")

            elif "buff_motive_fun" in b_name or "buff_motives_fun" in b_name:
                if any(k in b_name for k in ["desolate", "critical", "desperate"]):
                    add_need("fun", "Умирает от скуки и тоски")
                elif any(k in b_name for k in ["bored", "need"]):
                    add_need("fun", "Скучно (хочется развлечься)")

            elif "buff_motive_social" in b_name or "buff_motives_social" in b_name:
                if any(k in b_name for k in ["desolate", "critical", "desperate", "isolated"]):
                    add_need("social", "Крайне одинок (острая нехватка общения)")
                elif any(k in b_name for k in ["lonely", "need"]):
                    add_need("social", "Хочется пообщаться с кем-нибудь")

            elif "buff_plantsim" in b_name:
                if any(k in b_name for k in ["wilted", "dry", "dehydrated"]):
                    add_need("plantsim_water", "Критическая засуха и увядание (ростоман вянет без воды)")
                elif any(k in b_name for k in ["thirsty", "needwater", "need_water"]):
                    add_need("plantsim_water", "Обезвоживание ростомана (нужно поглотить воду или полить себя)")
                elif any(k in b_name for k in ["hungry", "needsun", "need_sun", "starving"]):
                    add_need("plantsim_sunlight", "Нехватка солнечного света (ростоману нужен свет для фотосинтеза)")

    except Exception as e:
        log_exception("Error inspecting sim motives", e)

    return notable_needs


def is_interaction_running(inter) -> bool:
    """Checks if an interaction is actively executing / running right now (not queued, not finishing, not routing)."""
    if inter is None:
        return False
    try:
        # If finishing, exiting or cancelled, it is no longer running
        if getattr(inter, "is_finishing", False):
            return False

        # If explicitly marked as running or performing
        if getattr(inter, "running", False) or getattr(inter, "performing", False):
            return True

        # Pipeline progress check (PipelineProgress: NONE=0, QUEUED=1, PRE_TRANSITIONING=2, PREPARED=3, RUNNING=4, STAGED=5, EXITED=6)
        progress = getattr(inter, "pipeline_progress", None)
        if progress is not None:
            # Under 4 is not yet running (queued=1, pre_transitioning=2, prepared=3)
            # 6 or above is exited
            if progress < 4 or progress >= 6:
                return False
            return True

        # Fallback to boolean properties
        if getattr(inter, "active", False) and not getattr(inter, "queued", False):
            return True
    except Exception:
        pass
    return False


def is_interaction_transitioning(inter, sim_instance) -> bool:
    """Checks if the interaction is currently transitioning / routing towards execution."""
    if inter is None:
        return False
    try:
        if getattr(inter, "is_finishing", False):
            return False

        progress = getattr(inter, "pipeline_progress", None)
        if progress is not None and progress in (2, 3):  # PRE_TRANSITIONING or PREPARED
            return True

        if hasattr(sim_instance, "queue") and sim_instance.queue is not None:
            if getattr(sim_instance.queue, "transition_in_progress", False):
                tc = getattr(sim_instance.queue, "transition_controller", None)
                if tc is not None and getattr(tc, "interaction", None) is inter:
                    return True
                if getattr(sim_instance.queue, "running", None) is inter:
                    return True
    except Exception:
        pass
    return False


def get_sim_running_interactions(sim_instance):
    """
    Gathers ONLY truly running/executing interactions on the Sim.
    Strictly excludes queued interactions and finishing interactions.
    """
    interactions = []
    seen = set()

    def _add(inter):
        if inter is not None and id(inter) not in seen:
            seen.add(id(inter))
            interactions.append(inter)

    if sim_instance is None:
        return interactions

    # 1. Super Interactions currently in SIState (Active, executing SuperInteractions)
    if hasattr(sim_instance, "si_state") and sim_instance.si_state is not None:
        try:
            sis = None
            if hasattr(sim_instance.si_state, "sis_actor_gen"):
                sis = sim_instance.si_state.sis_actor_gen()
            elif hasattr(sim_instance.si_state, "all_guaranteed_si_gen"):
                sis = sim_instance.si_state.all_guaranteed_si_gen()
            else:
                sis = sim_instance.si_state

            for si in sis:
                if is_interaction_running(si):
                    _add(si)
                    # Also collect running active mixers on this SI
                    for m_attr in ["active_mixers", "_active_mixers"]:
                        if hasattr(si, m_attr):
                            for mixer in getattr(si, m_attr, ()):
                                if is_interaction_running(mixer):
                                    _add(mixer)
        except Exception:
            pass

    # 2. Currently running interaction from the queue (if NOT in transition)
    if hasattr(sim_instance, "queue") and sim_instance.queue is not None:
        try:
            if not getattr(sim_instance.queue, "transition_in_progress", False):
                q_run = getattr(sim_instance.queue, "_running", None) or getattr(sim_instance.queue, "running", None)
                if is_interaction_running(q_run):
                    _add(q_run)

            # Active mixers in queue
            if hasattr(sim_instance.queue, "mixer_interactions_gen"):
                for mixer in sim_instance.queue.mixer_interactions_gen():
                    if is_interaction_running(mixer):
                        _add(mixer)
        except Exception:
            pass

    # 3. Posture interaction (sitting on couch, lying in bed, etc.)
    if hasattr(sim_instance, "posture") and sim_instance.posture is not None:
        try:
            source_interaction = getattr(sim_instance.posture, "source_interaction", None)
            if is_interaction_running(source_interaction):
                _add(source_interaction)
        except Exception:
            pass

    return interactions


def get_sim_transitioning_interaction(sim_instance):
    """
    Returns the interaction that the Sim is currently routing/walking towards, if any.
    """
    if sim_instance is None:
        return None

    try:
        # 1. Check transition_controller on queue
        if hasattr(sim_instance, "queue") and sim_instance.queue is not None:
            if getattr(sim_instance.queue, "transition_in_progress", False):
                tc = getattr(sim_instance.queue, "transition_controller", None)
                if tc is not None:
                    inter = getattr(tc, "interaction", None)
                    if inter is not None and not getattr(inter, "is_finishing", False):
                        return inter
                q_run = getattr(sim_instance.queue, "running", None)
                if q_run is not None and not getattr(q_run, "is_finishing", False):
                    return q_run

        # 2. Check sim_instance.transition_controller
        tc = getattr(sim_instance, "transition_controller", None)
        if tc is not None:
            inter = getattr(tc, "interaction", None)
            if inter is not None and not getattr(inter, "is_finishing", False):
                return inter

        # 3. Check head of queue if pipeline_progress is 2 or 3 (PRE_TRANSITIONING, PREPARED)
        if hasattr(sim_instance, "queue") and hasattr(sim_instance.queue, "peek_head"):
            head = sim_instance.queue.peek_head()
            if head is not None and not getattr(head, "is_finishing", False):
                prog = getattr(head, "pipeline_progress", None)
                if prog in (2, 3):
                    return head
    except Exception:
        pass
    return None


def format_transitioning_activity(act: str) -> str:
    """Formats an activity that the Sim is currently walking/routing towards (has not started yet)."""
    if not act:
        return "Идёт по своим делам"

    act_lower = act.lower().strip()

    # Specific replacements
    if "грязев" in act_lower:
        return "Идёт принимать грязевую ванну"
    if "горячий парной душ" in act_lower:
        return "Идёт принимать горячий парной душ"
    if "бодрящий" in act_lower and "душ" in act_lower:
        return "Идёт принимать бодрящий душ"
    if "душ" in act_lower:
        if "моет" in act_lower:
            return "Идёт мыть душевую кабину"
        return "Идёт принимать душ"
    if "ванн" in act_lower:
        if "моет" in act_lower:
            return "Идёт мыть ванну"
        if "пен" in act_lower:
            return "Идёт принимать ванну с пеной"
        return "Идёт принимать ванну"
    if "спит" in act_lower or "ложится спать" in act_lower:
        return "Идёт спать в кровать"
    if "дремлет" in act_lower:
        return "Идёт прилечь и вздремнуть"
    if "готовит" in act_lower or "варит" in act_lower or "печет" in act_lower or "жарит" in act_lower:
        return "Идёт на кухню готовить еду"
    if "ест" in act_lower or "завтракает" in act_lower or "обедает" in act_lower or "ужинает" in act_lower or "перекусывает" in act_lower:
        return "Идёт поесть / перекусить"
    if "пьет" in act_lower or "наливает" in act_lower:
        return "Идёт налить напиток"
    if "телевизор" in act_lower or "фильм" in act_lower:
        return "Идёт смотреть телевизор"
    if "компьютер" in act_lower or "пк" in act_lower or "видеоигры" in act_lower or "видеоигр" in act_lower:
        return "Идёт за компьютер"
    if "книг" in act_lower or "читает" in act_lower:
        return "Идёт читать книгу"
    if "уборк" in act_lower or "вытирает" in act_lower or "моет пол" in act_lower:
        return "Идёт делать уборку"
    if "мусор" in act_lower:
        return "Несёт выбросить мусор"
    if "посуд" in act_lower:
        return "Несёт грязную посуду"
    if "туалет" in act_lower or "справляет" in act_lower:
        return "Идёт в туалет"
    if "тренир" in act_lower or "бегает" in act_lower or "отжима" in act_lower or "йог" in act_lower:
        return "Идёт на тренировку"
    if "домашнее задание" in act_lower or "урок" in act_lower:
        return "Идёт делать домашнее задание"
    if "музык" in act_lower or "гитар" in act_lower or "пианино" in act_lower or "скрипк" in act_lower:
        return "Идёт играть на музыкальном инструменте"
    if "рисует" in act_lower or "мольберт" in act_lower:
        return "Идёт к мольберту рисовать картину"
    if "ракетостро" in act_lower or "ракет" in act_lower:
        if "строит" in act_lower:
            return "Идёт строить космическую ракету"
        if "летит" in act_lower or "полет" in act_lower or "запуск" in act_lower:
            return "Идёт на стартовую площадку для запуска ракеты в космос"
        return "Идёт к космической ракете"
    if "орган" in act_lower:
        return "Идёт играть на органе"
    if "микроскоп" in act_lower:
        return "Идёт работать за микроскопом"

    # Default prefix if not already starting with "Идёт" or "Направляется"
    if act.startswith("Идёт") or act.startswith("Направляется"):
        return act
    return f"Направляется: {act}"



def get_social_dialog_info(sim_info):
    """
    Extracts deep social interaction data for single or multi-sim group dialogues:
    1. Specific Social Action (gossip, flirt, group chat, etc.)
    2. Conversation Style/Tone (pleasant, flirty, heated, boring, etc.)
    3. All Target Sim details (Name, Age, Gender, Race, Mood, Career)
    4. Relationship Status & Compatibility with each interlocutor
    """
    try:
        sim_instance = sim_info.get_sim_instance() if hasattr(sim_info, "get_sim_instance") else None
        if sim_instance is None:
            return None

        target_sim_infos = []
        seen_target_ids = set()

        def add_interlocutor(t_info):
            if t_info is not None and hasattr(t_info, "sim_id"):
                if t_info.sim_id != sim_info.sim_id and t_info.sim_id not in seen_target_ids:
                    seen_target_ids.add(t_info.sim_id)
                    target_sim_infos.append(t_info)

        all_social_interactions = []
        mixer_social_tokens = []
        posture_social_tokens = []
        primary_mixer_target = None

        def collect_inter_tokens(inter, is_mixer=False):
            if inter is None:
                return
            try:
                name_str = (getattr(inter, "__name__", "") or str(inter)).lower()
                cls_name = getattr(getattr(inter, "__class__", None), "__name__", "").lower()
                aff = getattr(inter, "affordance", None)
                aff_name = (getattr(aff, "__name__", "") or str(aff)).lower() if aff is not None else ""
                aff_cls = getattr(aff, "__class__", None)
                aff_cls_name = getattr(aff_cls, "__name__", "").lower() if aff_cls else ""

                is_actually_mixer = (
                    is_mixer
                    or getattr(inter, "is_mixer", False)
                    or (aff is not None and getattr(aff, "is_mixer", False))
                    or "mixer" in name_str
                    or "mixer" in cls_name
                    or "mixer" in aff_name
                    or "mixer" in aff_cls_name
                    or any(rk in aff_name or rk in name_str for rk in [
                        "flirt", "kiss", "hug", "romance", "woohoo", "fight", "slap",
                        "yell", "insult", "apologize", "compliment", "joke", "tickle"
                    ])
                )
                curr_list = mixer_social_tokens if is_actually_mixer else posture_social_tokens

                for attr in ["__name__", "name", "_name", "debug_name"]:
                    v = getattr(inter, attr, None)
                    if v:
                        s_v = str(v).lower()
                        curr_list.append(s_v)
                        all_social_interactions.append(s_v)
                if cls_name:
                    curr_list.append(cls_name)
                    all_social_interactions.append(cls_name)
                aff = getattr(inter, "affordance", None)
                if aff is not None:
                    aff_name = getattr(aff, "__name__", str(aff)).lower()
                    curr_list.append(aff_name)
                    all_social_interactions.append(aff_name)
                    aff_cls = getattr(aff, "__class__", None)
                    if aff_cls:
                        curr_list.append(aff_cls.__name__.lower())
                        all_social_interactions.append(aff_cls.__name__.lower())
                    if hasattr(aff, "display_name") and LocalizationHelperTuning is not None:
                        try:
                            d = LocalizationHelperTuning.get_raw_text(aff.display_name)
                            if d and is_human_readable_text(str(d)):
                                curr_list.append(str(d).lower())
                                all_social_interactions.append(str(d).lower())
                        except Exception:
                            pass
                si = getattr(inter, "super_interaction", None)
                if si is not None:
                    si_name = getattr(si, "__name__", str(si)).lower()
                    posture_social_tokens.append(si_name)
                    all_social_interactions.append(si_name)
                    si_aff = getattr(si, "affordance", None)
                    if si_aff is not None:
                        si_aff_name = getattr(si_aff, "__name__", str(si_aff)).lower()
                        posture_social_tokens.append(si_aff_name)
                        all_social_interactions.append(si_aff_name)
                if hasattr(inter, "display_name") and LocalizationHelperTuning is not None:
                    try:
                        d = LocalizationHelperTuning.get_raw_text(inter.display_name)
                        if d and is_human_readable_text(str(d)):
                            curr_list.append(str(d).lower())
                            all_social_interactions.append(str(d).lower())
                    except Exception:
                        pass
                curr_list.append(str(inter).lower())
                all_social_interactions.append(str(inter).lower())
            except Exception:
                pass

        # 1. Inspect Social Groups (Main social group & all social groups)
        for sg_getter in ["get_main_social_group", "get_all_social_groups"]:
            if hasattr(sim_instance, sg_getter):
                try:
                    res = getattr(sim_instance, sg_getter)()
                    groups = [res] if not isinstance(res, (list, tuple, set)) else list(res)
                    for sg in groups:
                        if sg is None:
                            continue
                        # SocialGroup is iterable yielding Sim objects
                        try:
                            for member in sg:
                                m_info = getattr(member, "sim_info", member)
                                add_interlocutor(m_info)
                        except Exception:
                            pass
                        # Also check methods on sg
                        for m_attr in ["sims_gen", "get_sim_infos", "get_active_sim_infos"]:
                            if hasattr(sg, m_attr):
                                try:
                                    for item in getattr(sg, m_attr)():
                                        m_info = getattr(item, "sim_info", item)
                                        add_interlocutor(m_info)
                                except Exception:
                                    pass
                        for m_field in ["members", "_members"]:
                            if hasattr(sg, m_field):
                                try:
                                    for item in getattr(sg, m_field, []):
                                        m_info = getattr(item, "sim_info", item)
                                        add_interlocutor(m_info)
                                except Exception:
                                    pass
                except Exception:
                    pass

        # 2. Inspect transition controller, queue heads, active mixers and queued items
        transitioning_inters = []
        try:
            trans_inter = get_sim_transitioning_interaction(sim_instance)
            if trans_inter is not None:
                transitioning_inters.append(trans_inter)
            for tc_obj in [
                getattr(sim_instance, "transition_controller", None),
                getattr(getattr(sim_instance, "queue", None), "transition_controller", None),
            ]:
                if tc_obj is not None:
                    t_in = getattr(tc_obj, "interaction", None) or getattr(tc_obj, "_interaction", None)
                    if t_in is not None and t_in not in transitioning_inters:
                        transitioning_inters.append(t_in)
        except Exception:
            pass

        for t_inter in transitioning_inters:
            collect_inter_tokens(t_inter, is_mixer=True)
            t_tgt = getattr(t_inter, "target", None)
            if t_tgt is not None:
                t_tgt_info = getattr(t_tgt, "sim_info", t_tgt)
                add_interlocutor(t_tgt_info)
                if primary_mixer_target is None and hasattr(t_tgt_info, "sim_id") and t_tgt_info.sim_id != sim_info.sim_id:
                    primary_mixer_target = t_tgt_info

        if hasattr(sim_instance, "queue") and sim_instance.queue is not None:
            try:
                for q_getter in ["peek_head", "get_head"]:
                    if hasattr(sim_instance.queue, q_getter):
                        try:
                            h = getattr(sim_instance.queue, q_getter)()
                            if h is not None:
                                collect_inter_tokens(h, is_mixer=False)
                                h_tgt = getattr(h, "target", None)
                                if h_tgt is not None:
                                    add_interlocutor(getattr(h_tgt, "sim_info", h_tgt))
                        except Exception:
                            pass

                for q_inter in sim_instance.queue:
                    q_tgt = getattr(q_inter, "target", None)
                    collect_inter_tokens(q_inter, is_mixer=False)
                    if q_tgt is not None:
                        add_interlocutor(getattr(q_tgt, "sim_info", q_tgt))

                if hasattr(sim_instance.queue, "mixer_interactions_gen"):
                    for mixer in sim_instance.queue.mixer_interactions_gen():
                        collect_inter_tokens(mixer, is_mixer=True)
                        tgt = getattr(mixer, "target", None)
                        if tgt is not None:
                            tgt_info = getattr(tgt, "sim_info", tgt)
                            add_interlocutor(tgt_info)
                            if primary_mixer_target is None and hasattr(tgt_info, "sim_id") and tgt_info.sim_id != sim_info.sim_id:
                                primary_mixer_target = tgt_info
            except Exception:
                pass

        # 3. Inspect strictly running interactions and their internal active mixers & social groups
        for interaction in get_sim_running_interactions(sim_instance):
            target = getattr(interaction, "target", None)
            if target is not None:
                tgt_info = getattr(target, "sim_info", target)
                add_interlocutor(tgt_info)

            # Social group on interaction
            if hasattr(interaction, "social_group") and interaction.social_group is not None:
                sg = interaction.social_group
                try:
                    for member in sg:
                        m_info = getattr(member, "sim_info", member)
                        add_interlocutor(m_info)
                except Exception:
                    pass
                for m_attr in ["sims_gen", "get_sim_infos"]:
                    if hasattr(sg, m_attr):
                        try:
                            for item in getattr(sg, m_attr)():
                                m_info = getattr(item, "sim_info", item)
                                add_interlocutor(m_info)
                        except Exception:
                            pass

            collect_inter_tokens(interaction, is_mixer=False)

            for attr_name in ["active_mixers", "_active_mixers"]:
                if hasattr(interaction, attr_name):
                    try:
                        for m in getattr(interaction, attr_name, []):
                            collect_inter_tokens(m, is_mixer=True)
                            m_tgt = getattr(m, "target", None)
                            if m_tgt is not None:
                                m_tgt_info = getattr(m_tgt, "sim_info", m_tgt)
                                add_interlocutor(m_tgt_info)
                                if primary_mixer_target is None and hasattr(m_tgt_info, "sim_id") and m_tgt_info.sim_id != sim_info.sim_id:
                                    primary_mixer_target = m_tgt_info
                    except Exception:
                        pass

        # 4. Check nearby Sims in the same room / close distance (< 4m) who are actively interacting with active sim
        if len(target_sim_infos) < 2 and services is not None:
            try:
                sim_info_mgr = services.sim_info_manager()
                if sim_info_mgr is not None:
                    for other_info in sim_info_mgr.values():
                        if other_info is None or other_info.sim_id == sim_info.sim_id or other_info.sim_id in seen_target_ids:
                            continue
                        other_inst = other_info.get_sim_instance() if hasattr(other_info, "get_sim_instance") else None
                        if other_inst is not None:
                            for other_inter in get_sim_running_interactions(other_inst):
                                if getattr(other_inter, "target", None) in (sim_instance, sim_info):
                                    inter_str = (getattr(other_inter, "__name__", "") or str(other_inter)).lower()
                                    aff = getattr(other_inter, "affordance", None)
                                    if aff is not None:
                                        inter_str += " " + (getattr(aff, "__name__", "") or str(aff)).lower()
                                    if any(pk in inter_str for pk in ["watch", "look_at", "lookat", "view_sim", "viewsim", "observe", "check_on", "checkon", "inspect"]):
                                        continue
                                    add_interlocutor(other_info)
                                    collect_inter_tokens(other_inter, is_mixer=False)
                                    break
                            if hasattr(other_inst, "queue") and other_inst.queue is not None:
                                try:
                                    for oq in other_inst.queue:
                                        if getattr(oq, "target", None) in (sim_instance, sim_info):
                                            add_interlocutor(other_info)
                                            collect_inter_tokens(oq, is_mixer=False)
                                    if hasattr(other_inst.queue, "mixer_interactions_gen"):
                                        for om in other_inst.queue.mixer_interactions_gen():
                                            if getattr(om, "target", None) in (sim_instance, sim_info):
                                                add_interlocutor(other_info)
                                                collect_inter_tokens(om, is_mixer=True)
                                except Exception:
                                    pass
            except Exception:
                pass

        if not target_sim_infos:
            return None

        # Prioritize specific mixer/childcare/romance actions over generic postures/super-interactions across ALL interactions
        actor_age = getattr(getattr(sim_info, "age", None), "name", "ADULT")
        actor_is_young_child = actor_age in ("BABY", "INFANT", "TODDLER")
        actor_is_school_child = actor_age in ("CHILD", "TEEN")
        actor_is_child = actor_is_young_child or actor_is_school_child
        target_first_age = getattr(getattr(target_sim_infos[0], "age", None), "name", "ADULT") if target_sim_infos else "ADULT"

        # Detect anger moods on actor and interlocutors
        actor_is_angry = False
        try:
            if hasattr(sim_info, "get_mood"):
                m = sim_info.get_mood()
                m_n = getattr(m, "__name__", getattr(m, "name", str(m))).lower()
                if any(ak in m_n for ak in ["angry", "enraged", "furious"]):
                    actor_is_angry = True
        except Exception:
            pass

        target_is_angry = False
        for t_info in target_sim_infos:
            try:
                if hasattr(t_info, "get_mood"):
                    tm = t_info.get_mood()
                    tm_n = getattr(tm, "__name__", getattr(tm, "name", str(tm))).lower()
                    if any(ak in tm_n for ak in ["angry", "enraged", "furious"]):
                        target_is_angry = True
                        break
            except Exception:
                pass

        cleaned_mixer_names = [int_name.replace("_", "").lower() for int_name in mixer_social_tokens if int_name]
        cleaned_posture_names = [int_name.replace("_", "").lower() for int_name in posture_social_tokens if int_name]
        cleaned_social_names = cleaned_mixer_names + cleaned_posture_names

        # Check if the active sim is the TARGET of a mean / yell / scold action from an angry interlocutor
        is_being_yelled_at = False
        is_being_scolded = False
        if target_is_angry and not actor_is_angry:
            for clean_name in cleaned_social_names:
                if any(yk in clean_name for yk in ["yellat", "yell_at", "yell", "shout", "кричать", "накричать", "кричит"]):
                    is_being_yelled_at = True
                    break
                elif any(sk in clean_name for sk in ["disciplinesim", "discipline", "scoldchild", "scold_child", "scoldteen", "scold_teen", "lecturechild", "lecture_child", "отругать", "выговор", "отчитать"]):
                    is_being_scolded = True
                    break

        found_specific = False

        if is_being_yelled_at:
            social_action_verb = "Выслушивает крики и гневные претензии от"
            found_specific = True
        elif is_being_scolded:
            social_action_verb = "Слушает строгий выговор и наставления от"
            found_specific = True
        elif actor_is_young_child:
            social_action_verb = "По-детски лепечет и общается с"
        elif actor_is_angry:
            if actor_is_school_child:
                social_action_verb = "Раздраженно огрызается и спорит с"
            else:
                social_action_verb = "Сердито и на взводе отчитывает / спорит с"
        elif target_is_angry:
            if actor_is_school_child:
                social_action_verb = "Напряженно слушает сердитые упрёки от"
            else:
                social_action_verb = "Напряженно беседует с раздраженным собеседником"
        elif actor_is_school_child:
            social_action_verb = "Болтает и делится мыслями с"
        elif target_first_age in ("BABY", "INFANT", "TODDLER"):
            social_action_verb = "Ласково общается и сюсюкает с"
        else:
            social_action_verb = "Непринужденно общается и беседует с"

        # DEBUG: Log collected tokens for diagnosis
        if all_social_interactions:
            try:
                unique_tokens = list(set(all_social_interactions))[:30]
                log("[DEBUG SOCIAL TOKENS] {} tokens collected for {}: {}".format(
                    len(all_social_interactions),
                    getattr(sim_info, "first_name", "?"),
                    " | ".join(unique_tokens[:30])
                ))
            except Exception:
                pass

        if not found_specific:
            # 1. First priority: Check active mixers (specific gestures, jokes, high-fives, hugs, kiss micro-actions)
            # 2. Second priority: Check posture and super-interactions (general chat posture, greeting posture)
            for token_batch in [cleaned_mixer_names, cleaned_posture_names]:
                if not token_batch:
                    continue
                for kw_list, a_verb in SOCIAL_ACTIONS_MAP:
                    for clean_name in token_batch:
                        for kw in kw_list:
                            if kw.replace("_", "").lower() in clean_name:
                                if isinstance(a_verb, (tuple, list)):
                                    parent_verb, child_verb = a_verb[0], a_verb[1]
                                    if actor_is_child:
                                        if "лепечет" in child_verb and actor_is_school_child:
                                            social_action_verb = "Болтает и делится мыслями с"
                                        else:
                                            social_action_verb = child_verb
                                    elif target_first_age in ("BABY", "INFANT", "TODDLER"):
                                        social_action_verb = parent_verb
                                    else:
                                        social_action_verb = "Непринужденно общается и беседует с"
                                else:
                                    social_action_verb = a_verb
                                found_specific = True
                                break
                        if found_specific:
                            break
                    if found_specific:
                        break
                if found_specific:
                    break

        # Extract Conversation Style / Context
        social_style = ""
        if hasattr(sim_instance, "get_main_social_group"):
            try:
                sg = sim_instance.get_main_social_group()
                if sg is not None:
                    ctx_name = getattr(getattr(sg, "social_context", None), "__name__", "").lower()
                    for s_key, s_label in SOCIAL_CONTEXT_TRANSLATIONS:
                        if s_key in ctx_name:
                            social_style = s_label
                            break
            except Exception:
                pass

        rel_tracker = getattr(sim_info, "relationship_tracker", None)
        if not social_style and rel_tracker is not None:
            for t_info in target_sim_infos:
                try:
                    bits = rel_tracker.get_all_bits(t_info.sim_id)
                    bits_text = " ".join([getattr(b, "__name__", str(b)).lower() for b in bits])
                    for s_key, s_label in SOCIAL_CONTEXT_TRANSLATIONS:
                        if s_key in bits_text:
                            social_style = s_label
                            break
                    if social_style:
                        break
                except Exception:
                    pass

        # Override casual/pleasant tone if anyone in conversation is angry or conflict interaction is active
        if actor_is_angry or target_is_angry or is_being_yelled_at or is_being_scolded:
            if not social_style or any(w in social_style.lower() for w in ["непринужденный", "приятный", "дружеский"]):
                social_style = "Напряженный разговор (ссора, на повышенных тонах)"

        # If an active mixer targeted a specific interlocutor, prioritize that target at index 0
        if primary_mixer_target is not None:
            for idx, t_inf in enumerate(target_sim_infos):
                if getattr(t_inf, "sim_id", None) == getattr(primary_mixer_target, "sim_id", None):
                    if idx > 0:
                        target_sim_infos.insert(0, target_sim_infos.pop(idx))
                    break

        # Build details for all interlocutors
        target_details = []
        for t_info in target_sim_infos:
            t_first = getattr(t_info, "first_name", "Сим")
            t_last = getattr(t_info, "last_name", "")
            t_full_name = f"{t_first} {t_last}".strip()

            t_age_raw = getattr(getattr(t_info, "age", None), "name", "ADULT")
            t_age = AGE_TRANSLATIONS.get(t_age_raw, "Взрослый")

            t_gender_raw = getattr(getattr(t_info, "gender", None), "name", "FEMALE")
            t_gender = GENDER_TRANSLATIONS.get(t_gender_raw, "Женский")

            t_race = get_sim_occult_info(t_info)
            t_mood = get_sim_mood_info(t_info)
            t_career = get_sim_career_info(t_info)

            # Relationship and compatibility
            rel_types_list = []
            rel_title = get_relationship_between_sims(sim_info, t_info)
            if rel_title:
                rel_types_list.append(rel_title)

            if rel_tracker is not None:
                try:
                    bits = rel_tracker.get_all_bits(t_info.sim_id)
                    bits_names = [getattr(b, "__name__", str(b)).lower() for b in bits]
                    t_is_female = (t_gender == "Женский")
                    for b_key, b_label in REL_BITS_TRANSLATIONS:
                        # Skip opposite gender bits
                        if t_is_female and b_label in ("Муж", "Брат", "Отец", "Сын", "Дедушка", "Дядя", "Внук", "Жених"):
                            continue
                        if not t_is_female and b_label in ("Жена", "Сестра", "Мать", "Дочь", "Бабушка", "Тетя", "Внучка", "Невеста"):
                            continue
                        # Skip redundant bits already expressed in rel_title
                        if any(b_label.lower() in r.lower() for r in rel_types_list):
                            continue
                        for b_name in bits_names:
                            if b_key in b_name and b_label not in rel_types_list and b_label not in ("Знакомые", "Знакомый", "Друзья", "Друг", "Подруга", "Незнакомец / Не знаком"):
                                rel_types_list.append(b_label)
                                break

                    # Compatibility
                    if hasattr(rel_tracker, "get_compatibility_level"):
                        c_level = rel_tracker.get_compatibility_level(t_info.sim_id)
                        c_name = getattr(c_level, "name", str(c_level)).lower()
                        if "bad" in c_name or "poor" in c_name or "low" in c_name:
                            rel_types_list.append("Плохая совместимость")
                        elif "good" in c_name or "high" in c_name:
                            rel_types_list.append("Высокая совместимость")
                        elif "neutral" in c_name or "normal" in c_name:
                            rel_types_list.append("Нормальная совместимость")
                except Exception:
                    pass

            if not rel_types_list:
                rel_types_list = ["Знакомый" if rel_title == "Знакомый" else "Незнакомец / Не знаком"]

            target_details.append({
                "name": t_full_name,
                "age_gender": f"{t_age}, {t_gender}",
                "race": t_race,
                "mood": t_mood,
                "career": t_career,
                "relationships": ", ".join(rel_types_list),
            })

        is_group = len(target_details) >= 2
        names_list = [t["name"] for t in target_details]

        if found_specific:
            primary_name = names_list[0] if names_list else "Сим"
            action_text = f"{social_action_verb} {primary_name}"
        else:
            if len(names_list) == 1:
                action_text = f"{social_action_verb} {names_list[0]}"
            elif len(names_list) == 2:
                action_text = f"Ведет групповой разговор с {names_list[0]} и {names_list[1]}"
            else:
                action_text = f"Ведет групповой разговор с {', '.join(names_list[:-1])} и {names_list[-1]}"

        return {
            "is_group": is_group,
            "action": action_text,
            "style": social_style,
            "targets": target_details,
        }

    except Exception as e:
        log_exception("Error getting social dialog info", e)

    return None


