        # =========================================================================
        # 0.15. РАКЕТОСТРОЕНИЕ И КОСМИЧЕСКИЕ ПОЛЕТЫ (Rocket Science & Space Exploration)
        # =========================================================================
        for inter in interactions_list:
            n = getattr(inter, "__name__", str(inter)).lower().replace("_", "")
            tgt = getattr(inter, "target", None)
