                if any(v in n for v in ["view", "look", "admire", "inspect", "observe"]) or any(v in combined for v in ["viewfrog", "frogview", "lookat"]):
                    return "Рассматривает пойманную лягушку в террариуме"
                return "Рассматривает лягушку из коллекции"

