        # 0.4. САДОВОДСТВО И РАСТЕНИЯ (Gardening: Посадка, Полив, Прополка, Урожай, Вырывание)
        # =========================================================================
        for inter in interactions_list:
            n = getattr(inter, "__name__", str(inter)).lower().replace("_", "")
            tgt = getattr(inter, "target", None)
            if tgt is None and hasattr(inter, "get_target"):
                try:
                    tgt = inter.get_target()
                except Exception:
                    tgt = None
            t = getattr(tgt, "__name__", str(tgt)).lower().replace("_", "") if tgt else ""
            combined = f"{n} {t}"

            # Skip eating / drinking produce (handled in Eating section)
            if any(k in n for k in ["eat", "consume", "drink"]):
                continue

            # Check if this is a gardening interaction on the interaction itself or target
            is_gardening = any(k in n for k in [
                "gardening", "waterplant", "waterall", "weed", "harvest",
                "uproot", "fertilize", "spraybugs", "talktoplant", "evolveplant",
                "bonsai", "cowplant", "graft", "splice", "plantseed", "planthere"
            ]) or (("plant" in n or "garden" in n) and not any(skip in n for skip in ["look", "view", "sit", "stand"]))

            if is_gardening:
                p_name = extract_plant_name(tgt, inter)
                p_suffix = f" ({p_name})" if p_name else ""

                # 1. Посадка семян / растений (Planting)
                if any(k in n for k in ["plant", "sow", "planthere", "plantseed", "plantproduce"]) and not any(k in n for k in ["water", "weed", "harvest", "uproot", "talk", "spray", "fertilize", "evolve"]):
                    return f"Сажает семена растения{p_suffix} в землю"

                # 2. Вырвать / Уничтожить с корнем (Uprooting / Disposing)
