def get_season_info() -> str:
    """Extracts current season (e.g. 'Лето', 'Осень', 'Зима', 'Весна')."""
    try:
        if services is not None:
            season_service = services.season_service()
            if season_service is not None:
                s_val = getattr(season_service, "season", None)
                if s_val is not None:
                    s_name = getattr(s_val, "name", str(s_val)).lower()
                    for k, v in SEASON_TRANSLATIONS.items():
                        if k in s_name:
                            return v
                    return s_name.capitalize()
    except Exception as e:
        log_exception("Error getting season info", e)
    return "Лето"


def get_weather_info() -> str:
    """Extracts current weather condition and temperature (e.g. 'Солнечно (Тепло)', 'Сильный ливень (Прохладно)')."""
    try:
        if services is not None:
            weather_service = services.weather_service()
            if weather_service is not None:
                # 1. Weather Type / Precipitation
                w_type = getattr(weather_service, "current_weather_type", None) or getattr(weather_service, "_current_weather_type", None)
                w_str = getattr(w_type, "name", str(w_type)).lower() if w_type else ""

                weather_label = "Ясно"
                for k, v in WEATHER_TRANSLATIONS:
                    if k in w_str:
                        weather_label = v
                        break

                # 2. Temperature
                temp_label = ""
                temp_type = getattr(weather_service, "current_temperature", None) or getattr(weather_service, "_current_temperature", None)
                if temp_type is not None:
                    t_str = getattr(temp_type, "name", str(temp_type)).lower()
                    for tk, tv in TEMP_TRANSLATIONS.items():
                        if tk in t_str:
                            temp_label = tv
                            break

                if temp_label and temp_label.lower() not in weather_label.lower():
                    return f"{weather_label} ({temp_label})"
                return weather_label
    except Exception as e:
        log_exception("Error getting weather info", e)

    return "Ясно (Тепло)"


def get_holiday_info(sim_info=None) -> str:
    """Extracts the active calendar holiday (e.g. 'Новый год', 'День любви') or 'День рождения', or 'Обычный день (нет праздника)'."""
    try:
        # 1. Check official active Seasons Holiday from holiday_service
        if services is not None:
            holiday_service = services.holiday_service()
            if holiday_service is not None:
                active_id = None
                if hasattr(holiday_service, "get_active_holiday_id"):
                    active_id = holiday_service.get_active_holiday_id()
                elif hasattr(holiday_service, "active_holiday_id"):
                    active_id = holiday_service.active_holiday_id

                if active_id:
                    if hasattr(holiday_service, "get_holiday_display_name"):
                        loc_name = holiday_service.get_holiday_display_name(active_id)
                        if loc_name:
                            try:
                                if LocalizationHelperTuning is not None:
                                    t_str = LocalizationHelperTuning.get_raw_text(loc_name)
                                    if t_str and is_human_readable_text(str(t_str)):
                                        return str(t_str)
                            except Exception:
                                pass
                            return str(loc_name)

                    if hasattr(holiday_service, "get_holiday_info_by_id"):
                        h_info = holiday_service.get_holiday_info_by_id(active_id)
                        if h_info is not None:
                            h_name = getattr(h_info, "holiday_name", None) or getattr(h_info, "name", None) or getattr(h_info, "display_name", None)
                            if h_name:
                                try:
                                    if LocalizationHelperTuning is not None:
                                        t_str = LocalizationHelperTuning.get_raw_text(h_name)
                                        if t_str and is_human_readable_text(str(t_str)):
                                            return str(t_str)
                                except Exception:
                                    pass
                                h_str = str(h_name).lower()
                                for hk, h_ru in HOLIDAY_COMMON_TRANSLATIONS.items():
                                    if hk in h_str:
                                        return h_ru
                                return str(h_name)

        # 2. Check if active sim or household member has a Birthday today
        if sim_info is not None:
            try:
                days_to_age = getattr(sim_info, "days_until_ready_to_age", None)
                if days_to_age is not None:
                    d_val = days_to_age() if callable(days_to_age) else days_to_age
                    if d_val == 0 or d_val is True:
                        return f"День рождения ({getattr(sim_info, 'first_name', 'Сим')} сегодня празднует день рождения и взрослеет!)"

                if hasattr(sim_info, "household") and sim_info.household is not None:
                    hh = sim_info.household
                    hh_sims = getattr(hh, "sim_infos", []) if hasattr(hh, "sim_infos") else []
                    for h_sim in hh_sims:
                        if h_sim and h_sim.sim_id != sim_info.sim_id:
                            h_days = getattr(h_sim, "days_until_ready_to_age", None)
                            if h_days is not None:
                                val = h_days() if callable(h_days) else h_days
                                if val == 0 or val is True:
                                    h_first = getattr(h_sim, "first_name", "")
                                    return f"День рождения у {h_first} (сегодня праздник взросления в семье!)"
            except Exception:
                pass

    except Exception as e:
        log_exception("Error getting holiday info", e)

    return "Обычный день (нет праздника)"


def get_family_relation_from_bit(bit_obj_or_name) -> str:
    """
    Returns verified family relationship type:
      'child', 'parent', 'sibling', 'grandparent', 'grandchild',
      'cousin', 'aunt_uncle', 'niece_nephew', 'stepparent', 'stepchild', 'stepsibling',
      'spouse', 'fiance',
      'son_in_law', 'daughter_in_law', 'father_in_law', 'mother_in_law', 'brother_in_law', 'sister_in_law', 'in_law'
    or None.
    Strictly filters out non-family bits with deceptive substrings like 'childhood_friend',
    'parenthood', 'sorority_sister', 'bro_code', 'family_friend'.
    """
    if bit_obj_or_name is None:
        return None

    b_raw = getattr(bit_obj_or_name, "__name__", str(bit_obj_or_name)).lower().replace(" ", "_")

    # 1. Strictly exclude non-family bits that happen to contain 'child', 'parent', 'sister', 'brother'
    FALSE_POSITIVES = [
        "childhood", "parenthood", "sorority", "fraternity",
        "bro_code", "parent_friend", "family_friend", "family_acquaintance",
        "child_of_friend", "friendly", "friend"
    ]
    if any(fake in b_raw for fake in FALSE_POSITIVES):
        return None

    # 2. In-law relations (MUST be checked before direct son/daughter/parent/sibling!)
    if "in_law" in b_raw or "inlaw" in b_raw:
        if "son" in b_raw:
            return "son_in_law"
        if "daughter" in b_raw:
            return "daughter_in_law"
        if "father" in b_raw:
            return "father_in_law"
        if "mother" in b_raw:
            return "mother_in_law"
        if "brother" in b_raw:
            return "brother_in_law"
        if "sister" in b_raw:
            return "sister_in_law"
        return "in_law"

    # 3. Grand relations (MUST be checked before child/parent to avoid grand_son matching son!)
    if any(k in b_raw for k in [
        "grandchild", "grand_child", "grandson", "grand_son", "granddaughter", "grand_daughter",
        "family_grandchild", "family_grand_child", "family_grandson", "family_grand_son",
        "family_granddaughter", "family_grand_daughter"
    ]):
        return "grandchild"

    if any(k in b_raw for k in [
        "grandparent", "grand_parent", "grandfather", "grand_father", "grandmother", "grand_mother",
        "family_grandparent", "family_grand_parent", "family_grandfather", "family_grand_father",
        "family_grandmother", "family_grand_mother"
    ]):
        return "grandparent"

    # 4. Step relations (MUST be checked before child/parent/sibling!)
    if any(k in b_raw for k in ["stepchild", "step_child", "step_son", "stepson", "step_daughter", "stepdaughter", "family_step_child"]):
        return "stepchild"
    if any(k in b_raw for k in ["stepparent", "step_parent", "step_father", "stepfather", "step_mother", "stepmother", "family_step_parent"]):
        return "stepparent"
    if any(k in b_raw for k in ["stepsibling", "step_sibling", "step_brother", "stepbrother", "step_sister", "stepsister", "family_step_sibling"]):
        return "stepsibling"

    # 5. Immediate family
    if any(k in b_raw for k in [
        "family_brother_sister", "genealogy_sibling", "sibling_brother", "sibling_sister",
        "relbit_sibling", "has_been_brother", "has_been_sister"
    ]) or b_raw in ("brother", "sister", "sibling") or any(b_raw.endswith(s) for s in ["_brother", "_sister", "_sibling"]):
        return "sibling"

    if any(k in b_raw for k in [
        "family_son_daughter", "family_child", "genealogy_child", "parentchild_child",
        "relbit_child", "has_been_child"
    ]) or b_raw in ("son", "daughter", "child") or any(b_raw.endswith(s) for s in ["_son", "_daughter", "_child"]):
        return "child"

    if any(k in b_raw for k in [
        "family_parent", "genealogy_parent", "parentchild_parent",
        "relbit_parent", "has_been_parent"
    ]) or b_raw in ("father", "mother", "parent") or any(b_raw.endswith(s) for s in ["_father", "_mother", "_parent"]):
        return "parent"

    # 6. Extended family
    if "cousin" in b_raw:
        return "cousin"
    if any(k in b_raw for k in ["aunt_uncle", "uncle", "aunt", "family_aunt_uncle"]):
        return "aunt_uncle"
    if any(k in b_raw for k in ["niece_nephew", "nephew", "niece", "family_niece_nephew"]):
        return "niece_nephew"

    # 7. Spousal relations
    if any(k in b_raw for k in ["spouse", "family_husband_wife", "husband_wife", "married"]):
        return "spouse"
    if any(k in b_raw for k in ["fiance", "engaged"]):
        return "fiance"

    return None


def get_relationship_between_sims(sim_info, target_info) -> str:
    """
    Returns an accurate, gender-appropriate relationship string from sim_info to target_info.
    Supports multiclassing: e.g. 'Девушка, Сестра', 'Жена, Сестра [ИНЦЕСТ-отношения]', 'Жена, Лучшая подруга'.
    Properly detects compound and incestuous relationships.
    Never confuses strangers with acquaintances or acquaintances with friends.
    """
    if sim_info is None or target_info is None:
        return "Незнакомец / Не знаком"

    target_id = getattr(target_info, "sim_id", None)
    sim_id = getattr(sim_info, "sim_id", None)
    if not target_id:
        return "Незнакомец / Не знаком"

    # Determine target gender
    target_gender = getattr(getattr(target_info, "gender", None), "name", "FEMALE")
    is_female = (target_gender == "FEMALE")

    rel_tracker = getattr(sim_info, "relationship_tracker", None)
    genealogy = getattr(sim_info, "genealogy", None)
    target_genealogy = getattr(target_info, "genealogy", None)

    # Collect relationship bit names if tracker exists
    bits_names = []
    if rel_tracker is not None:
        try:
            bits = rel_tracker.get_all_bits(target_id)
            bits_names = [getattr(b, "__name__", str(b)).lower() for b in bits]
        except Exception:
            pass

    # Gather genealogy ties directly from genealogy trackers
    genealogy_ties = set()
    sim_parent_ids = set()
    target_parent_ids = set()
    sim_child_ids = set()
    target_child_ids = set()

    def _collect_parents(gen, target_set):
        if gen is None:
            return
        try:
            # 1. Native Sims 4 GenealogyTracker methods
            if hasattr(gen, "get_parent_sim_ids"):
                for p_id in gen.get_parent_sim_ids():
                    if p_id:
                        target_set.add(p_id)
            if hasattr(gen, "get_parent_sim_ids_gen"):
                for p_id in gen.get_parent_sim_ids_gen():
                    if p_id:
                        target_set.add(p_id)
            if hasattr(gen, "get_parent_relation"):
                for rel_idx in (0, 1):  # 0: MOTHER, 1: FATHER
                    p_id = gen.get_parent_relation(rel_idx)
                    if p_id:
                        target_set.add(p_id)
            if hasattr(gen, "_family_relations") and isinstance(gen._family_relations, dict):
                for rel_idx in (0, 1):
                    p_id = gen._family_relations.get(rel_idx)
                    if p_id:
                        target_set.add(p_id)
            # Fallback legacy checks
            for p_attr in ["get_parent_sim_infos", "get_parents", "_parent_ids", "parent_ids"]:
                if hasattr(gen, p_attr):
                    val = getattr(gen, p_attr)
                    items = val() if callable(val) else val
                    for p in (items or []):
                        p_id = getattr(p, "sim_id", p)
                        if p_id:
                            target_set.add(p_id)
        except Exception:
            pass

    def _collect_children(gen, target_set):
        if gen is None:
            return
        try:
            if hasattr(gen, "get_children_sim_ids_gen"):
                for c_id in gen.get_children_sim_ids_gen():
                    if c_id:
                        target_set.add(c_id)
            if hasattr(gen, "get_child_sim_infos_gen"):
                for c_info in gen.get_child_sim_infos_gen():
                    c_id = getattr(c_info, "sim_id", None)
                    if c_id:
                        target_set.add(c_id)
            for c_attr in ["get_children_sim_infos", "get_children", "get_child_sim_infos", "_child_ids", "child_ids"]:
                if hasattr(gen, c_attr):
                    val = getattr(gen, c_attr)
                    items = val() if callable(val) else val
                    for c in (items or []):
                        c_id = getattr(c, "sim_id", c)
                        if c_id:
                            target_set.add(c_id)
        except Exception:
            pass

    _collect_parents(genealogy, sim_parent_ids)
    _collect_parents(target_genealogy, target_parent_ids)
    _collect_children(genealogy, sim_child_ids)
    _collect_children(target_genealogy, target_child_ids)

    # Check shared parents -> Sibling!
    if sim_parent_ids and target_parent_ids and (sim_parent_ids & target_parent_ids):
        genealogy_ties.add("sibling")

    # Check if target is parent of sim or vice versa
    if target_id in sim_parent_ids:
        genealogy_ties.add("parent")
    if sim_id and sim_id in target_parent_ids:
        genealogy_ties.add("child")
    if target_id in sim_child_ids:
        genealogy_ties.add("child")

    # Grandchild / Grandparent direct check via multi-generational link
    # (Target's parents contain Sim's child -> Target is definitely Grandchild!)
    if target_parent_ids and sim_child_ids and (target_parent_ids & sim_child_ids):
        genealogy_ties.add("grandchild")
    # (Sim's parents contain Target's child -> Target is definitely Grandparent!)
    if sim_parent_ids and target_child_ids and (sim_parent_ids & target_child_ids):
        genealogy_ties.add("grandparent")

    # In-law direct check: Target is married to Sim's child -> Son-in-law / Daughter-in-law!
    if sim_child_ids:
        try:
            target_sp = getattr(target_info, "spouse_sim_id", None)
            if target_sp and target_sp in sim_child_ids:
                genealogy_ties.add("daughter_in_law" if is_female else "son_in_law")
        except Exception:
            pass

    if genealogy is not None:
        try:
            # Children
            if hasattr(genealogy, "get_children_sim_ids_gen"):
                for c_id in genealogy.get_children_sim_ids_gen():
                    if c_id == target_id:
                        genealogy_ties.add("child")
            if hasattr(genealogy, "get_child_sim_infos_gen"):
                for c_info in genealogy.get_child_sim_infos_gen():
                    if getattr(c_info, "sim_id", None) == target_id:
                        genealogy_ties.add("child")
            for c_attr in ["get_children_sim_infos", "get_children", "get_child_sim_infos", "_child_ids", "child_ids"]:
                if hasattr(genealogy, c_attr):
                    val = getattr(genealogy, c_attr)
                    items = val() if callable(val) else val
                    for c in (items or []):
                        c_id = getattr(c, "sim_id", c)
                        if c_id == target_id:
                            genealogy_ties.add("child")

            # Siblings
            if hasattr(genealogy, "get_siblings_sim_ids_gen"):
                for s_id in genealogy.get_siblings_sim_ids_gen():
                    if s_id == target_id:
                        genealogy_ties.add("sibling")
            if hasattr(genealogy, "get_siblings_sim_infos_gen"):
                for s_info in genealogy.get_siblings_sim_infos_gen():
                    if getattr(s_info, "sim_id", None) == target_id:
                        genealogy_ties.add("sibling")
            for s_attr in ["get_sibling_sim_infos", "get_siblings", "_sibling_ids", "sibling_ids"]:
                if hasattr(genealogy, s_attr):
                    val = getattr(genealogy, s_attr)
                    items = val() if callable(val) else val
                    for s in (items or []):
                        s_id = getattr(s, "sim_id", s)
                        if s_id == target_id:
                            genealogy_ties.add("sibling")

            # Grandparents
            if hasattr(genealogy, "get_grandparent_sim_ids_gen"):
                for gp_id in genealogy.get_grandparent_sim_ids_gen():
                    if gp_id == target_id:
                        genealogy_ties.add("grandparent")
            for gp_attr in ["get_grandparent_sim_infos", "get_grandparents"]:
                if hasattr(genealogy, gp_attr):
                    val = getattr(genealogy, gp_attr)
                    items = val() if callable(val) else val
                    for gp in (items or []):
                        gp_id = getattr(gp, "sim_id", gp)
                        if gp_id == target_id:
                            genealogy_ties.add("grandparent")

            # Grandchildren
            for gc_attr in ["get_grandchild_sim_infos", "get_grandchildren"]:
                if hasattr(genealogy, gc_attr):
                    val = getattr(genealogy, gc_attr)
                    items = val() if callable(val) else val
                    for gc in (items or []):
                        gc_id = getattr(gc, "sim_id", gc)
                        if gc_id == target_id:
                            genealogy_ties.add("grandchild")

            # Check exact relationship bit from Sims 4 FamilyTreeService
            if hasattr(genealogy, "get_family_relationship_bit"):
                fam_bit = genealogy.get_family_relationship_bit(target_id)
                if fam_bit:
                    f_rel = get_family_relation_from_bit(fam_bit)
                    if f_rel:
                        genealogy_ties.add(f_rel)
        except Exception:
            pass

    # Check verified family bits from rel_tracker
    if rel_tracker is not None:
        try:
            for b in rel_tracker.get_all_bits(target_id):
                f_rel = get_family_relation_from_bit(b)
                if f_rel:
                    genealogy_ties.add(f_rel)
        except Exception:
            pass

    # Strict precedence filtering: Grandchild and In-laws must NEVER be labeled as Child/Parent/Sibling!
    if "grandchild" in genealogy_ties:
        genealogy_ties.discard("child")
    if "grandparent" in genealogy_ties:
        genealogy_ties.discard("parent")
    if "son_in_law" in genealogy_ties or "daughter_in_law" in genealogy_ties:
        genealogy_ties.discard("child")
    if "father_in_law" in genealogy_ties or "mother_in_law" in genealogy_ties:
        genealogy_ties.discard("parent")
    if "brother_in_law" in genealogy_ties or "sister_in_law" in genealogy_ties:
        genealogy_ties.discard("sibling")

    # 1. Blood / Family Relationship Detection
    blood_label = ""
    if "grandchild" in genealogy_ties:
        blood_label = "Внучка" if is_female else "Внук"
    elif "grandparent" in genealogy_ties:
        blood_label = "Бабушка" if is_female else "Дедушка"
    elif "son_in_law" in genealogy_ties:
        blood_label = "Зять (Муж дочери)"
    elif "daughter_in_law" in genealogy_ties:
        blood_label = "Невестка (Жена сына)"
    elif "father_in_law" in genealogy_ties:
        blood_label = "Свёкор / Тесть"
    elif "mother_in_law" in genealogy_ties:
        blood_label = "Свекровь / Тёща"
    elif "brother_in_law" in genealogy_ties:
        blood_label = "Деверь / Шурин / Зять"
    elif "sister_in_law" in genealogy_ties:
        blood_label = "Золовка / Свояченица / Невестка"
    elif "in_law" in genealogy_ties:
        blood_label = "Родственница по браку" if is_female else "Родственник по браку"
    elif "sibling" in genealogy_ties:
        blood_label = "Сестра" if is_female else "Брат"
    elif "parent" in genealogy_ties:
        blood_label = "Мать" if is_female else "Отец"
    elif "child" in genealogy_ties:
        blood_label = "Дочь" if is_female else "Сын"
    elif "aunt_uncle" in genealogy_ties:
        blood_label = "Тетя" if is_female else "Дядя"
    elif "niece_nephew" in genealogy_ties:
        blood_label = "Племянница" if is_female else "Племянник"
    elif "cousin" in genealogy_ties:
        blood_label = "Двоюродная сестра" if is_female else "Двоюродный брат"
    elif "stepchild" in genealogy_ties:
        blood_label = "Падчерица" if is_female else "Пасынок"
    elif "stepparent" in genealogy_ties:
        blood_label = "Мачеха" if is_female else "Отчим"
    elif "stepsibling" in genealogy_ties:
        blood_label = "Сводная сестра" if is_female else "Сводный брат"
    elif "family" in genealogy_ties:
        blood_label = "Родственница" if is_female else "Родственник"

    bits_str = " ".join(bits_names)

    # 2. Romantic / Spousal Relationship Detection
    romantic_label = ""
    is_direct_spouse = (getattr(sim_info, "spouse_sim_id", None) == target_id)
    is_spouse_bit = any(k in bits_str for k in ["spouse", "husband", "wife", "married"])
    is_spouse = (is_direct_spouse or is_spouse_bit)

    my_spouse_id = getattr(sim_info, "spouse_sim_id", None)
    target_spouse_id = getattr(target_info, "spouse_sim_id", None)

    is_cheating_me = (my_spouse_id is not None and my_spouse_id != target_id)
    is_cheating_target = (target_spouse_id is not None and target_spouse_id != sim_id)

    if is_spouse:
        romantic_label = "Жена" if is_female else "Муж"
    elif any(k in bits_str for k in ["engaged", "fiance"]):
        romantic_label = "Невеста" if is_female else "Жених"
    elif any(k in bits_str for k in ["significant_other", "sweethearts", "lovebirds", "boyfriend_girlfriend", "lovers"]) or any(k in bits_str for k in ["affair", "cheating"]):
        if is_cheating_me and is_cheating_target:
            romantic_label = "Любовница [двойная измена / оба в браке]" if is_female else "Любовник [двойная измена / оба в браке]"
        elif is_cheating_me:
            romantic_label = "Любовница [роман на стороне при живой жене]" if is_female else "Любовник [роман на стороне при живом муже]"
        elif is_cheating_target:
            romantic_label = "Любовница [замужняя женщина / измена её мужу]" if is_female else "Любовник [женатый мужчина / измена его жене]"
        elif any(k in bits_str for k in ["lovers", "affair", "cheating"]):
            romantic_label = "Любовница" if is_female else "Любовник"
        else:
            romantic_label = "Девушка" if is_female else "Парень"
    elif "crush" in bits_str:
        romantic_label = "Симпатия / Влюбленность"
    else:
        # Check romance track score and explicit romance relationship bits
        r_score = 0
        if rel_tracker is not None:
            try:
                rel = None
                if hasattr(rel_tracker, "get_relationship"):
                    rel = rel_tracker.get_relationship(target_id)
                elif hasattr(rel_tracker, "_find_relationship"):
                    rel = rel_tracker._find_relationship(target_id)
                if rel is not None:
                    tracks = getattr(rel, "relationship_tracks", {}) or {}
                    if isinstance(tracks, dict):
                        for track_key, track_inst in tracks.items():
                            t_name = str(getattr(track_inst, "stat_type", track_key)).lower()
                            if "romance" in t_name or "romantic" in t_name:
                                get_val = getattr(track_inst, "get_value", None)
                                if callable(get_val):
                                    r_score = max(r_score, get_val())
                                elif hasattr(track_inst, "value"):
                                    r_score = max(r_score, track_inst.value)
            except Exception:
                pass

        # Check for explicit romance status bits (excluding physical attraction like WW 'attracted'/'desirable')
        has_actual_romance_bit = False
        for b_n in bits_names:
            if any(k in b_n for k in [
                "romanticinterest", "romantic_interest",
                "lovebirds", "sweethearts", "lovers",
                "first_kiss", "firstkiss", "have_kissed",
                "woohoo_partner", "friends_with_benefits"
            ]):
                has_actual_romance_bit = True
                break

        # In The Sims 4, romance must be established (score >= 15) or have an explicit romance bit
        if (r_score >= 15) or has_actual_romance_bit:
            if is_cheating_me and is_cheating_target:
                romantic_label = "Любовница [двойная интрижка / оба в браке]" if is_female else "Любовник [двойная интрижка / оба в браке]"
            elif is_cheating_me:
                romantic_label = "Любовница (интрижка на стороне при живой жене)" if is_female else "Любовник (интрижка на стороне при живом муже)"
            elif is_cheating_target:
                romantic_label = "Любовница (замужняя интрижка)" if is_female else "Любовник (женатый партнер)"
            else:
                romantic_label = "Романтический интерес"

    # 3. Friendship / Social Relationship Detection
    friend_label = ""
    f_score = 0
    if rel_tracker is not None:
        try:
            f_score = rel_tracker.get_relationship_score(target_id)
        except Exception:
            f_score = 0

    if any(k in bits_str for k in ["best_friend", "bestfriend", "bff"]):
        friend_label = "Лучшая подруга" if is_female else "Лучший друг"
    elif any(k in bits_str for k in ["good_friends", "goodfriends", "good_friend"]):
        friend_label = "Хорошая подруга" if is_female else "Хороший друг"
    elif any(k in bits_str for k in ["nemesis", "enemy", "enemies"]):
        friend_label = "Заклятый враг" if "nemesis" in bits_str else "Враг"
    elif any(k in bits_str for k in ["disliked", "despised"]):
        friend_label = "Неприязнь"
    elif "roommate" in bits_str:
        friend_label = "Соседка по дому" if is_female else "Сосед по дому"
    elif "coworker" in bits_str:
        friend_label = "Коллега по работе"
    else:
        is_actual_friend = False
        for b_n in bits_names:
            if b_n in ["friendship_friend", "relationshipbit_friendship_friend"] or (b_n.endswith("_friend") and not any(skip in b_n for skip in ["acquaintance", "neutral", "good", "best"])):
                is_actual_friend = True
                break
        if is_actual_friend or f_score >= 35:
            friend_label = "Подруга" if is_female else "Друг"
        elif any(k in bits_str for k in ["acquaintance", "has_met", "neutral", "introduced"]) or f_score > 0:
            friend_label = "Знакомая" if is_female else "Знакомый"

    # 4. Multiclassing Assembly
    classes = []
    if romantic_label:
        classes.append(romantic_label)

    # Social / Friendship tie
    if friend_label and friend_label != "Незнакомец / Не знаком":
        # If romantic label exists (e.g. Жена), only include high-impact friend roles (Лучший друг, Враг)
        if romantic_label:
            if any(k in friend_label.lower() for k in ["лучш", "враг", "недруг", "сосед"]):
                if friend_label not in classes:
                    classes.append(friend_label)
        else:
            # When combined with blood/family, always include friend status (e.g. "Знакомый, Брат", "Лучшая подруга, Мать")
            if friend_label not in classes:
                classes.append(friend_label)

    # Blood / Family tie
    if blood_label and blood_label not in classes:
        classes.append(blood_label)

    # Incest flag: if both romantic and family ties are present, or explicit incest bit found
    is_incest = False
    if get_context_flag("incest"):
        if (romantic_label and blood_label) or any(k in bits_str for k in ["incest", "incestuous"]):
            is_incest = True

    if classes:
        res = ", ".join(classes)
        if is_incest:
            res += " [инцест]"
        return res

    if friend_label:
        return friend_label

    return "Незнакомец / Не знаком"


def get_sim_room_and_outdoor(sim_instance):
    """
    Returns (room_id, is_outside) for a Sim instance using TS4 build_buy and native properties.
    """
    if sim_instance is None:
        return (0, True)

    room_id = 0
    is_outside = False

    # 1. Try build_buy.get_room_id
    if services is not None:
        try:
            import build_buy
            zone_id = services.current_zone_id()
            pos = getattr(sim_instance, "position", None)
            level = getattr(getattr(sim_instance, "location", None), "level", 0)
            if pos is not None and zone_id is not None:
                room_id = build_buy.get_room_id(zone_id, pos, level)
                if room_id == 0:
                    is_outside = True
                else:
                    is_outside = False
                return (room_id, is_outside)
        except Exception:
            pass

    # 2. Fallback to sim_instance.is_outside
    if hasattr(sim_instance, "is_outside"):
        try:
            val = sim_instance.is_outside
            is_outside = val() if callable(val) else bool(val)
        except Exception:
            is_outside = False

    # 3. Fallback to sim_instance.room_id
    if hasattr(sim_instance, "room_id"):
        try:
            r_val = sim_instance.room_id
            room_id = r_val() if callable(r_val) else int(r_val)
            if room_id == 0:
                is_outside = True
        except Exception:
            pass

    return (room_id, is_outside)


def get_nearby_sims_info(sim_info, max_sims: int = 5, exclude_sim_ids: set = None) -> list:
    """
    Scans for Sims physically close to the active Sim (in the same room or within 20 meters).
    Extracts:
    1. Full Name
    2. Relationship to active Sim (Spouse, Son, Daughter, Father, Mother, Sibling, Friend, etc.)
    3. Mood / Emotion
    4. Current Activity / Action
    5. Proximity (In same room / Nearby in room / In yard outside / In adjacent room)
    Returns a list of formatted strings.
    """
    nearby_list = []
    try:
        sim_instance = sim_info.get_sim_instance() if hasattr(sim_info, "get_sim_instance") else None
        if sim_instance is None or services is None:
            return []

        sim_pos = getattr(sim_instance, "position", None)
        if sim_pos is None:
            return []

        if exclude_sim_ids is None:
            exclude_sim_ids = set()

        sim_room_id, sim_is_outside = get_sim_room_and_outdoor(sim_instance)

        sim_mgr = services.sim_info_manager()
        if sim_mgr is None or not hasattr(sim_mgr, "instanced_sims_gen"):
            return []

        candidates = []
        for other_sim in sim_mgr.instanced_sims_gen():
            if other_sim is None or other_sim is sim_instance:
                continue

            other_info = getattr(other_sim, "sim_info", None)
            if other_info is None or getattr(other_info, "is_pet", False):
                continue

            other_id = getattr(other_info, "sim_id", None)
            if other_id and other_id in exclude_sim_ids:
                continue

            other_pos = getattr(other_sim, "position", None)
            if other_pos is None:
                continue

            try:
                dist = (sim_pos - other_pos).magnitude()
            except Exception:
                continue

            other_room_id, other_is_outside = get_sim_room_and_outdoor(other_sim)
            same_room = (not sim_is_outside and not other_is_outside and sim_room_id != 0 and sim_room_id == other_room_id)

            # Check if this other sim is an interlocutor in active social dialog
            is_talking_to = False
            if hasattr(sim_instance, "get_all_running_and_queued_interactions"):
                try:
                    for inter in sim_instance.get_all_running_and_queued_interactions():
                        if getattr(inter, "target", None) is other_sim or getattr(inter, "target", None) is other_info:
                            is_talking_to = True
                            break
                except Exception:
                    pass

            # Proximity criteria: in the same room (up to 30m) or within 20m
            if same_room or dist <= 20.0:
                prio_score = 0
                if is_talking_to:
                    prio_score += 300
                if same_room:
                    prio_score += 150
                if getattr(other_info, "household_id", None) == getattr(sim_info, "household_id", None):
                    prio_score += 50
                prio_score -= int(dist * 2)

                candidates.append((prio_score, dist, same_room, sim_is_outside, other_is_outside, other_info, other_sim))

        # Sort by priority score (highest score first)
        candidates.sort(key=lambda x: x[0], reverse=True)

        for prio_score, dist, same_room, sim_is_outside, other_is_outside, other_info, other_sim in candidates[:max_sims]:
            first_name = getattr(other_info, "first_name", "Сим")
            last_name = getattr(other_info, "last_name", "")
            other_full_name = f"{first_name} {last_name}".strip()

            # Relationship: accurate single gender-appropriate title
            rel_str = get_relationship_between_sims(sim_info, other_info)

            # Mood
            other_mood = get_sim_mood_info(other_info)

            # Activity
            other_activity = get_current_activity(other_info)

            # Location / Proximity formatting
            if dist <= 2.5:
                if same_room or (not sim_is_outside and not other_is_outside):
                    loc_str = "Рядом в комнате (в паре шагов)"
                elif sim_is_outside and other_is_outside:
                    loc_str = "Стоит рядом (в паре шагов)"
                else:
                    loc_str = "Рядом (в паре шагов)"
            elif dist <= 6.0:
                if same_room:
                    loc_str = "В этой же комнате"
                elif not sim_is_outside and not other_is_outside:
                    loc_str = "В соседней комнате в доме"
                elif not sim_is_outside and other_is_outside:
                    loc_str = "На улице возле дома"
                elif sim_is_outside and not other_is_outside:
                    loc_str = "Внутри дома"
                else:
                    loc_str = "На улице во дворе"
            elif dist <= 12.0:
                if same_room:
                    loc_str = "В другом конце комнаты"
                elif not sim_is_outside and not other_is_outside:
                    loc_str = "В соседней комнате в доме"
                elif not sim_is_outside and other_is_outside:
                    loc_str = "На улице во дворе"
                elif sim_is_outside and not other_is_outside:
                    loc_str = "Внутри дома"
                else:
                    loc_str = "Во дворе на улице (в нескольких метрах)"
            else:
                if not sim_is_outside and not other_is_outside:
                    loc_str = "В другой части дома"
                elif other_is_outside:
                    loc_str = "На улице во дворе (в отдалении)"
                else:
                    loc_str = "Внутри дома"

            n_entry = f"{other_full_name} ({rel_str}, Настроение: {other_mood}, Действие: {other_activity}, Локация: {loc_str})"
            if is_werewolf_enraged(other_info):
                n_entry += " [ВНИМАНИЕ: Оборотень в ярости!]"
            nearby_list.append(n_entry)

    except Exception as e:
        log_exception("Error getting nearby sims info", e)

    return nearby_list


def _get_info_by_id(sim_id, sim_info_mgr):
    if not sim_id or sim_info_mgr is None:
        return None
    try:
        return sim_info_mgr.get(int(sim_id))
    except Exception:
        return None


def _get_sim_children_infos(s_info, sim_info_mgr):
    """Returns list of SimInfo objects for children of s_info."""
    c_set = set()
    if s_info is None or sim_info_mgr is None:
        return []
    genealogy = getattr(s_info, "genealogy", None)
    if genealogy is not None:
        if hasattr(genealogy, "get_children_sim_ids_gen"):
            try:
                for c_id in genealogy.get_children_sim_ids_gen():
                    if c_id:
                        c_set.add(c_id)
            except Exception:
                pass
        if hasattr(genealogy, "get_child_sim_infos_gen"):
            try:
                for c_inf in genealogy.get_child_sim_infos_gen():
                    cid = getattr(c_inf, "sim_id", None)
                    if cid:
                        c_set.add(cid)
            except Exception:
                pass
        for c_attr in ["_child_ids", "child_ids", "_children_ids", "children_ids"]:
            if hasattr(genealogy, c_attr):
                try:
                    for cid in getattr(genealogy, c_attr, []):
                        if cid:
                            c_set.add(cid)
                except Exception:
                    pass
    for direct_attr in ["get_children", "get_child_sim_infos"]:
        if hasattr(s_info, direct_attr):
            try:
                res = getattr(s_info, direct_attr)()
                if res:
                    for c in res:
                        cid = getattr(c, "sim_id", c)
                        if cid:
                            c_set.add(cid)
            except Exception:
                pass
    rt = getattr(s_info, "relationship_tracker", None)
    if rt is not None:
        try:
            rel_list = []
            if hasattr(rt, "_relationships"):
                rel_list = list(rt._relationships.values())
            elif hasattr(rt, "get_all_relationships"):
                rel_list = list(rt.get_all_relationships())
            for rel in rel_list:
                tid = getattr(rel, "sim_id_a", None)
                if tid == s_info.sim_id:
                    tid = getattr(rel, "sim_id_b", None)
                if tid and tid not in c_set:
                    bits = []
                    if hasattr(rel, "_bits"):
                        bits = list(rel._bits.keys())
                    elif hasattr(rt, "get_all_bits"):
                        bits = rt.get_all_bits(tid)
                    for b in bits:
                        b_str = getattr(b, "__name__", str(b)).lower()
                        if any(k in b_str for k in ["family_son_daughter", "family_child", "genealogy_child", "parentchild_child"]):
                            c_set.add(tid)
                            break
        except Exception:
            pass
    res_list = []
    for cid in c_set:
        inf = _get_info_by_id(cid, sim_info_mgr)
        if inf is not None:
            res_list.append(inf)
    return res_list


def _get_sim_parent_infos(s_info, sim_info_mgr):
    """Returns list of SimInfo objects for parents of s_info."""
    p_set = set()
    if s_info is None or sim_info_mgr is None:
        return []
    genealogy = getattr(s_info, "genealogy", None)
    if genealogy is not None:
        if hasattr(genealogy, "get_parent_sim_ids"):
            try:
                for pid in genealogy.get_parent_sim_ids():
                    if pid:
                        p_set.add(pid)
            except Exception:
                pass
        if hasattr(genealogy, "get_parent_sim_ids_gen"):
            try:
                for pid in genealogy.get_parent_sim_ids_gen():
                    if pid:
                        p_set.add(pid)
            except Exception:
                pass
        if hasattr(genealogy, "get_parent_relation"):
            try:
                for rel_idx in (0, 1):
                    pid = genealogy.get_parent_relation(rel_idx)
                    if pid:
                        p_set.add(pid)
            except Exception:
                pass
        if hasattr(genealogy, "_family_relations") and isinstance(genealogy._family_relations, dict):
            try:
                for rel_idx in (0, 1):
                    pid = genealogy._family_relations.get(rel_idx)
                    if pid:
                        p_set.add(pid)
            except Exception:
                pass
        for p_attr in ["_parent_ids", "parent_ids"]:
            if hasattr(genealogy, p_attr):
                try:
                    for pid in getattr(genealogy, p_attr, []):
                        if pid:
                            p_set.add(pid)
                except Exception:
                    pass
    for direct_attr in ["get_parents", "get_parent_sim_infos"]:
        if hasattr(s_info, direct_attr):
            try:
                res = getattr(s_info, direct_attr)()
                if res:
                    for p in res:
                        pid = getattr(p, "sim_id", p)
                        if pid:
                            p_set.add(pid)
            except Exception:
                pass
    rt = getattr(s_info, "relationship_tracker", None)
    if rt is not None:
        try:
            rel_list = []
            if hasattr(rt, "_relationships"):
                rel_list = list(rt._relationships.values())
            elif hasattr(rt, "get_all_relationships"):
                rel_list = list(rt.get_all_relationships())
            for rel in rel_list:
                tid = getattr(rel, "sim_id_a", None)
                if tid == s_info.sim_id:
                    tid = getattr(rel, "sim_id_b", None)
                if tid and tid not in p_set:
                    bits = []
                    if hasattr(rel, "_bits"):
                        bits = list(rel._bits.keys())
                    elif hasattr(rt, "get_all_bits"):
                        bits = rt.get_all_bits(tid)
                    for b in bits:
                        b_str = getattr(b, "__name__", str(b)).lower()
                        if any(k in b_str for k in ["family_parent", "genealogy_parent", "parentchild_parent"]):
                            p_set.add(tid)
                            break
        except Exception:
            pass
    res_list = []
    for pid in p_set:
        inf = _get_info_by_id(pid, sim_info_mgr)
        if inf is not None:
            res_list.append(inf)
    return res_list


def _get_sim_sibling_infos(s_info, sim_info_mgr):
    """Returns list of SimInfo objects for siblings of s_info."""
    s_set = set()
    if s_info is None or sim_info_mgr is None:
        return []
    genealogy = getattr(s_info, "genealogy", None)
    if genealogy is not None:
        if hasattr(genealogy, "get_siblings_sim_ids_gen"):
            try:
                for sid in genealogy.get_siblings_sim_ids_gen():
                    if sid:
                        s_set.add(sid)
            except Exception:
                pass
        for s_attr in ["_sibling_ids", "sibling_ids"]:
            if hasattr(genealogy, s_attr):
                try:
                    for sid in getattr(genealogy, s_attr, []):
                        if sid:
                            s_set.add(sid)
                except Exception:
                    pass
    for direct_attr in ["get_siblings", "get_sibling_sim_infos"]:
        if hasattr(s_info, direct_attr):
            try:
                res = getattr(s_info, direct_attr)()
                if res:
                    for s in res:
                        sid = getattr(s, "sim_id", s)
                        if sid:
                            s_set.add(sid)
            except Exception:
                pass
    # Find children of parents (excluding s_info)
    parents = _get_sim_parent_infos(s_info, sim_info_mgr)
    for p in parents:
        p_children = _get_sim_children_infos(p, sim_info_mgr)
        for pc in p_children:
            pcid = getattr(pc, "sim_id", None)
            if pcid and pcid != s_info.sim_id:
                s_set.add(pcid)
    rt = getattr(s_info, "relationship_tracker", None)
    if rt is not None:
        try:
            rel_list = []
            if hasattr(rt, "_relationships"):
                rel_list = list(rt._relationships.values())
            elif hasattr(rt, "get_all_relationships"):
                rel_list = list(rt.get_all_relationships())
            for rel in rel_list:
                tid = getattr(rel, "sim_id_a", None)
                if tid == s_info.sim_id:
                    tid = getattr(rel, "sim_id_b", None)
                if tid and tid not in s_set:
                    bits = []
                    if hasattr(rel, "_bits"):
                        bits = list(rel._bits.keys())
                    elif hasattr(rt, "get_all_bits"):
                        bits = rt.get_all_bits(tid)
                    for b in bits:
                        b_str = getattr(b, "__name__", str(b)).lower()
                        if any(k in b_str for k in ["family_brother_sister", "genealogy_sibling", "sibling_brother", "sibling_sister"]):
                            s_set.add(tid)
                            break
        except Exception:
            pass
    res_list = []
    for sid in s_set:
        inf = _get_info_by_id(sid, sim_info_mgr)
        if inf is not None:
            res_list.append(inf)
    return res_list


def _get_sim_spouses_and_partners_infos(s_info, sim_info_mgr):
    """
    Returns list of tuples: (other_sim_info, relationship_type)
    relationship_type: 'spouse', 'fiance', 'partner'
    """
    partners = []
    seen = set()
    if s_info is None or sim_info_mgr is None:
        return []
    
    # 1. spouse_sim_id
    sp_id = getattr(s_info, "spouse_sim_id", None)
    if sp_id:
        sp_inf = _get_info_by_id(sp_id, sim_info_mgr)
        if sp_inf and sp_id not in seen and sp_id != s_info.sim_id:
            partners.append((sp_inf, "spouse"))
            seen.add(sp_id)

    # 2. genealogy
    gen = getattr(s_info, "genealogy", None)
    if gen is not None:
        for s_attr in ["get_spouse_sim_info", "get_spouse"]:
            if hasattr(gen, s_attr):
                try:
                    res = getattr(gen, s_attr)()
                    rid = getattr(res, "sim_id", None)
                    if rid and rid not in seen and rid != s_info.sim_id:
                        partners.append((res, "spouse"))
                        seen.add(rid)
                except Exception:
                    pass
        for sid_attr in ["_spouse_id", "spouse_id"]:
            if hasattr(gen, sid_attr):
                val = getattr(gen, sid_attr, None)
                if val and val not in seen and val != s_info.sim_id:
                    sinf = _get_info_by_id(val, sim_info_mgr)
                    if sinf:
                        partners.append((sinf, "spouse"))
                        seen.add(val)

    # 3. relationship tracker
    rt = getattr(s_info, "relationship_tracker", None)
    if rt is not None:
        try:
            rel_list = []
            if hasattr(rt, "_relationships"):
                rel_list = list(rt._relationships.values())
            elif hasattr(rt, "get_all_relationships"):
                rel_list = list(rt.get_all_relationships())
            
            for rel in rel_list:
                tid = getattr(rel, "sim_id_a", None)
                if tid == s_info.sim_id:
                    tid = getattr(rel, "sim_id_b", None)
                if not tid or tid in seen or tid == s_info.sim_id:
                    continue
                
                bits = []
                if hasattr(rel, "_bits"):
                    bits = list(rel._bits.keys())
                elif hasattr(rt, "get_all_bits"):
                    bits = rt.get_all_bits(tid)
                
                bits_names = [getattr(b, "__name__", str(b)).lower() for b in bits]
                bits_str = " ".join(bits_names)
                
                if any(k in bits_str for k in ["married", "family_husband_wife", "spouse"]):
                    t_inf = _get_info_by_id(tid, sim_info_mgr)
                    if t_inf:
                        partners.append((t_inf, "spouse"))
                        seen.add(tid)
                elif any(k in bits_str for k in ["engaged", "fiance"]):
                    t_inf = _get_info_by_id(tid, sim_info_mgr)
                    if t_inf:
                        partners.append((t_inf, "fiance"))
                        seen.add(tid)
                elif any(k in bits_str for k in ["significant_other", "boyfriend_girlfriend", "sweethearts", "lovebirds"]):
                    t_inf = _get_info_by_id(tid, sim_info_mgr)
                    if t_inf:
                        partners.append((t_inf, "partner"))
                        seen.add(tid)
        except Exception:
            pass

    return partners


