def get_sim_family_info(sim_info, max_relatives: int = None) -> list:
    """
    Extracts the Sim's complete family, romantic partners, in-laws, and extended relatives:
    - Spouses, fiances, partners, lovers
    - Children (sons, daughters, stepchildren)
    - Parents (father, mother, stepparents)
    - Siblings (brothers, sisters, stepsiblings)
    - Grandparents, grandchildren
    - Spouses of children (daughter-in-law / невестка, son-in-law / зять)
    - Relatives of daughter-in-law / son-in-law (сваты, братья/сестры невестки/зятя)
    - Spouses and children of siblings (жена брата, муж сестры, племянники/племянницы)
    - Spouse's parents & siblings (тесть, тёща, свёкор, свекровь, шурин, деверь, золовка, свояченица)
    - Aunts, uncles, cousins
    Returns a list of formatted strings.
    """
    family_list = []
    try:
        if services is None:
            return []

        if max_relatives is None:
            max_relatives = get_genealogy_max_relatives()

        sim_info_mgr = services.sim_info_manager()
        if sim_info_mgr is None:
            return []

        rel_tracker = getattr(sim_info, "relationship_tracker", None)
        household_id = getattr(sim_info, "household_id", None)

        found_sim_ids = set()
        candidates = []  # (priority_order, rel_label, rel_sim_info)

        def add_family_member(prio, rel_type_default, r_id_or_info):
            if not r_id_or_info:
                return
            if isinstance(r_id_or_info, int) or isinstance(r_id_or_info, str):
                try:
                    r_id = int(r_id_or_info)
                    r_info = sim_info_mgr.get(r_id)
                except Exception:
                    return
            else:
                r_info = r_id_or_info
                r_id = getattr(r_info, "sim_id", None)

            if r_info is None or r_id is None or r_id == sim_info.sim_id or r_id in found_sim_ids:
                return

            gender_name = getattr(getattr(r_info, "gender", None), "name", "MALE")

            # Refine title by gender
            if rel_type_default == "Спутник":
                label = "Муж" if gender_name == "MALE" else "Жена"
            elif rel_type_default == "Ребенок":
                label = "Сын" if gender_name == "MALE" else "Дочь"
            elif rel_type_default == "Родитель":
                label = "Отец" if gender_name == "MALE" else "Мать"
            elif rel_type_default == "Сиблинг":
                label = "Брат" if gender_name == "MALE" else "Сестра"
            elif rel_type_default == "Дедушка/Бабушка":
                label = "Дедушка" if gender_name == "MALE" else "Бабушка"
            elif rel_type_default == "Внук/Внучка":
                label = "Внук" if gender_name == "MALE" else "Внучка"
            else:
                label = rel_type_default

            candidates.append((prio, label, r_info))
            found_sim_ids.add(r_id)

        # 1. Direct Spouses & Partners of sim_info
        direct_partners = _get_sim_spouses_and_partners_infos(sim_info, sim_info_mgr)
        if get_genealogy_type_flag("spouses"):
            for p_inf, p_type in direct_partners:
                p_gender = getattr(getattr(p_inf, "gender", None), "name", "FEMALE")
                if p_type == "spouse":
                    add_family_member(1, "Спутник", p_inf)
                elif p_type == "fiance":
                    label = "Жених" if p_gender == "MALE" else "Невеста"
                    add_family_member(1, label, p_inf)
                else:
                    label = "Парень" if p_gender == "MALE" else "Девушка"
                    add_family_member(1, label, p_inf)

        # 2. Direct Children of sim_info
        direct_children = _get_sim_children_infos(sim_info, sim_info_mgr)
        if get_genealogy_type_flag("children"):
            for c_inf in direct_children:
                add_family_member(2, "Ребенок", c_inf)

        # 3. Direct Parents of sim_info
        direct_parents = _get_sim_parent_infos(sim_info, sim_info_mgr)
        if get_genealogy_type_flag("parents"):
            for p_inf in direct_parents:
                add_family_member(3, "Родитель", p_inf)

        # 4. Direct Siblings of sim_info
        direct_siblings = _get_sim_sibling_infos(sim_info, sim_info_mgr)
        if get_genealogy_type_flag("siblings"):
            for s_inf in direct_siblings:
                add_family_member(4, "Сиблинг", s_inf)

        # 5. Direct Grandparents of sim_info
        if get_genealogy_type_flag("grandparents"):
            for p_inf in direct_parents:
                gp_list = _get_sim_parent_infos(p_inf, sim_info_mgr)
                for gp_inf in gp_list:
                    p_g = getattr(getattr(p_inf, "gender", None), "name", "MALE")
                    gp_g = getattr(getattr(gp_inf, "gender", None), "name", "MALE")
                    side = "со стороны отца" if p_g == "MALE" else "со стороны матери"
                    title = "Дедушка" if gp_g == "MALE" else "Бабушка"
                    add_family_member(5, f"{title} ({side})", gp_inf)

        # 6. Direct Grandchildren of sim_info
        if get_genealogy_type_flag("grandchildren"):
            for c_inf in direct_children:
                gc_list = _get_sim_children_infos(c_inf, sim_info_mgr)
                for gc_inf in gc_list:
                    c_g = getattr(getattr(c_inf, "gender", None), "name", "MALE")
                    gc_g = getattr(getattr(gc_inf, "gender", None), "name", "MALE")
                    title = "Внук" if gc_g == "MALE" else "Внучка"
                    sub = f"сын {'сына' if c_g == 'MALE' else 'дочери'}" if gc_g == "MALE" else f"дочь {'сына' if c_g == 'MALE' else 'дочери'}"
                    add_family_member(6, f"{title} ({sub})", gc_inf)

        # 7. Spouses of Children (Невестка, Зять, Жена сына, Муж дочери) AND their relatives (Сваты, братья/сестры невестки/зятя)
        for c_inf in direct_children:
            c_name = getattr(c_inf, "first_name", "Ребенок")
            c_gender = getattr(getattr(c_inf, "gender", None), "name", "MALE")
            c_is_male = (c_gender == "MALE")

            c_partners = _get_sim_spouses_and_partners_infos(c_inf, sim_info_mgr)
            for cp_inf, cp_type in c_partners:
                cp_id = getattr(cp_inf, "sim_id", None)
                if not cp_id or cp_id == sim_info.sim_id:
                    continue
                cp_gender = getattr(getattr(cp_inf, "gender", None), "name", "FEMALE")
                cp_is_male = (cp_gender == "MALE")

                if get_genealogy_type_flag("child_spouses"):
                    if cp_type == "spouse":
                        if c_is_male:
                            label = f"Жена сына (Невестка / Сноха) [супруга: {c_name}]" if not cp_is_male else f"Муж сына (Супруг сына) [супруг: {c_name}]"
                        else:
                            label = f"Муж дочери (Зять) [супруг: {c_name}]" if cp_is_male else f"Жена дочери (Супруга дочери) [супруга: {c_name}]"
                    elif cp_type == "fiance":
                        if c_is_male:
                            label = f"Невеста сына [помолвлена с: {c_name}]" if not cp_is_male else f"Жених сына [помолвлен с: {c_name}]"
                        else:
                            label = f"Жених дочери [помолвлен с: {c_name}]" if cp_is_male else f"Невеста дочери [помолвлена с: {c_name}]"
                    else:
                        if c_is_male:
                            label = f"Девушка сына [пара: {c_name}]" if not cp_is_male else f"Парень сына [пара: {c_name}]"
                        else:
                            label = f"Парень дочери [пара: {c_name}]" if cp_is_male else f"Девушка дочери [пара: {c_name}]"

                    add_family_member(7, label, cp_inf)

                # 8. Relatives of Child's Spouse (Сваты: родители невестки/зятя, братья/сестры невестки/зятя)
                if get_genealogy_type_flag("child_in_laws"):
                    in_law_target_label = "невестки" if (c_is_male and not cp_is_male) else ("зятя" if (not c_is_male and cp_is_male) else "супруга/супруги ребенка")
                    cp_parents = _get_sim_parent_infos(cp_inf, sim_info_mgr)
                    for cpp_inf in cp_parents:
                        cpp_id = getattr(cpp_inf, "sim_id", None)
                        if not cpp_id or cpp_id == sim_info.sim_id:
                            continue
                        cpp_gender = getattr(getattr(cpp_inf, "gender", None), "name", "MALE")
                        cpp_is_male = (cpp_gender == "MALE")
                        p_label = f"Сват (Отец {in_law_target_label})" if cpp_is_male else f"Сватья (Мать {in_law_target_label})"
                        add_family_member(8, p_label, cpp_inf)

                    cp_siblings = _get_sim_sibling_infos(cp_inf, sim_info_mgr)
                    for cps_inf in cp_siblings:
                        cps_id = getattr(cps_inf, "sim_id", None)
                        if not cps_id or cps_id == sim_info.sim_id:
                            continue
                        cps_gender = getattr(getattr(cps_inf, "gender", None), "name", "MALE")
                        cps_is_male = (cps_gender == "MALE")
                        s_label = f"Брат {in_law_target_label}" if cps_is_male else f"Сестра {in_law_target_label}"
                        add_family_member(8, s_label, cps_inf)

        # 9. Siblings' Spouses and Children (Жена брата, Муж сестры, Племянники/Племянницы)
        if get_genealogy_type_flag("sibling_family"):
            for s_inf in direct_siblings:
                s_name = getattr(s_inf, "first_name", "Сиблинг")
                s_gender = getattr(getattr(s_inf, "gender", None), "name", "MALE")
                s_is_male = (s_gender == "MALE")

                s_partners = _get_sim_spouses_and_partners_infos(s_inf, sim_info_mgr)
                for sp_inf, sp_type in s_partners:
                    sp_id = getattr(sp_inf, "sim_id", None)
                    if not sp_id or sp_id == sim_info.sim_id:
                        continue
                    sp_gender = getattr(getattr(sp_inf, "gender", None), "name", "FEMALE")
                    sp_is_male = (sp_gender == "MALE")

                    if sp_type == "spouse":
                        if s_is_male:
                            label = f"Жена брата (Невестка / Сноха) [супруга: {s_name}]" if not sp_is_male else f"Муж брата [супруг: {s_name}]"
                        else:
                            label = f"Муж сестры (Зять) [супруг: {s_name}]" if sp_is_male else f"Жена сестры [супруга: {s_name}]"
                    elif sp_type == "fiance":
                        label = f"Невеста брата" if s_is_male and not sp_is_male else (f"Жених сестры" if not s_is_male and sp_is_male else f"Помолвлен(а) с {'братом' if s_is_male else 'сестрой'}")
                    else:
                        label = f"Девушка брата" if s_is_male and not sp_is_male else (f"Парень сестры" if not s_is_male and sp_is_male else f"Партнёр {'брата' if s_is_male else 'сестры'}")
                    add_family_member(9, label, sp_inf)

                s_children = _get_sim_children_infos(s_inf, sim_info_mgr)
                for sc_inf in s_children:
                    sc_id = getattr(sc_inf, "sim_id", None)
                    if not sc_id or sc_id == sim_info.sim_id:
                        continue
                    sc_gender = getattr(getattr(sc_inf, "gender", None), "name", "MALE")
                    sc_is_male = (sc_gender == "MALE")
                    sub = f"сын {'брата' if s_is_male else 'сестры'} ({s_name})" if sc_is_male else f"дочь {'брата' if s_is_male else 'сестры'} ({s_name})"
                    title = "Племянник" if sc_is_male else "Племянница"
                    add_family_member(9, f"{title} ({sub})", sc_inf)

        # 10. Spouse's Parents & Siblings (Тесть, Тёща, Свёкор, Свекровь, Шурин, Деверь, Золовка, Свояченица)
        if get_genealogy_type_flag("spouse_in_laws"):
            my_gender = getattr(getattr(sim_info, "gender", None), "name", "FEMALE")
            sim_is_male = (my_gender == "MALE")
            for my_sp_inf, sp_rel_type in direct_partners:
                if sp_rel_type == "spouse":
                    sp_parents = _get_sim_parent_infos(my_sp_inf, sim_info_mgr)
                    for spp_inf in sp_parents:
                        spp_id = getattr(spp_inf, "sim_id", None)
                        if not spp_id or spp_id == sim_info.sim_id:
                            continue
                        spp_gender = getattr(getattr(spp_inf, "gender", None), "name", "MALE")
                        spp_is_male = (spp_gender == "MALE")
                        if sim_is_male:
                            label = "Тесть (Отец жены)" if spp_is_male else "Тёща (Мать жены)"
                        else:
                            label = "Свёкор (Отец мужа)" if spp_is_male else "Свекровь (Мать мужа)"
                        add_family_member(10, label, spp_inf)

                    sp_siblings = _get_sim_sibling_infos(my_sp_inf, sim_info_mgr)
                    for sps_inf in sp_siblings:
                        sps_id = getattr(sps_inf, "sim_id", None)
                        if not sps_id or sps_id == sim_info.sim_id:
                            continue
                        sps_gender = getattr(getattr(sps_inf, "gender", None), "name", "MALE")
                        sps_is_male = (sps_gender == "MALE")
                        if sim_is_male:
                            label = "Шурин (Брат жены)" if sps_is_male else "Свояченица (Сестра жены)"
                        else:
                            label = "Деверь (Брат мужа)" if sps_is_male else "Золовка (Сестра мужа)"
                        add_family_member(10, label, sps_inf)

        # 11. Aunts, Uncles, Cousins (Дяди, Тети, Кузены)
        if get_genealogy_type_flag("extended"):
            for p_inf in direct_parents:
                p_name = getattr(p_inf, "first_name", "Родитель")
                p_gender = getattr(getattr(p_inf, "gender", None), "name", "MALE")
                p_is_male = (p_gender == "MALE")
                p_title = "отца" if p_is_male else "матери"

                p_siblings = _get_sim_sibling_infos(p_inf, sim_info_mgr)
                for ps_inf in p_siblings:
                    ps_id = getattr(ps_inf, "sim_id", None)
                    if not ps_id or ps_id == sim_info.sim_id:
                        continue
                    ps_gender = getattr(getattr(ps_inf, "gender", None), "name", "MALE")
                    ps_is_male = (ps_gender == "MALE")
                    title = "Дядя" if ps_is_male else "Тетя"
                    sub = f"{'брат' if ps_is_male else 'сестра'} {p_title} ({p_name})"
                    add_family_member(11, f"{title} ({sub})", ps_inf)

                    cousins = _get_sim_children_infos(ps_inf, sim_info_mgr)
                    for cou_inf in cousins:
                        cou_id = getattr(cou_inf, "sim_id", None)
                        if not cou_id or cou_id == sim_info.sim_id:
                            continue
                        cou_gender = getattr(getattr(cou_inf, "gender", None), "name", "MALE")
                        cou_is_male = (cou_gender == "MALE")
                        c_title = "Двоюродный брат (Кузен)" if cou_is_male else "Двоюродная сестра (Кузина)"
                        add_family_member(11, f"{c_title}", cou_inf)

        # 12. Grandchildren's Spouses
        if get_genealogy_type_flag("child_spouses") or get_genealogy_type_flag("extended"):
            for c_inf in direct_children:
                gc_list = _get_sim_children_infos(c_inf, sim_info_mgr)
                for gc_inf in gc_list:
                    gc_partners = _get_sim_spouses_and_partners_infos(gc_inf, sim_info_mgr)
                    for gcp_inf, gcp_type in gc_partners:
                        gcp_id = getattr(gcp_inf, "sim_id", None)
                        if not gcp_id or gcp_id == sim_info.sim_id:
                            continue
                        gcp_gender = getattr(getattr(gcp_inf, "gender", None), "name", "FEMALE")
                        gcp_is_male = (gcp_gender == "MALE")
                        title = "Муж внучки" if gcp_is_male else "Жена внука"
                        add_family_member(12, title, gcp_inf)

        # 13. Relationship Tracker scan for any additional family/kinship bits & romantic affairs
        if rel_tracker is not None:
            try:
                all_sim_infos = []
                if hasattr(sim_info_mgr, "values"):
                    all_sim_infos = list(sim_info_mgr.values())
                elif hasattr(sim_info_mgr, "get_all"):
                    all_sim_infos = list(sim_info_mgr.get_all())
                elif hasattr(sim_info_mgr, "objects"):
                    all_sim_infos = list(sim_info_mgr.objects.values())

                for r_info in all_sim_infos:
                    if r_info is None or r_info.sim_id == sim_info.sim_id or r_info.sim_id in found_sim_ids:
                        continue
                    bits = rel_tracker.get_all_bits(r_info.sim_id)
                    if not bits:
                        continue
                    g_name = getattr(getattr(r_info, "gender", None), "name", "MALE")

                    rel_type = None
                    for b in bits:
                        f_rel = get_family_relation_from_bit(b)
                        if f_rel is not None:
                            rel_type = f_rel
                            break

                    if rel_type == "child" and get_genealogy_type_flag("children"):
                        add_family_member(2, "Ребенок", r_info)
                    elif rel_type == "parent" and get_genealogy_type_flag("parents"):
                        add_family_member(3, "Родитель", r_info)
                    elif rel_type == "sibling" and get_genealogy_type_flag("siblings"):
                        add_family_member(4, "Сиблинг", r_info)
                    elif rel_type == "spouse" and get_genealogy_type_flag("spouses"):
                        add_family_member(1, "Спутник", r_info)
                    elif rel_type == "fiance" and get_genealogy_type_flag("spouses"):
                        label = "Жених" if g_name == "MALE" else "Невеста"
                        add_family_member(1, label, r_info)
                    elif rel_type == "grandparent" and get_genealogy_type_flag("grandparents"):
                        add_family_member(5, "Дедушка/Бабушка", r_info)
                    elif rel_type == "grandchild" and get_genealogy_type_flag("grandchildren"):
                        add_family_member(6, "Внук/Внучка", r_info)
                    elif rel_type == "cousin" and get_genealogy_type_flag("extended"):
                        label = "Двоюродный брат (Кузен)" if g_name == "MALE" else "Двоюродная сестра (Кузина)"
                        add_family_member(11, label, r_info)
                    elif rel_type == "aunt_uncle" and get_genealogy_type_flag("extended"):
                        label = "Дядя" if g_name == "MALE" else "Тетя"
                        add_family_member(11, label, r_info)
                    elif rel_type == "stepchild" and get_genealogy_type_flag("children"):
                        step_lbl = "Пасынок" if g_name == "MALE" else "Падчерица"
                        add_family_member(2, step_lbl, r_info)
                    elif rel_type == "stepparent" and get_genealogy_type_flag("parents"):
                        step_lbl = "Отчим" if g_name == "MALE" else "Мачеха"
                        add_family_member(3, step_lbl, r_info)
                    elif rel_type == "stepsibling" and get_genealogy_type_flag("siblings"):
                        step_lbl = "Сводный брат" if g_name == "MALE" else "Сводная сестра"
                        add_family_member(4, step_lbl, r_info)
                    elif rel_type == "son_in_law" and get_genealogy_type_flag("child_spouses"):
                        add_family_member(7, "Зять", r_info)
                    elif rel_type == "daughter_in_law" and get_genealogy_type_flag("child_spouses"):
                        add_family_member(7, "Невестка (Сноха)", r_info)
                    elif rel_type == "father_in_law" and get_genealogy_type_flag("spouse_in_laws"):
                        add_family_member(10, "Свёкор / Тесть", r_info)
                    elif rel_type == "mother_in_law" and get_genealogy_type_flag("spouse_in_laws"):
                        add_family_member(10, "Свекровь / Тёща", r_info)
                    elif rel_type == "brother_in_law" and get_genealogy_type_flag("spouse_in_laws"):
                        add_family_member(10, "Деверь / Шурин / Зять", r_info)
                    elif rel_type == "sister_in_law" and get_genealogy_type_flag("spouse_in_laws"):
                        add_family_member(10, "Золовка / Свояченица / Невестка", r_info)
                    elif rel_type == "in_law" and get_genealogy_type_flag("spouse_in_laws"):
                        label = "Родственница по браку" if g_name == "FEMALE" else "Родственник по браку"
                        add_family_member(13, label, r_info)
                    else:
                        bits_names = [getattr(b, "__name__", str(b)).lower() for b in bits]
                        bits_str = " ".join(bits_names)
                        is_female = (g_name == "FEMALE")

                        is_romantic_partner = any(k in bits_str for k in [
                            "significant_other", "boyfriend_girlfriend", "sweethearts",
                            "lovebirds", "lovers", "affair", "cheating", "promised", "engaged", "fiance"
                        ])

                        r_score = 0
                        try:
                            rel = None
                            if hasattr(rel_tracker, "get_relationship"):
                                rel = rel_tracker.get_relationship(r_info.sim_id)
                            elif hasattr(rel_tracker, "_find_relationship"):
                                rel = rel_tracker._find_relationship(r_info.sim_id)
                            if rel is not None:
                                tracks = getattr(rel, "relationship_tracks", {}) or {}
                                if isinstance(tracks, dict):
                                    for track_key, track_inst in tracks.items():
                                        t_name = str(getattr(track_inst, "stat_type", track_key)).lower()
                                        if "romance" in t_name or "romantic" in t_name:
                                            get_val = getattr(track_inst, "get_value", None)
                                            if callable(get_val):
                                                r_score = max(r_score, get_val())
                                            elif hasattr(track_inst, "value"):
                                                r_score = max(r_score, track_inst.value)
                        except Exception:
                            pass

                        if not is_romantic_partner and (r_score >= 35 or (r_score >= 20 and any(k in bits_str for k in ["first_kiss", "firstkiss", "romanticinterest", "romantic_interest", "woohoo_partner"]))):
                            is_romantic_partner = True

                        if is_romantic_partner and get_genealogy_type_flag("spouses"):
                            my_spouse_id = getattr(sim_info, "spouse_sim_id", None)
                            is_cheating_me = (my_spouse_id is not None and my_spouse_id != r_info.sim_id)
                            target_spouse_id = getattr(r_info, "spouse_sim_id", None)
                            is_cheating_target = (target_spouse_id is not None and target_spouse_id != sim_info.sim_id)

                            if any(k in bits_str for k in ["engaged", "fiance"]):
                                label = "Невеста" if is_female else "Жених"
                            elif is_cheating_me and is_cheating_target:
                                label = "Любовница [двойная измена / оба в браке]" if is_female else "Любовник [двойная измена / оба в браке]"
                            elif is_cheating_me:
                                label = "Любовница [роман на стороне при живой жене]" if is_female else "Любовник [роман на стороне при живом муже]"
                            elif is_cheating_target:
                                label = "Любовница [замужняя женщина / измена её мужу]" if is_female else "Любовник [женатый мужчина / измена его жене]"
                            elif any(k in bits_str for k in ["lovers", "affair", "cheating"]):
                                label = "Любовница" if is_female else "Любовник"
                            else:
                                label = "Девушка" if is_female else "Парень"
                            add_family_member(1, label, r_info)
            except Exception:
                pass

        # 14. Household members scan for step-relations
        if get_genealogy_type_flag("children") and hasattr(sim_info, "household") and sim_info.household is not None:
            try:
                hh = sim_info.household
                hh_sims = []
                if hasattr(hh, "sim_info_gen"):
                    hh_sims = list(hh.sim_info_gen())
                elif hasattr(hh, "sim_infos"):
                    hh_sims = list(hh.sim_infos)
                elif hasattr(hh, "_sim_infos"):
                    hh_sims = list(hh._sim_infos)

                spouse_sim_id = getattr(sim_info, "spouse_sim_id", None)
                for hh_sim in hh_sims:
                    if hh_sim is None or hh_sim.sim_id == sim_info.sim_id or hh_sim.sim_id in found_sim_ids:
                        continue
                    hh_p_ids = [getattr(p, "sim_id", p) for p in _get_sim_parent_infos(hh_sim, sim_info_mgr)]
                    if sim_info.sim_id in hh_p_ids:
                        add_family_member(2, "Ребенок", hh_sim)
                    elif spouse_sim_id and spouse_sim_id in hh_p_ids:
                        g_name = getattr(getattr(hh_sim, "gender", None), "name", "MALE")
                        step_lbl = "Пасынок" if g_name == "MALE" else "Падчерица"
                        add_family_member(2, step_lbl, hh_sim)
            except Exception:
                pass

        # Sort candidates by priority (Spouse, Children, Parents, Siblings, Grandchildren, Grandparents, In-laws, etc.)
        candidates.sort(key=lambda x: x[0])

        for prio, rel_label, r_info in candidates:
            # Living / Death status
            is_ghost = getattr(r_info, "is_ghost", False)
            d_type = getattr(r_info, "death_type", None)
            is_dead = getattr(r_info, "is_dead", False) or is_ghost or (d_type is not None and d_type != 0)

            if is_dead and not get_genealogy_type_flag("deceased"):
                continue

            if len(family_list) >= max_relatives:
                break
            # Recalculate compound/incest title if present for close relatives
            if prio <= 6:
                accurate_title = get_relationship_between_sims(sim_info, r_info)
                if accurate_title:
                    is_plain_friend = any(f == accurate_title for f in (
                        "Незнакомец / Не знаком", "Знакомый", "Знакомая",
                        "Друг", "Подруга", "Хороший друг", "Хорошая подруга",
                        "Лучший друг", "Лучшая подруга", "Коллега по работе",
                        "Сосед по дому", "Соседка по дому"
                    ))
                    if not is_plain_friend:
                        rel_label = accurate_title
            else:
                # Check for incest/special direct ties even for in-laws
                accurate_title = get_relationship_between_sims(sim_info, r_info)
                if accurate_title and "[инцест" in accurate_title.lower():
                    rel_label = f"{rel_label} {accurate_title}"

            r_first = getattr(r_info, "first_name", "Сим")
            r_last = getattr(r_info, "last_name", "")
            r_full = f"{r_first} {r_last}".strip()

            r_age_raw = getattr(getattr(r_info, "age", None), "name", "ADULT")
            r_age = AGE_TRANSLATIONS.get(r_age_raw, "")

            # Living / Death status
            is_ghost = getattr(r_info, "is_ghost", False)
            d_type = getattr(r_info, "death_type", None)
            is_dead = getattr(r_info, "is_dead", False) or is_ghost or (d_type is not None and d_type != 0)

            qual_str = ""
            if is_dead:
                death_cause = ""
                if d_type:
                    dt_name = getattr(d_type, "name", str(d_type)).upper()
                    death_cause = DEATH_CAUSE_TRANSLATIONS.get(dt_name, "")
                if is_ghost:
                    status_str = "Покойный (Призрак)"
                else:
                    status_str = "Покойный / Умер"
                if death_cause:
                    status_str += f" (причина: {death_cause})"

                # Memory / relationship quality with the deceased
                if rel_tracker is not None:
                    try:
                        f_score = rel_tracker.get_relationship_score(r_info.sim_id)
                        if f_score >= 70:
                            qual_str = "Были очень близки при жизни / светлая память"
                        elif f_score >= 30:
                            qual_str = "Были в хороших отношениях при жизни"
                        elif f_score <= -30:
                            qual_str = "При жизни были в ссоре / неприязнь"
                    except Exception:
                        pass
            else:
                r_hh_id = getattr(r_info, "household_id", None)
                if household_id is not None and r_hh_id is not None and r_hh_id == household_id:
                    status_str = "Живут вместе в одном доме"
                else:
                    status_str = "Живет отдельно"

                # Relationship quality for living relatives
                if rel_tracker is not None:
                    has_met = False
                    try:
                        if hasattr(rel_tracker, "has_relationship"):
                            has_met = rel_tracker.has_relationship(r_info.sim_id)
                        elif hasattr(rel_tracker, "get_all_bits"):
                            has_met = bool(rel_tracker.get_all_bits(r_info.sim_id))
                        elif hasattr(rel_tracker, "_find_relationship"):
                            has_met = rel_tracker._find_relationship(r_info.sim_id) is not None
                    except Exception:
                        pass

                    f_score = 0
                    try:
                        f_score = rel_tracker.get_relationship_score(r_info.sim_id)
                    except Exception:
                        pass

                    if f_score >= 70:
                        qual_str = "Очень близкие и теплые отношения"
                    elif f_score >= 30:
                        qual_str = "Хорошие отношения"
                    elif f_score <= -50:
                        qual_str = "Враждебные отношения / Сильная неприязнь"
                    elif f_score <= -20:
                        qual_str = "Напряженные отношения"
                    elif has_met or f_score != 0:
                        qual_str = "Обычные / Нейтральные отношения"
                    else:
                        qual_str = "Лично ещё не знакомы"

            details = [status_str]
            if r_age and r_age not in ("Взрослый", "Молодой"):
                details.append(r_age)
            if qual_str:
                details.append(qual_str)

            det_text = f" ({', '.join(details)})" if details else ""
            family_list.append(f"{rel_label}: {r_full}{det_text}")

    except Exception as e:
        log_exception("Error getting sim family info", e)

    return family_list


OUTFIT_CATEGORY_TRANSLATIONS = {
    "EVERYDAY": "Повседневная одежда",
    "FORMAL": "Официальный наряд",
    "ATHLETIC": "Спортивная форма",
    "SLEEP": "Одежда для сна (пижама)",
    "PARTY": "Праздничный наряд",
    "SWIMWEAR": "Купальный костюм (купальник / плавки)",
    "HOTWEATHER": "Летняя одежда (для жаркой погоды)",
    "COLDWEATHER": "Тёплая одежда (для холодной погоды)",
    "BATHTIME": "Одежда для купания (без одежды / полотенце)",
    "BATHING": "Одежда для купания (без одежды / полотенце)",
    "CAREER": "Рабочая униформа",
    "SITUATION": "Ситуативный наряд",
    "SPECIAL": "Особый наряд / костюм",
    "BATUU": "Наряд с Батуу",
    "BAKU": "Магический наряд",
    "SMALL_BUSINESS": "Рабочая форма (бизнес)",
}


def get_sim_clothing_and_nudity_info(sim_info) -> tuple:
    """
    Determines the Sim's outfit category and precise nudity state.
    Supports both WickedWhims mod (if installed) and Vanilla Sims 4 fallback.
    Returns: (clothing_category_str, nudity_state_str)
    """
    category_raw = "EVERYDAY"
    try:
        if hasattr(sim_info, "get_current_outfit"):
            outfit_data = sim_info.get_current_outfit()
            if outfit_data is not None:
                cat_obj = outfit_data[0] if isinstance(outfit_data, (tuple, list)) else outfit_data

                # 1. Check if enum object has .name (e.g. standard enum / DynamicEnum)
                if hasattr(cat_obj, "name"):
                    category_raw = str(cat_obj.name).upper()
                else:
                    # 2. Try official The Sims 4 OutfitCategory enum value_to_name mapping
                    try:
                        from sims.outfits.outfit_enums import OutfitCategory
                        if hasattr(OutfitCategory, "value_to_name") and int(cat_obj) in OutfitCategory.value_to_name:
                            category_raw = str(OutfitCategory.value_to_name[int(cat_obj)]).upper()
                    except Exception:
                        pass

                # 3. Fallback to exact official TS4 integer mapping
                if category_raw == "EVERYDAY" or not category_raw:
                    try:
                        cat_int = int(cat_obj)
                        # Official EA The Sims 4 OutfitCategory enum integers:
                        # 0: EVERYDAY, 1: FORMAL, 2: ATHLETIC, 3: SLEEP, 4: PARTY,
                        # 5: BATHING, 6: CAREER, 7: SITUATION, 8: SPECIAL,
                        # 9: SWIMWEAR, 10: HOTWEATHER, 11: COLDWEATHER, 12: BATUU, 13: SMALL_BUSINESS
                        ea_int_map = {
                            0: "EVERYDAY",
                            1: "FORMAL",
                            2: "ATHLETIC",
                            3: "SLEEP",
                            4: "PARTY",
                            5: "BATHING",
                            6: "CAREER",
                            7: "SITUATION",
                            8: "SPECIAL",
                            9: "SWIMWEAR",
                            10: "HOTWEATHER",
                            11: "COLDWEATHER",
                            12: "BATUU",
                            13: "SMALL_BUSINESS",
                        }
                        category_raw = ea_int_map.get(cat_int, "EVERYDAY")
                    except Exception:
                        category_raw = "EVERYDAY"
    except Exception as e:
        log_exception("Error determining outfit category", e)

