def get_pet_species_info(sim_info):
    """Returns (species_type, species_name_ru), e.g. ('DOG', 'Собака') or ('CAT', 'Кошка')."""
    if sim_info is None:
        return ("DOG", "Собака")
    sp_str = str(getattr(sim_info, "species", "")).upper()
    if "CAT" in sp_str:
        return ("CAT", "Кошка")
    if "DOG" in sp_str:
        return ("DOG", "Собака")
    if "HORSE" in sp_str:
        return ("HORSE", "Лошадь")
    
    if getattr(sim_info, "is_cat", False):
        return ("CAT", "Кошка")
    if getattr(sim_info, "is_dog", False):
        return ("DOG", "Собака")
        
    traits = []
    if hasattr(sim_info, "get_traits"):
        try:
            traits = [getattr(t, "__name__", str(t)).lower() for t in sim_info.get_traits()]
        except Exception:
            pass
    for t in traits:
        if "cat" in t:
            return ("CAT", "Кошка")
        if "dog" in t:
            return ("DOG", "Собака")
            
    return ("DOG", "Собака")


def get_pet_breed(sim_info) -> str:
    """Resolves pet breed from traits or metadata."""
    if sim_info is None:
        return "Беспородный(ая) / Метис"
    try:
        traits = []
        if hasattr(sim_info, "get_traits"):
            try:
                traits = [getattr(t, "__name__", str(t)).lower() for t in sim_info.get_traits()]
            except Exception:
                pass
        for t in traits:
            if "breed" in t:
                for bk, bv in PET_BREED_TRANSLATIONS.items():
                    if bk in t:
                        return bv
        for t in traits:
            for bk, bv in PET_BREED_TRANSLATIONS.items():
                if bk in t:
                    return bv
    except Exception as e:
        log_exception("Error determining pet breed", e)
    return "Беспородный(ая) / Метис"


def get_pet_age_gender(sim_info) -> str:
    """Returns age and gender for a pet, e.g. 'Щенок, Самец' or 'Взрослая кошка, Самка'."""
    sp_type, _ = get_pet_species_info(sim_info)
    gender_raw = getattr(getattr(sim_info, "gender", None), "name", "MALE")
    is_female = (gender_raw == "FEMALE")
    gender_str = "Самка" if is_female else "Самец"
    
    age_raw = getattr(getattr(sim_info, "age", None), "name", "ADULT").upper()
    is_baby = any(k in age_raw for k in ["BABY", "CHILD", "TODDLER", "INFANT"])
    is_elder = "ELDER" in age_raw
    
    if sp_type == "CAT":
        if is_baby:
            age_str = "Котёнок"
        elif is_elder:
            age_str = "Пожилая кошка" if is_female else "Пожилой кот"
        else:
            age_str = "Взрослая кошка" if is_female else "Взрослый кот"
    else:
        if is_baby:
            age_str = "Щенок"
        elif is_elder:
            age_str = "Пожилая собака" if is_female else "Пожилой пес"
        else:
            age_str = "Взрослая собака" if is_female else "Взрослый пес"
            
    return f"{age_str}, {gender_str}"


def get_pet_motives_summary(sim_info) -> str:
    """Accurately evaluates pet motives (Hunger, Bowel/Bladder, Affection, Play, Energy, Hygiene)."""
    if sim_info is None:
        return "Все потребности в норме (питомец сыт и доволен)"
    comm_tracker = getattr(sim_info, "commodity_tracker", None)
    if comm_tracker is None:
        return "Все потребности в норме (питомец сыт и доволен)"

    deficits = []
    satisfied_highlights = []
    seen_categories = set()

    def add_need(cat_key, desc, is_deficit=True):
        if cat_key not in seen_categories:
            seen_categories.add(cat_key)
            if is_deficit:
                deficits.append(desc)
            else:
                satisfied_highlights.append(desc)

    try:
        stats_list = []
        if hasattr(comm_tracker, "__iter__"):
            try:
                stats_list = list(comm_tracker)
            except Exception:
                pass
        if not stats_list and hasattr(comm_tracker, "get_all_commodities"):
            try:
                stats_list = list(comm_tracker.get_all_commodities())
            except Exception:
                pass
        if not stats_list:
            stats_list = getattr(comm_tracker, "_commodities", []) or getattr(comm_tracker, "commodities", [])

        # Priority sort: ensure actual 'motive_' commodities are processed before generic ones
        def _motive_priority(st):
            s_type = getattr(st, "stat_type", None) or type(st)
            t_name = getattr(s_type, "__name__", str(st)).lower()
            return 0 if ("motive" in t_name) else 1

        try:
            stats_list = sorted(stats_list, key=_motive_priority)
        except Exception:
            pass

        for stat in stats_list:
            s_type = getattr(stat, "stat_type", None) or type(stat)
            type_name = getattr(s_type, "__name__", "").lower()
            inst_str = str(stat).lower()
            combined_name = f"{type_name} {inst_str}"

            # Filter out cooldowns, static commodities, buff commodities, autonomy tracking, traits
            if any(skip in combined_name for skip in ["cooldown", "static", "buff", "autonomy", "trait", "decay", "test", "walker", "cleanliness", "role"]):
                continue

            # Obtain numeric stat value
            val = getattr(stat, "get_value", None)
            if callable(val):
                try:
                    val = float(val())
                except Exception:
                    val = None
            elif hasattr(stat, "value"):
                try:
                    val = float(getattr(stat, "value", 0))
                except Exception:
                    val = None
            else:
                val = None

            if val is None:
                continue

            # 1. Естественная нужда (Bowel / Bladder / Potty)
            if any(k in combined_name for k in ["bowel", "bladder", "pet_potty", "petpotty"]):
                if "bowel" not in seen_categories:
                    if val <= -65:
                        add_need("bowel", "Туалет: Срочно нужно в туалет (терпит изо всех сил, критическая нужда!)")
                    elif val <= -15:
                        add_need("bowel", "Туалет: Хочет в туалет (просится на улицу или к лотку)")
                    elif val >= 75:
                        add_need("bowel", "Туалет: Нужда полностью удовлетворена", is_deficit=False)

            # 2. Питание / Голод (Hunger)
            elif "hunger" in combined_name:
                if "hunger" not in seen_categories:
                    if val <= -65:
                        add_need("hunger", "Голод: Очень голоден (миска пуста, жалобно выпрашивает еду!)")
                    elif val <= -15:
                        add_need("hunger", "Голод: Проголодался (поглядывает на миску, хочет перекусить)")
                    elif val >= 70:
                        add_need("hunger", "Голод: Сыт и доволен", is_deficit=False)

            # 3. Бодрость / Энергия (Energy)
            elif "energy" in combined_name:
                if "energy" not in seen_categories:
                    if val <= -65:
                        add_need("energy", "Бодрость: Валится с лап от усталости (засыпает на ходу, нужен сон!)")
                    elif val <= -15:
                        add_need("energy", "Бодрость: Сонный / уставший (глаза слипаются, хочет вздремнуть)")
                    elif val >= 75:
                        add_need("energy", "Бодрость: Полон сил и энергии", is_deficit=False)

            # 4. Игры / Досуг (Play / Fun)
            elif "play" in combined_name:
                if "play" not in seen_categories:
                    if val <= -65:
                        add_need("play", "Игры: Сходит с ума от скуки (острая нехватка активности и игр)")
                    elif val <= -15:
                        add_need("play", "Игры: Хочет побеситься с игрушкой или побегать")
                    elif val >= 70:
                        add_need("play", "Игры: Нарезвился вдоволь", is_deficit=False)

            # 5. Любовь / Внимание (Affection / Social)
            elif any(k in combined_name for k in ["affection", "pet_social", "petsocial"]):
                if "affection" not in seen_categories:
                    if val <= -65:
                        add_need("affection", "Внимание: Отчаянно жаждет ласки (очень тоскует по хозяину)")
                    elif val <= -15:
                        add_need("affection", "Внимание: Скучает по хозяину, просит почесать за ушком")
                    elif val >= 70:
                        add_need("affection", "Внимание: Окружен заботой и любовью", is_deficit=False)

            # 6. Гигиена (Hygiene)
            elif "hygiene" in combined_name:
                if "hygiene" not in seen_categories:
                    if val <= -65:
                        add_need("hygiene", "Гигиена: Ужасно грязный (шерсть свалялась, весь в грязи)")
                    elif val <= -15:
                        add_need("hygiene", "Гигиена: Испачкался (не помешает помыться или расчесаться)")
                    elif val >= 70:
                        add_need("hygiene", "Гигиена: Чистая ухоженная шерстка", is_deficit=False)

    except Exception as e:
        log_exception("Error evaluating pet motives", e)

    if deficits:
        return "; ".join(deficits)

    if satisfied_highlights:
        return "Все потребности в норме (" + ", ".join(satisfied_highlights[:2]) + ")"

    return "Все потребности в норме (питомец сыт, бодр и доволен жизнью)"


def get_pet_traits_summary(sim_info) -> str:
    """Returns friendly Russian summary of pet traits."""
    if sim_info is None:
        return "Обычный питомец"
    traits_list = []
    try:
        if hasattr(sim_info, "get_traits"):
            for t in sim_info.get_traits():
                t_name = getattr(t, "__name__", str(t)).lower()
                for tk, tv in PET_TRAIT_TRANSLATIONS.items():
                    if tk in t_name and tv not in traits_list:
                        traits_list.append(tv)
                        break
    except Exception as e:
        log_exception("Error getting pet traits", e)
    return ", ".join(traits_list) if traits_list else "Обычный добрый питомец"


def get_pet_mood_info(sim_info) -> str:
    """Returns emotional mood of pet."""
    if sim_info is None:
        return "Спокойное / Довольное"
    try:
        if hasattr(sim_info, "get_mood"):
            mood = sim_info.get_mood()
            if mood is not None:
                m_name = getattr(mood, "__name__", str(mood)).lower()
                if "happy" in m_name:
                    return "Счастливое / Радостное (виляет хвостом / мурлычет)"
                if "playful" in m_name:
                    return "Игривое (хочет резвиться и скакать)"
                if "scared" in m_name:
                    return "Испуганное / Напуган (прячется, прижал уши)"
                if "angry" in m_name:
                    return "Сердитое (рычит / шипит)"
                if "sad" in m_name:
                    return "Грустное / Скучает в одиночестве"
                if "uncomfortable" in m_name:
                    return "Дискомфорт / Нездоровится"
                if "asleep" in m_name or "drowsy" in m_name:
                    return "Сонное / Дремлет"
                if "flirty" in m_name:
                    return "Призывное / Возбужденное"
    except Exception as e:
        log_exception("Error getting pet mood", e)
    return "Спокойное / Довольное"


def get_pet_current_activity(sim_info) -> str:
    """Determines what the pet is actively doing right now in The Sims 4."""
    species_type, _ = get_pet_species_info(sim_info)
    is_cat = (species_type == "CAT")

    if sim_info is None:
        return "Сидит и наблюдает за обстановкой" if is_cat else "Стоит и преданно виляет хвостом"

    try:
        sim_instance = sim_info.get_sim_instance()
        if sim_instance is None:
            return "Отдыхает"

        interactions = get_all_sim_interactions(sim_instance)

        # 1. First pass: Match known pet behavior keywords on meaningful interactions
        for inter in interactions:
            aff = getattr(inter, "affordance", inter)
            guid = getattr(aff, "guid64", 0) or getattr(inter, "guid64", 0)

            # Skip our AI mind reader interaction!
            if guid == 18298976728462081835:
                continue

            aff_name = getattr(aff, "__name__", str(aff)).lower()
            if any(k in aff_name for k in ["readthoughts", "mind_reader", "ai_read", "read_thoughts"]):
                continue

            # Sleep / Nap
            if any(k in aff_name for k in ["sleep", "nap", "rest", "snooze"]):
                return "Спит, свернувшись калачиком"
            # Food / Drink
            if any(k in aff_name for k in ["eat_food", "petfood", "bowl_eat", "eat"]):
                return "Хрустит вкусным кормом из миски"
            if any(k in aff_name for k in ["drink_water", "water_bowl", "bowl_drink", "drink"]):
                return "Лакает свежую воду из миски"
            if any(k in aff_name for k in ["toilet", "drink_toilet"]):
                return "Лакает воду прямо из унитаза (пока никто не видит)"
            if any(k in aff_name for k in ["beg_for_food", "beg_food", "beg"]):
                return "Преданно заглядывает в глаза и жалобно выпрашивает еду со стола"
            if any(k in aff_name for k in ["trash", "scavenge", "rummage"]):
                return "Роется в мусорном ведре в поисках вкусняшек"

            # Social / Affection with humans
            if any(k in aff_name for k in ["greet", "welcome"]):
                return "Радостно встречает любимого хозяина у двери"
            if any(k in aff_name for k in ["rub", "nuzzle", "affection", "be_petted", "pet_to_sim"]):
                return "Ластится, трется мордочкой о ноги человека и требует ласки"
            if any(k in aff_name for k in ["belly", "belly_rub"]):
                return "Подставил теплое пузико и блаженствует от почесываний"
            if any(k in aff_name for k in ["lap", "sit_lap"]):
                return "Уютно устроился на коленях у человека"
            if any(k in aff_name for k in ["ask_walk", "beg_walk"]):
                return "Скулит у входной двери и нетерпеливо просится на прогулку"
            if any(k in aff_name for k in ["walk", "leash"]):
                return "Гуляет на поводке рядом с хозяином"
            if any(k in aff_name for k in ["sniff", "investigate"]):
                return "С любопытством обнюхивает все вокруг"
            if any(k in aff_name for k in ["bark_at", "bark"]):
                return "Громко и звонко лает, заявляя о своем присутствии"
            if any(k in aff_name for k in ["howl"]):
                return "Протяжно воет, выражая глубокие собачьи чувства"
            if any(k in aff_name for k in ["meow", "yowl", "vocalize"]):
                return "Громко мяукает, требуя внимания к своей персоне"
            if any(k in aff_name for k in ["purr"]):
                return "Громко и довольно мурлычет"
            if any(k in aff_name for k in ["hiss"]):
                return "Угрожающе шипит и выгибает спину дугой"
            if any(k in aff_name for k in ["growl"]):
                return "Грозно рычит, защищая свою территорию"

            # Play & Zoomies
            if any(k in aff_name for k in ["run_around", "zoomies", "hyper", "crazy", "frisky"]):
                return "Внезапный приступ безудержного тыгыдыка — с восторгом носится по комнатам!"
            if any(k in aff_name for k in ["laser", "laser_pointer"]):
                return "Азартно охотится за неуловимой красной точкой от лазерной указки"
            if any(k in aff_name for k in ["ball", "toy_ball", "fetch"]):
                return "Гоняет мячик по всей комнате и радостно ловит его лапами"
            if any(k in aff_name for k in ["chew", "bone", "chewtoy"]):
                return "С упоением грызет любимую игрушку на ковре"
            if any(k in aff_name for k in ["scratch_post", "post"]):
                return "Энергично точит когти о когтеточку"
            if any(k in aff_name for k in ["scratch_furniture", "scratch_sofa", "scratch_couch"]):
                return "Втихаря и с упоением дерет когтями любимый диван хозяина"
            if any(k in aff_name for k in ["jump_counter", "jump_table", "counter", "table"]):
                return "Запрыгнул на стол и инспектирует, что там оставили люди"
            if any(k in aff_name for k in ["box", "cardboard"]):
                return "Залез в картонную коробку (идеальный размер для величия)"
            if any(k in aff_name for k in ["window", "watch_birds"]):
                return "Сидит на подоконнике и гипнотизирует птиц за окном"
            if any(k in aff_name for k in ["roll", "roll_back"]):
                return "Кувыркается и катается на спине по полу от удовольствия"

            # Hygiene & Potty
            if any(k in aff_name for k in ["litter", "litterbox"]):
                return "Деловито шуршит и закапывает дела в лотке"
            if any(k in aff_name for k in ["pee_outside", "poop_outside", "pee", "poop", "potty"]):
                return "Справляет нужду"
            if any(k in aff_name for k in ["groom", "lick_paws", "wash", "lick"]):
                return "Тщательно умывается лапкой и чистит шерстку"
            if any(k in aff_name for k in ["flea", "scratch_flea"]):
                return "Остервенело чешет задней лапой за ухом"
            if any(k in aff_name for k in ["vomit", "hairball", "sick"]):
                return "Чувствует себя скверно / тошнит шерстью"
            if any(k in aff_name for k in ["fear_vacuum", "vacuum"]):
                return "В панике прячется под диваном от ревущего монстра-пылесоса!"
            if any(k in aff_name for k in ["thunder", "storm"]):
                return "Дрожит от страха под кроватью из-за грозы за окном"

        # 2. Second pass: Check affordance display_name and string hashes against SelectablePets translation database
        if PET_ACTION_HASH_TRANSLATIONS:
            for inter in interactions:
                aff = getattr(inter, "affordance", inter)
                guid = getattr(aff, "guid64", 0) or getattr(inter, "guid64", 0)
                if guid == 18298976728462081835:
                    continue
                aff_name = getattr(aff, "__name__", str(aff)).lower()
                if any(k in aff_name for k in ["readthoughts", "mind_reader", "ai_read", "read_thoughts"]):
                    continue

                d_name = getattr(aff, "display_name", None)
                if d_name is not None:
                    try:
                        d_int = int(d_name)
                        if d_int in PET_ACTION_HASH_TRANSLATIONS:
                            return PET_ACTION_HASH_TRANSLATIONS[d_int]
                    except Exception:
                        pass
                    h_val = getattr(d_name, "hash", None) or getattr(d_name, "_string_id", None)
                    if h_val is not None and h_val in PET_ACTION_HASH_TRANSLATIONS:
                        return PET_ACTION_HASH_TRANSLATIONS[h_val]

                try:
                    name_loc = inter.get_name(target=getattr(inter, "target", None), context=getattr(inter, "context", None))
                    if name_loc is not None:
                        h_val = getattr(name_loc, "hash", None) or getattr(name_loc, "_string_id", None)
                        if h_val is not None and h_val in PET_ACTION_HASH_TRANSLATIONS:
                            return PET_ACTION_HASH_TRANSLATIONS[h_val]
                except Exception:
                    pass

        # 3. Third pass: Try clean human-readable localized UI name from game tuning
        for inter in interactions:
            aff = getattr(inter, "affordance", inter)
            guid = getattr(aff, "guid64", 0) or getattr(inter, "guid64", 0)
            if guid == 18298976728462081835:
                continue
            aff_name = getattr(aff, "__name__", str(aff)).lower()
            if any(k in aff_name for k in ["readthoughts", "mind_reader", "ai_read", "read_thoughts"]):
                continue

            ui_name = get_interaction_ui_name(inter)
            if ui_name and is_human_readable_text(ui_name):
                # Extra safety check against protobuf tokens
                if not any(bad in ui_name.lower() for bad in ["hash:", "tokens", "first_name", "{", "}", "type:"]):
                    return ui_name

        # 3. Third pass: Check pet posture (sleep, sit, lay down, stand)
        if hasattr(sim_instance, "posture") and sim_instance.posture is not None:
            p_str = str(getattr(sim_instance.posture, "name", str(type(sim_instance.posture).__name__))).lower()
            if "sleep" in p_str:
                return "Спит, свернувшись калачиком"
            if "lay" in p_str or "lie" in p_str:
                return "Лежит на полу, расслабленно наблюдая за обстановкой"
            if "sit" in p_str:
                return "Сидит и внимательно слушает происходящее вокруг"

    except Exception as e:
        log_exception("Error determining pet current activity", e)

    return "Лениво осматривается по сторонам, прислушиваясь к звукам в доме" if is_cat else "Стоит на месте, навострив уши и виляя хвостом"


def get_household_roommates_info(sim_info) -> list:
    """
    Returns list of roommates / housemates who live in the same household with sim_info,
    strictly excluding: the Sim themselves, pets, family/blood relatives, and romantic partners.
    E.g. 'Марк Торрес (Молодой, Мужской, Отношения: Лучший друг, Очень близкие отношения)'
    """
    roommates = []
    if sim_info is None:
        return roommates

    try:
        if services is None:
            return roommates

        my_id = getattr(sim_info, "sim_id", None)
        if not my_id:
            return roommates

        rel_tracker = getattr(sim_info, "relationship_tracker", None)
        genealogy = getattr(sim_info, "genealogy", None)
        my_spouse_id = getattr(sim_info, "spouse_sim_id", None)

        # Collect all cohabitants
        cohabitants = []
        seen_ids = set()

        household = getattr(sim_info, "household", None)
        if household is not None:
            sim_infos = getattr(household, "sim_infos", None)
            if sim_infos is None and hasattr(household, "get_sim_infos"):
                sim_infos = household.get_sim_infos()
            if sim_infos:
                for m in sim_infos:
                    if m is not None:
                        m_id = getattr(m, "sim_id", None)
                        if m_id and m_id != my_id and m_id not in seen_ids:
                            seen_ids.add(m_id)
                            cohabitants.append(m)

        # Check Discover University / NPC roommate service if active
        try:
            if hasattr(services, "get_roommate_service"):
                roommate_svc = services.get_roommate_service()
                if roommate_svc is not None:
                    zone_id = getattr(sim_info, "zone_id", None)
                    if not zone_id and hasattr(services, "current_zone_id"):
                        zone_id = services.current_zone_id()
                    if zone_id and hasattr(roommate_svc, "get_roommate_sim_infos"):
                        for r_m in roommate_svc.get_roommate_sim_infos(zone_id):
                            if r_m is not None:
                                r_m_id = getattr(r_m, "sim_id", None)
                                if r_m_id and r_m_id != my_id and r_m_id not in seen_ids:
                                    seen_ids.add(r_m_id)
                                    cohabitants.append(r_m)
        except Exception:
            pass

        # Filter cohabitants: must NOT be pet, must NOT be family, must NOT be romantic partner
        for other_info in cohabitants:
            if getattr(other_info, "is_pet", False):
                continue

            other_id = getattr(other_info, "sim_id", None)
            if not other_id:
                continue

            # 1. Check spouse
            if my_spouse_id and my_spouse_id == other_id:
                continue
            if getattr(other_info, "spouse_sim_id", None) == my_id:
                continue

            # 2. Check genealogy
            is_family = False
            if genealogy is not None:
                if hasattr(genealogy, "get_parent_sim_ids") and other_id in (genealogy.get_parent_sim_ids() or ()):
                    is_family = True
                elif hasattr(genealogy, "get_children_sim_ids_gen"):
                    try:
                        if other_id in list(genealogy.get_children_sim_ids_gen()):
                            is_family = True
                    except Exception:
                        pass
                elif hasattr(genealogy, "get_siblings_sim_ids_gen"):
                    try:
                        if other_id in list(genealogy.get_siblings_sim_ids_gen()):
                            is_family = True
                    except Exception:
                        pass

            if is_family:
                continue

            # 3. Check relationship bits & romance tracks
            bits = []
            if rel_tracker is not None:
                try:
                    bits = rel_tracker.get_all_bits(other_id)
                except Exception:
                    bits = []

            bits_names = [getattr(b, "__name__", str(b)).lower() for b in bits]
            bits_str = " ".join(bits_names)

            # Check if family relation bit
            is_family_bit = False
            for b in bits:
                if get_family_relation_from_bit(b) is not None:
                    is_family_bit = True
                    break
            if is_family_bit:
                continue

            # Check if romantic partner / couple / lover
            is_romantic = any(k in bits_str for k in [
                "significant_other", "boyfriend_girlfriend", "sweethearts",
                "lovebirds", "lovers", "affair", "cheating", "promised", "engaged", "fiance", "spouse", "married"
            ])

            r_score = 0
            if rel_tracker is not None:
                try:
                    rel = rel_tracker.get_relationship(other_id) if hasattr(rel_tracker, "get_relationship") else rel_tracker._find_relationship(other_id)
                    if rel is not None:
                        tracks = getattr(rel, "relationship_tracks", {}) or {}
                        if isinstance(tracks, dict):
                            for track_key, track_inst in tracks.items():
                                t_name = str(getattr(track_inst, "stat_type", track_key)).lower()
                                if "romance" in t_name or "romantic" in t_name:
                                    get_val = getattr(track_inst, "get_value", None)
                                    if callable(get_val):
                                        r_score = max(r_score, get_val())
                                    elif hasattr(track_inst, "value"):
                                        r_score = max(r_score, track_inst.value)
                except Exception:
                    pass

            if is_romantic or r_score >= 35:
                continue

            # other_info IS A ROOMMATE (Сосед по дому)
            r_first = getattr(other_info, "first_name", "") or "Сим"
            r_last = getattr(other_info, "last_name", "") or ""
            r_full = f"{r_first} {r_last}".strip()

            g_raw = getattr(getattr(other_info, "gender", None), "name", "MALE")
            is_female = (g_raw == "FEMALE")
            gender_label = "Женский" if is_female else "Мужской"

            r_age_raw = getattr(getattr(other_info, "age", None), "name", "ADULT")
            r_age = AGE_TRANSLATIONS.get(r_age_raw, "Взрослый")

            # Social relation label
            rel_label = get_relationship_between_sims(sim_info, other_info)
            if not rel_label or rel_label == "Незнакомец / Не знаком":
                rel_label = "Соседка по дому" if is_female else "Сосед по дому"

            # Tone string
            tone_str = ""
            if rel_tracker is not None:
                try:
                    f_score = rel_tracker.get_relationship_score(other_id)
                    if f_score >= 70:
                        tone_str = "Очень близкие и теплые отношения"
                    elif f_score >= 30:
                        tone_str = "Теплые дружеские отношения"
                    elif f_score <= -50:
                        tone_str = "Вражда / Сильная неприязнь"
                    elif f_score <= -20:
                        tone_str = "Напряженные отношения"
                except Exception:
                    pass

            details = [f"{r_age}, {gender_label}", f"Отношения: {rel_label}"]
            if tone_str:
                details.append(tone_str)

            roommates.append(f"{r_full} ({', '.join(details)})")

    except Exception as e:
        log_exception("Error getting household roommates info", e)

    return roommates


def get_household_pets_info(sim_info) -> list:
    """Returns list of pet descriptions in the household: e.g. 'Кошка: Старк'."""
    pets = []
    if sim_info is None:
        return pets
    try:
        household = getattr(sim_info, "household", None)
        if household is not None:
            sim_infos = getattr(household, "sim_infos", None)
            if sim_infos is None and hasattr(household, "get_sim_infos"):
                sim_infos = household.get_sim_infos()
            if sim_infos:
                for member in sim_infos:
                    if member is not None and getattr(member, "is_pet", False):
                        p_name = getattr(member, "first_name", "") or "Питомец"
                        _, sp_name = get_pet_species_info(member)
                        pets.append(f"{sp_name}: {p_name}")
    except Exception as e:
        log_exception("Error getting household pets info", e)
    return pets


def get_pet_owners_info(sim_info) -> list:
    """Returns list of human owners in the household for a pet."""
    owners = []
    if sim_info is None:
        return owners
    try:
        household = getattr(sim_info, "household", None)
        if household is not None:
            sim_infos = getattr(household, "sim_infos", None)
            if sim_infos is None and hasattr(household, "get_sim_infos"):
                sim_infos = household.get_sim_infos()
            if sim_infos:
                for member in sim_infos:
                    if member is not None and not getattr(member, "is_pet", False):
                        h_name = f"{getattr(member, 'first_name', '')} {getattr(member, 'last_name', '')}".strip()
                        if h_name:
                            owners.append(f"{h_name} (Хозяин)")
    except Exception as e:
        log_exception("Error getting pet owners info", e)
    return owners


def get_pet_cohabitants_info(sim_info) -> list:
    """Returns list of other pets in the household."""
    other_pets = []
    if sim_info is None:
        return other_pets
    try:
        my_id = getattr(sim_info, "sim_id", None)
        household = getattr(sim_info, "household", None)
        if household is not None:
            sim_infos = getattr(household, "sim_infos", None)
            if sim_infos is None and hasattr(household, "get_sim_infos"):
                sim_infos = household.get_sim_infos()
            if sim_infos:
                for member in sim_infos:
                    if member is not None and getattr(member, "is_pet", False):
                        if getattr(member, "sim_id", None) != my_id:
                            p_name = getattr(member, "first_name", "") or "Питомец"
                            _, sp_name = get_pet_species_info(member)
                            other_pets.append(f"{sp_name} {p_name}")
    except Exception as e:
        log_exception("Error getting other pets info", e)
    return other_pets


def build_pet_prompt(sim_info) -> str:
    """Constructs a specialized contextual prompt for Dogs and Cats."""
    first_name = getattr(sim_info, "first_name", "Питомец") or "Питомец"
    species_type, species_name = get_pet_species_info(sim_info)
    age_gender = get_pet_age_gender(sim_info)

    activity = get_pet_current_activity(sim_info)
    mood = get_pet_mood_info(sim_info)
    motives = get_pet_motives_summary(sim_info)
    traits = get_pet_traits_summary(sim_info)
    location = get_current_location(sim_info)

    owners = get_pet_owners_info(sim_info)
    other_pets = get_pet_cohabitants_info(sim_info)
    nearby = get_nearby_sims_info(sim_info)

    world_time = get_world_time_info()
    season = get_season_info()
    weather = get_weather_info()

    pet_id = getattr(sim_info, "sim_id", None)
    p_lore = get_custom_sim_lore(pet_id) if pet_id else ""

    try:
        from ai_thought_reader.localization import get_game_language
        is_en = (get_game_language() == "en")
    except Exception:
        is_en = False

    if is_en:
        try:
            from ai_thought_reader.context_en import build_pet_prompt_en
            prompt = build_pet_prompt_en(
                first_name=first_name,
                species_name_ru=species_name,
                age_gender_ru=age_gender,
                activity_ru=activity,
                mood_ru=mood,
                motives_ru=motives,
                traits_ru=traits,
                location_ru=location,
                owners_ru=owners or [],
                other_pets_ru=other_pets or [],
                nearby_ru=nearby or [],
                world_time_ru=world_time,
                season_ru=season,
                weather_ru=weather,
                custom_lore=p_lore,
                flags_func=get_context_flag,
            )
            log(f"Generated Pet Context Prompt (EN) for {first_name} ({species_name}):\n{prompt}")
            return prompt
        except Exception as e_pet_en:
            log_exception("Error in build_pet_prompt_en", e_pet_en)

    lines = [
        f"Информация о домашнем животном ({species_name}):",
        f"- Кличка: {first_name}",
        f"- Вид: {species_name}",
        f"- Возраст и пол: {age_gender}",
    ]
    if get_context_flag("world_time"):
        lines.append(f"- Время в игре: {world_time}")
    if get_context_flag("weather"):
        lines.append(f"- Время года: {season}")
        lines.append(f"- Погода: {weather}")
    lines.append(f"- Текущее действие: {activity}")
    lines.append(f"- Текущее настроение: {mood}")
    lines.append(f"- Состояние потребностей: {motives}")
    lines.append(f"- Черты характера и повадки: {traits}")

    pet_id = getattr(sim_info, "sim_id", None)
    if pet_id:
        p_lore = get_custom_sim_lore(pet_id)
        if p_lore:
            lines.append(f"- Дополнительные сведения о питомце: {p_lore}")

    if get_context_flag("location"):
        lines.append(f"- Текущая локация: {location}")

    if get_context_flag("pets"):
        if owners:
            lines.append(f"- Хозяева (люди в семье): " + ", ".join(owners))
        else:
            lines.append("- Хозяева: Бродячий / без постоянного хозяина")
        if other_pets:
            lines.append(f"- Другие питомцы в доме: " + ", ".join(other_pets))

    if get_context_flag("nearby"):
        if nearby:
            lines.append("- Кто находится рядом:")
            for n in nearby:
                lines.append(f"  • {n}")
        else:
            lines.append("- Кто находится рядом: Поблизости никого нет")
        
    lines.append("")
    lines.append(
        f"Сформулируй короткую (1-2 предложения) спонтанную реплику мыслей питомца {first_name} ({species_name}) в эту конкретную секунду от первого лица («Я»). Отрази его текущее действие, звуки, повадки и искренние животные эмоции!"
    )
    prompt = "\n".join(lines)
    log(f"Generated Pet Context Prompt for {first_name} ({species_name}):\n{prompt}")
    return prompt


def is_sim_erratic_or_insane(sim_info, traits_str: str = "") -> bool:
    """Checks whether the Sim has the Erratic / Insane trait."""
    if traits_str and any(k in traits_str.lower() for k in ["чудаковатый", "безумный", "erratic", "insane"]):
        return True
    if sim_info is not None:
        try:
            raw_traits = []
            if hasattr(sim_info, "get_traits"):
                raw_traits = list(sim_info.get_traits())
            elif hasattr(sim_info, "trait_tracker") and sim_info.trait_tracker is not None:
                if hasattr(sim_info.trait_tracker, "equipped_traits"):
                    raw_traits = list(sim_info.trait_tracker.equipped_traits)
                else:
                    raw_traits = list(sim_info.trait_tracker)
            for t in raw_traits:
                t_name = getattr(t, "__name__", str(t)).lower()
                guid = getattr(t, "guid64", None) or getattr(t, "guid", None)
                if guid == 16847 or any(k in t_name for k in ["insane", "erratic"]):
                    return True
        except Exception:
            pass
    return False


def build_sim_prompt(sim_info) -> str:
    """Constructs a rich contextual prompt strictly following the user's structured order."""
    # If the target is a pet (Dog or Cat), route to build_pet_prompt
    if getattr(sim_info, "is_pet", False):
        return build_pet_prompt(sim_info)

    first_name = getattr(sim_info, "first_name", "Сим")
    last_name = getattr(sim_info, "last_name", "")
    full_name = f"{first_name} {last_name}".strip()

    age_raw = getattr(getattr(sim_info, "age", None), "name", "ADULT")
    age = AGE_TRANSLATIONS.get(age_raw, "Взрослый")

