    # Dynamic Intoxication / Substance Guidance (Basemental Drugs Moods & Highs)
    mood_lower = mood.lower()
    if any(k in mood_lower for k in ["под кайфом", "накурен", "stoned"]):
        lines.append(
            "ВАЖНО (Под кайфом / Марихуана): Персонаж находится под воздействием каннабиса (накурен). "
            "Мысли должны быть расслабленными, слегка затуманенными, с нотками ленивой философии, внезапного аппетита (хочется чего-нибудь перекусить) или забавной заторможенности."
        )
        lines.append("")
    elif any(k in mood_lower for k in ["пьян", "drunk", "навеселе", "в стельку", "в хлам"]):
        lines.append(
            "ВАЖНО (Алкогольное опьянение): Персонаж пьян. "
            "Мысли должны быть развязными, импульсивными, с притупленным самоконтролем, излишней эмоциональностью или пьяным весельем/куражом."
        )
        lines.append("")
    elif any(k in mood_lower for k in ["под стимуляторами", "взвинчен", "stimulated"]):
        lines.append(
            "ВАЖНО (Под стимуляторами): Персонаж под воздействием сильных стимуляторов. "
            "Мысли несутся с бешеной скоростью, обостренное восприятие, бурлящая энергия, мания величия или резкие порывы сделать всё и сразу прямо сейчас!"
        )
        lines.append("")
    elif any(k in mood_lower for k in ["под седацией", "замедлен", "заторможен", "sedated"]):
        lines.append(
            "ВАЖНО (Под седацией): Персонаж под действием успокоительных или седативных веществ. "
            "Мысли вязкие, медленные, реакция притуплена, ощущение расслабленной тяжести в теле и желание отключиться или спокойно залипнуть."
        )
        lines.append("")

    lines.append(
        f"Сформулируй короткую (1-2 предложения) спонтанную реплику внутреннего монолога {full_name} в эту конкретную секунду. Помни: мысль должна звучать прямо, живо, без вводных шаблонов вроде «Я думаю о...»!"
    )

    prompt = "\n".join(lines)
    log(f"Generated Context Prompt for {full_name}:\n{prompt}")
    return prompt


